// Generated by scripts/embed.mjs from packages/adapter-tanstack/templates. Do not edit.
export const TEMPLATES: Record<string, string> = {
  ".dockerignore": "node_modules\ndist\ndata\n.git\n.env\n*.local\n",
  ".gitignore": "node_modules\ndist\ndata\n.env\n*.local\n.tanstack\n",
  ".mcp.json": "{\n  \"mcpServers\": {\n    \"smithable\": { \"command\": \"smithable\", \"args\": [\"mcp\"] }\n  }\n}\n",
  "AGENTS.md": "# Working on this app\n\nThis app is generated by [Smithable](https://smithable.ai) from `smithable.yml` (what it does), `smithable.auth.yml` (sign-in, roles, access) and `smithable.content.yml` (visible text). The code follows the usual TanStack Start, Drizzle and shadcn/ui idioms, but most of it is regenerated on every change.\n\n## Change the app through Smithable, not by editing files\n\n- **With MCP** (`.mcp.json` registers `smithable mcp`): call `smithable_context` with the request to see the parts of the app it is about, then an operation tool such as `smithable_add_field`. Each operation checks the change, regenerates the code, migrates the database and commits a checkpoint; `smithable_undo` reverts it. `smithable_inspect` shows any concept with its files and tests.\n- **Without MCP:** `smithable context \"<request>\"`, `smithable op <operation> …` (`smithable op` lists them), `smithable inspect <concept>`, `smithable undo`.\n- You rarely need to read the source to make a change.\n- When no operation can make a page look or behave as asked, `smithable_customize_page` (or `smithable customize page:<page>`) gives it its own component in `src/custom/pages/`, starting as a copy of the generated one. Edit that file, never the generated route.\n\n## Who owns which files\n\n| Path | Owner | |\n|---|---|---|\n| `smithable*.yml` | The project | Changed through operations |\n| `src/generated/`, `src/db/schema.ts`, `src/db/seed.ts`, generated routes, `src/lib/auth.ts` | Smithable | Overwritten on every change: never edit |\n| `src/kit/`, `src/components/ui/` | Smithable | Updated with Smithable: never edit; copy into `src/custom/` to change |\n| `src/custom/` | You | Never touched by Smithable |\n| `drizzle/` | History | Migrations; never edit old ones |\n\n## Custom code\n\n- A custom action's implementation is `src/custom/actions/<action>.ts`. Its input and output types come from the spec.\n- Read and write data with the functions in `src/generated/<model>.server.ts`: they apply the access rules. The signed-in user is `await currentViewer()` from `#/lib/viewer.server`.\n- Mark code that implements a rule with `// implements rule <id>`, and its test with `test(\"rule <id>: …\")`, then run `smithable test`: `smithable inspect` shows each rule's status.\n",
  "CLAUDE.md": "@AGENTS.md\n",
  "Dockerfile": "# Builds the app into a small image. Irreplaceable state lives in the /data volume.\nFROM node:24-slim AS build\nWORKDIR /app\nRUN corepack enable\nCOPY package.json pnpm-lock.yaml pnpm-workspace.yaml ./\nRUN pnpm install --frozen-lockfile\nCOPY . .\nRUN pnpm build && pnpm prune --prod && mkdir -p /data\n\n# A minimal runtime (Node and little else, no shell), as a user without root rights: fewer\n# packages means fewer vulnerabilities to patch (smithable security --level release checks it).\n# Pinned by digest, so a build is reproducible; a Smithable update moves the pin.\nFROM gcr.io/distroless/nodejs24-debian13:nonroot@sha256:9eeb7f5887d0e239e78264b06f7f11d2e14be534050481803a9e4728fcdd278e\nWORKDIR /app\nENV NODE_ENV=production PORT=3000 DATA_DIR=/data\nCOPY --from=build /app/package.json ./\nCOPY --from=build /app/node_modules ./node_modules\nCOPY --from=build /app/dist ./dist\nCOPY --from=build /app/drizzle ./drizzle\nCOPY --from=build /app/server.mjs ./\n# Third-party notices travel with the image (LICENSES/README.md).\nCOPY --from=build /app/LICENSES ./LICENSES\nCOPY --from=build --chown=nonroot:nonroot /data /data\nVOLUME /data\nEXPOSE 3000\nHEALTHCHECK CMD [\"/nodejs/bin/node\", \"-e\", \"fetch('http://localhost:' + process.env.PORT + '/health').then((r) => process.exit(r.ok ? 0 : 1), () => process.exit(1))\"]\nCMD [\"server.mjs\"]\n",
  "LICENSES/README.md": "# Third-party notices\n\nThis folder keeps the license texts of code copied into the app's source, so they travel with\nevery copy of the app, in the container image too. Libraries installed from npm carry their\nown licenses in `node_modules/`.\n\n- `shadcn-ui.txt`: the components in `src/components/ui/` (MIT).\n\nThe app kit in `src/kit/` comes under the Zero-Clause BSD license, which asks nothing of you;\nthe generated code is yours.\n",
  "LICENSES/shadcn-ui.txt": "The files in src/components/ui/ are shadcn/ui's (https://ui.shadcn.com), copied into this app as\nshadcn's own CLI does, and licensed as follows.\n\nMIT License\n\nCopyright (c) 2023 shadcn\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n",
  "drizzle.config.ts": "import { defineConfig } from \"drizzle-kit\";\n\nexport default defineConfig({\n  dialect: \"sqlite\",\n  schema: \"./src/db/schema.ts\",\n  out: \"./drizzle\",\n  casing: \"snake_case\",\n  dbCredentials: { url: `${process.env.DATA_DIR ?? \"data\"}/db/app.db` },\n});\n",
  "playwright.config.ts": "import { rmSync } from \"node:fs\";\nimport { defineConfig, devices } from \"@playwright/test\";\n\n// The smoke tests run the app on port 3100 (or SMOKE_PORT) with their own, empty database.\nrmSync(\"data/smoke\", { recursive: true, force: true });\nconst port = Number(process.env.SMOKE_PORT ?? 3100);\n\nexport default defineConfig({\n  testDir: \"tests\",\n  fullyParallel: false,\n  workers: 1,\n  // A page's first visit compiles it; on a busy machine that alone can take half a minute.\n  timeout: 60_000,\n  reporter: \"list\",\n  use: { baseURL: `http://localhost:${port}` },\n  projects: [{ name: \"chromium\", use: { ...devices[\"Desktop Chrome\"] } }],\n  webServer: {\n    // Vite itself, not through pnpm, so it stops when the tests end.\n    command: `vite dev --port ${port} --strictPort`,\n    url: `http://localhost:${port}/health`,\n    env: { DATA_DIR: \"data/smoke\" },\n    reuseExistingServer: false,\n    timeout: 120_000,\n  },\n});\n",
  "pnpm-workspace.yaml": "allowBuilds:\n  better-sqlite3: true\n  esbuild: true\n",
  "server.mjs": "// Smithable app kit: the production server (`pnpm start`, and the container). It serves the\n// built files and the app, and gives every response the security headers; pages also get a\n// Content Security Policy from the root route (src/kit/security.ts).\nimport { serve } from \"srvx\";\nimport { staticMiddleware } from \"srvx/static\";\nimport app from \"./dist/server/server.js\";\n\nconst HEADERS = {\n  \"X-Content-Type-Options\": \"nosniff\",\n  \"X-Frame-Options\": \"DENY\",\n  \"Referrer-Policy\": \"strict-origin-when-cross-origin\",\n  \"Permissions-Policy\": \"camera=(), microphone=(), geolocation=(), payment=(), usb=()\",\n  \"Cross-Origin-Opener-Policy\": \"same-origin\",\n  \"Cross-Origin-Resource-Policy\": \"same-origin\",\n  \"Cross-Origin-Embedder-Policy\": \"require-corp\",\n};\n\n/**\n * Changes (anything but GET and HEAD) per address: a burst of 60, then one a second. Enough\n * for anyone using the app, and a brake on a script filling a public form.\n */\nconst BURST = 60;\nconst TRUST_PROXY = process.env.TRUST_PROXY === \"1\";\nconst buckets = new Map();\nfunction allowed(request) {\n  if (request.method === \"GET\" || request.method === \"HEAD\") return true;\n  // Only behind a proxy that says who the visitor is (TRUST_PROXY=1, e.g. the hosted service)\n  // is X-Forwarded-For believed, and then only its last hop, the one that proxy added; anyone\n  // else could send a new address with every request.\n  const forwarded =\n    TRUST_PROXY && request.headers.get(\"x-forwarded-for\")?.split(\",\").at(-1)?.trim();\n  const address = forwarded || request.ip || \"\";\n  const now = Date.now() / 1000;\n  const bucket = buckets.get(address) ?? { tokens: BURST, at: now };\n  bucket.tokens = Math.min(BURST, bucket.tokens + (now - bucket.at));\n  bucket.at = now;\n  buckets.set(address, bucket);\n  if (buckets.size > 10_000)\n    for (const [key, b] of buckets) if (b.tokens >= BURST) buckets.delete(key);\n  if (bucket.tokens < 1) return false;\n  bucket.tokens -= 1;\n  return true;\n}\n\nserve({\n  port: Number(process.env.PORT ?? 3000),\n  gracefulShutdown: true,\n  fetch: app.fetch,\n  middleware: [\n    async (request, next) => {\n      if (!allowed(request))\n        return new Response(\"Too many requests; try again in a moment.\", {\n          status: 429,\n          headers: { \"Retry-After\": \"5\", ...HEADERS },\n        });\n      const response = await next();\n      for (const [name, value] of Object.entries(HEADERS))\n        if (!response.headers.has(name)) response.headers.set(name, value);\n      return response;\n    },\n    staticMiddleware({ dir: new URL(\"./dist/client\", import.meta.url).pathname }),\n  ],\n});\n",
  "src/components/ui/badge.tsx": "import { cva, type VariantProps } from \"class-variance-authority\";\nimport type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nconst badgeVariants = cva(\n  \"inline-flex items-center rounded-md px-2 py-0.5 text-xs font-semibold whitespace-nowrap\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-accent text-accent-foreground\",\n        success: \"bg-success text-success-foreground\",\n        warning: \"bg-warning text-warning-foreground\",\n        danger: \"bg-destructive text-destructive-foreground\",\n      },\n    },\n    defaultVariants: { variant: \"default\" },\n  },\n);\n\nexport function Badge({\n  className,\n  variant,\n  ...props\n}: React.ComponentProps<\"span\"> & VariantProps<typeof badgeVariants>) {\n  return (\n    <span\n      data-tone={variant && variant !== \"default\" ? variant : \"neutral\"}\n      className={cn(badgeVariants({ variant, className }))}\n      {...props}\n    />\n  );\n}\n",
  "src/components/ui/button.tsx": "import { cva, type VariantProps } from \"class-variance-authority\";\nimport type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nconst buttonVariants = cva(\n  \"inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-(--button-radius) text-sm font-semibold transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background active:inset-ring-2 active:inset-ring-foreground/20 disabled:pointer-events-none disabled:border-transparent disabled:bg-muted disabled:text-muted-foreground disabled:shadow-none [&_svg]:pointer-events-none [&_svg]:size-5 [&_svg]:shrink-0\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground hover:bg-primary/90\",\n        destructive: \"bg-destructive text-destructive-foreground hover:bg-destructive/90\",\n        outline: \"border border-input bg-card hover:bg-accent hover:text-accent-foreground\",\n        secondary: \"bg-secondary text-secondary-foreground hover:bg-secondary/80\",\n        ghost: \"hover:bg-accent hover:text-accent-foreground\",\n      },\n      size: {\n        default: \"h-control px-4\",\n        sm: \"h-9 px-3 pointer-coarse:h-11\",\n        icon: \"size-control\",\n      },\n    },\n    defaultVariants: { variant: \"default\", size: \"default\" },\n  },\n);\n\nexport function Button({\n  className,\n  variant,\n  size,\n  ...props\n}: React.ComponentProps<\"button\"> & VariantProps<typeof buttonVariants>) {\n  return <button className={cn(buttonVariants({ variant, size, className }))} {...props} />;\n}\n\nexport { buttonVariants };\n",
  "src/components/ui/card.tsx": "import type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nexport function Card({ className, ...props }: React.ComponentProps<\"div\">) {\n  return (\n    <div\n      className={cn(\n        \"rounded-lg border-(length:--card-border) border-(--card-border-color) bg-card text-card-foreground shadow-card\",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n",
  "src/components/ui/input.tsx": "import type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\n// 16 px text on phones, so browsers do not zoom into a field being edited.\nexport const fieldClassName =\n  \"w-full min-w-0 rounded-md border border-input bg-card px-3 text-base text-foreground outline-none transition-[color,box-shadow] placeholder:text-muted-foreground hover:border-foreground/40 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:bg-muted disabled:text-muted-foreground aria-invalid:border-destructive aria-invalid:border-2 md:text-sm\";\n\nexport function Input({ className, ...props }: React.ComponentProps<\"input\">) {\n  return <input className={cn(fieldClassName, \"h-control\", className)} {...props} />;\n}\n\nexport function Textarea({ className, ...props }: React.ComponentProps<\"textarea\">) {\n  return <textarea className={cn(fieldClassName, \"min-h-24 py-2\", className)} {...props} />;\n}\n\nexport function NativeSelect({ className, ...props }: React.ComponentProps<\"select\">) {\n  return <select className={cn(fieldClassName, \"h-control pr-8\", className)} {...props} />;\n}\n\nexport function Checkbox({ className, ...props }: React.ComponentProps<\"input\">) {\n  return (\n    <input\n      type=\"checkbox\"\n      className={cn(\n        \"size-5 rounded accent-primary outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background\",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n\nexport function Label({\n  className,\n  htmlFor,\n  children,\n  ...props\n}: React.ComponentProps<\"label\"> & { htmlFor: string }) {\n  return (\n    <label\n      htmlFor={htmlFor}\n      className={cn(\"text-sm font-semibold leading-5\", className)}\n      {...props}\n    >\n      {children}\n    </label>\n  );\n}\n",
  "src/components/ui/table.tsx": "import type * as React from \"react\";\nimport { cn } from \"#/lib/utils\";\n\nexport function Table({ className, ...props }: React.ComponentProps<\"table\">) {\n  return (\n    <div className=\"relative w-full overflow-x-auto\">\n      <table className={cn(\"w-full caption-bottom text-sm\", className)} {...props} />\n    </div>\n  );\n}\n\nexport function TableHeader({ className, ...props }: React.ComponentProps<\"thead\">) {\n  return <thead className={cn(\"bg-muted [&_tr]:border-b\", className)} {...props} />;\n}\n\nexport function TableBody({ className, ...props }: React.ComponentProps<\"tbody\">) {\n  return <tbody className={cn(\"[&_tr:last-child]:border-0\", className)} {...props} />;\n}\n\nexport function TableRow({ className, ...props }: React.ComponentProps<\"tr\">) {\n  return <tr className={cn(\"border-b transition-colors hover:bg-accent\", className)} {...props} />;\n}\n\nexport function TableHead({ className, ...props }: React.ComponentProps<\"th\">) {\n  return (\n    <th\n      className={cn(\n        \"h-11 px-cell text-left align-middle text-[11px] leading-4 font-semibold uppercase tracking-wide text-muted-foreground\",\n        className,\n      )}\n      {...props}\n    />\n  );\n}\n\nexport function TableCell({ className, ...props }: React.ComponentProps<\"td\">) {\n  return <td className={cn(\"h-row px-cell py-2 align-middle\", className)} {...props} />;\n}\n",
  "src/db/index.ts": "// Smithable app kit: opens the SQLite database under DATA_DIR and applies pending migrations.\nimport { mkdirSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport Database from \"better-sqlite3\";\nimport { drizzle } from \"drizzle-orm/better-sqlite3\";\nimport { migrate } from \"drizzle-orm/better-sqlite3/migrator\";\nimport * as schema from \"./schema\";\n\nconst dataDir = process.env.DATA_DIR ?? \"data\";\nmkdirSync(join(dataDir, \"db\"), { recursive: true });\n\nconst sqlite = new Database(join(dataDir, \"db\", \"app.db\"));\nsqlite.pragma(\"journal_mode = WAL\");\nsqlite.pragma(\"foreign_keys = ON\");\n\nexport const db = drizzle(sqlite, { schema, casing: \"snake_case\" });\n\n// Some changes rebuild a table (e.g. making a column required). SQLite only lets a migration do\n// that with foreign keys off, and ignores switching them off inside the migration's transaction;\n// so they are off around it, and every reference is checked afterwards.\nsqlite.pragma(\"foreign_keys = OFF\");\ntry {\n  migrate(db, { migrationsFolder: \"drizzle\" });\n  const broken = sqlite.pragma(\"foreign_key_check\") as unknown[];\n  if (broken.length > 0) throw new Error(`A migration left ${broken.length} broken references.`);\n} finally {\n  sqlite.pragma(\"foreign_keys = ON\");\n}\n",
  "src/kit/AppShell.tsx": "// Smithable app kit: the application frame with navigation menus and the signed-in user.\nimport { Link, type LinkProps } from \"@tanstack/react-router\";\nimport { LogOut, type LucideIcon, Menu, X } from \"lucide-react\";\nimport { useRef } from \"react\";\nimport { allows, type Rule, type Viewer } from \"./access\";\nimport { textMarker } from \"./model\";\n\nexport interface MenuUi {\n  name: string;\n  label?: string;\n  /** Only pages the viewer may open are shown. */\n  items: { to: LinkProps[\"to\"]; label: string; icon?: LucideIcon; access: Rule }[];\n}\n\ninterface ShellProps {\n  appName: string;\n  /** The page at \"/\", if the app has one: the name leads there when the viewer may open it. */\n  home?: { to: LinkProps[\"to\"]; access: Rule };\n  menus: MenuUi[];\n  viewer: Viewer | null;\n  /** Without it the app has no sign-in. */\n  onSignOut?: () => Promise<void>;\n}\n\n// Links and buttons on the sidebar's own colors, with 44 px targets.\nconst sidebarItem =\n  \"flex min-h-11 items-center gap-3 rounded-md px-3 text-sm font-medium transition-colors hover:bg-accent hover:text-accent-foreground outline-none focus-visible:ring-2 focus-visible:ring-sidebar-foreground\";\n\nexport function AppShell({ children, ...shell }: ShellProps & { children: React.ReactNode }) {\n  const drawer = useRef<HTMLDialogElement>(null);\n  return (\n    <div data-kit=\"app-shell\" className=\"min-h-screen lg:flex\">\n      {/* Desktop: a sidebar. */}\n      <aside className=\"hidden border-r bg-sidebar text-sidebar-foreground lg:sticky lg:top-0 lg:flex lg:h-screen lg:w-56 lg:shrink-0 lg:flex-col\">\n        <p className=\"px-6 pt-7 pb-6 text-2xl font-bold\">\n          <AppName {...shell} />\n        </p>\n        <Navigation {...shell} />\n      </aside>\n      {/* Phones and tablets: a header whose menu opens the same navigation as a drawer. */}\n      <header\n        data-part=\"header\"\n        className=\"sticky top-0 z-10 flex h-18 items-center gap-2 border-b bg-sidebar px-2 text-sidebar-foreground lg:hidden\"\n      >\n        <button\n          type=\"button\"\n          aria-label=\"Open menu\"\n          className={`${sidebarItem} size-11 justify-center px-0`}\n          onClick={() => drawer.current?.showModal()}\n        >\n          <Menu aria-hidden className=\"size-6\" />\n        </button>\n        <p className=\"min-w-0 truncate text-lg font-bold\">\n          <AppName {...shell} />\n        </p>\n      </header>\n      <dialog\n        ref={drawer}\n        aria-label=\"Menu\"\n        className=\"m-0 h-dvh max-h-none w-72 max-w-[85vw] flex-col bg-sidebar text-sidebar-foreground backdrop:bg-black/50 open:flex lg:hidden\"\n      >\n        <div className=\"flex h-18 shrink-0 items-center justify-between gap-2 pr-2 pl-5\">\n          <p className=\"min-w-0 truncate text-lg font-bold\">\n            <AppName {...shell} onNavigate={() => drawer.current?.close()} />\n          </p>\n          <button\n            type=\"button\"\n            aria-label=\"Close menu\"\n            className={`${sidebarItem} size-11 justify-center px-0`}\n            onClick={() => drawer.current?.close()}\n          >\n            <X aria-hidden className=\"size-6\" />\n          </button>\n        </div>\n        <Navigation {...shell} onNavigate={() => drawer.current?.close()} />\n      </dialog>\n      <main className=\"min-w-0 flex-1 px-5 py-6 lg:px-9 lg:py-8\">{children}</main>\n    </div>\n  );\n}\n\n/** The app's name, a way back to its start: the page at \"/\", else the first the viewer may open. */\nfunction AppName({\n  appName,\n  home,\n  menus,\n  viewer,\n  onNavigate,\n}: ShellProps & { onNavigate?: () => void }) {\n  const start =\n    home && allows(home.access, viewer)\n      ? home.to\n      : menus.flatMap((m) => m.items).find((item) => allows(item.access, viewer))?.to;\n  if (!start) return appName;\n  return (\n    <Link\n      to={start}\n      onClick={onNavigate}\n      className=\"rounded-sm underline-offset-4 outline-none hover:underline focus-visible:ring-2 focus-visible:ring-sidebar-foreground\"\n    >\n      {appName}\n    </Link>\n  );\n}\n\nfunction Navigation({\n  menus,\n  viewer,\n  onSignOut,\n  onNavigate,\n}: ShellProps & { onNavigate?: () => void }) {\n  return (\n    <>\n      <nav\n        aria-label=\"Main\"\n        data-kit=\"nav\"\n        className=\"flex flex-1 flex-col gap-5 overflow-y-auto px-3 pb-4\"\n      >\n        {menus.map((menu) => {\n          const items = menu.items.filter((item) => allows(item.access, viewer));\n          if (items.length === 0) return null;\n          return (\n            <div key={menu.name} className=\"flex flex-col gap-1\">\n              {menu.label && (\n                <p className=\"px-3 pb-1 text-xs font-semibold uppercase tracking-wide\">\n                  {menu.label}\n                </p>\n              )}\n              {items.map((item) => (\n                <Link\n                  key={String(item.to)}\n                  to={item.to}\n                  onClick={onNavigate}\n                  className={sidebarItem}\n                  activeProps={{\n                    className:\n                      \"bg-primary font-semibold text-primary-foreground hover:bg-primary hover:text-primary-foreground\",\n                  }}\n                >\n                  {item.icon && <item.icon aria-hidden className=\"size-5 shrink-0\" />}\n                  {item.label}\n                </Link>\n              ))}\n            </div>\n          );\n        })}\n      </nav>\n      {onSignOut && (\n        <div className=\"mx-3 border-t border-sidebar-foreground/30 px-3 py-4 text-sm\">\n          {viewer ? (\n            <>\n              <p className=\"truncate font-semibold\" title={viewer.email}>\n                {viewer.name}\n              </p>\n              <p className=\"capitalize\">{viewer.role}</p>\n              <button type=\"button\" onClick={onSignOut} className={`${sidebarItem} -mx-3 mt-2`}>\n                <LogOut aria-hidden className=\"size-5\" />\n                Sign out\n              </button>\n            </>\n          ) : (\n            <a href=\"/sign-in\" className={`${sidebarItem} -mx-3`}>\n              Sign in\n            </a>\n          )}\n        </div>\n      )}\n    </>\n  );\n}\n\n/** Shown while a page's data loads for longer than a moment: the shape of a page, no words. */\nexport function Loading() {\n  return (\n    <div\n      aria-busy=\"true\"\n      aria-label=\"Loading\"\n      className=\"max-w-3xl animate-pulse space-y-6\"\n      role=\"status\"\n    >\n      <div className=\"h-8 w-1/3 rounded-md bg-muted\" />\n      <div className=\"space-y-3\">\n        <div className=\"h-row rounded-md bg-muted\" />\n        <div className=\"h-row rounded-md bg-muted\" />\n        <div className=\"h-row rounded-md bg-muted\" />\n      </div>\n    </div>\n  );\n}\n\n/** Shown instead of a page that failed, e.g. \"You are not allowed to do this.\" */\nexport function ErrorNotice({ title, message }: { title: string; message?: string }) {\n  return (\n    <div className=\"max-w-xl\">\n      <PageHeader title={title} />\n      {message && <p className=\"text-muted-foreground\">{message}</p>}\n    </div>\n  );\n}\n\nexport function PageHeader({\n  title,\n  subtitle,\n  actions,\n  page,\n}: {\n  title: string;\n  subtitle?: string;\n  actions?: React.ReactNode;\n  /** The page's name in the spec: its texts can then be changed in the preview. */\n  page?: string;\n}) {\n  return (\n    <div\n      data-part=\"header\"\n      className=\"mb-6 flex flex-col gap-4 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between\"\n    >\n      <div className=\"min-w-0\">\n        <h1\n          data-part=\"title\"\n          className=\"break-words text-[28px] leading-9 font-bold lg:text-[32px] lg:leading-10\"\n          {...(page ? textMarker(`pages.${page}.title`) : {})}\n        >\n          {title}\n        </h1>\n        {subtitle && (\n          <p\n            className=\"mt-1 text-muted-foreground\"\n            {...(page ? textMarker(`pages.${page}.subtitle`) : {})}\n          >\n            {subtitle}\n          </p>\n        )}\n      </div>\n      {actions && (\n        <div data-part=\"actions\" className=\"flex flex-wrap items-center gap-2 max-sm:[&>*]:flex-1\">\n          {actions}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/kit/Articles.tsx": "// Smithable app kit: articles (a blog, news). A list newest first, and an article with its\n// picture, date, author and formatted body, and links to the ones before and after it.\n// To change them, copy this file into src/custom/components/ and edit the copy.\nimport { Card } from \"#/components/ui/card\";\nimport { MarkdownText } from \"./Markdown\";\n\nexport interface ArticleCard {\n  href: string;\n  title: string;\n  summary?: string;\n  date?: string;\n  picture?: { src: string; alt: string; width: number; height: number };\n}\n\nexport function ArticleList({\n  items,\n  older,\n  newer,\n}: {\n  items: ArticleCard[];\n  /** Addresses of the next and previous pages of the list, when there are more. */\n  older?: string;\n  newer?: string;\n}) {\n  if (!items.length) return <p className=\"text-muted-foreground\">Nothing here yet.</p>;\n  return (\n    <div data-kit=\"articles\" className=\"space-y-8\">\n      <ul className=\"grid gap-6 sm:grid-cols-2 lg:grid-cols-3\">\n        {items.map((item) => (\n          <li key={item.href} data-part=\"row\">\n            <Card className=\"relative h-full overflow-hidden hover:bg-accent/40\">\n              {item.picture && (\n                <img\n                  src={item.picture.src}\n                  alt={item.picture.alt}\n                  width={item.picture.width}\n                  height={item.picture.height}\n                  loading=\"lazy\"\n                  className=\"aspect-[3/2] w-full object-cover\"\n                />\n              )}\n              <div className=\"space-y-2 p-card\">\n                {item.date && <p className=\"text-sm text-muted-foreground\">{item.date}</p>}\n                <h2 className=\"text-lg font-semibold\">\n                  {/* The whole card opens the article; the link is the title. */}\n                  <a\n                    href={item.href}\n                    className=\"outline-none after:absolute after:inset-0 focus-visible:underline\"\n                  >\n                    {item.title}\n                  </a>\n                </h2>\n                {item.summary && <p className=\"text-muted-foreground\">{item.summary}</p>}\n              </div>\n            </Card>\n          </li>\n        ))}\n      </ul>\n      {(older || newer) && (\n        <nav aria-label=\"More articles\" className=\"flex justify-between gap-4\">\n          {newer ? (\n            <a href={newer} className=\"font-medium text-primary\">\n              Newer articles\n            </a>\n          ) : (\n            <span />\n          )}\n          {older && (\n            <a href={older} className=\"font-medium text-primary\">\n              Older articles\n            </a>\n          )}\n        </nav>\n      )}\n    </div>\n  );\n}\n\nexport function ArticleView({\n  title,\n  date,\n  author,\n  picture,\n  body,\n  previous,\n  next,\n  edit,\n}: {\n  title: string;\n  date?: string;\n  author?: string;\n  picture?: ArticleCard[\"picture\"];\n  body: string;\n  previous?: { href: string; title: string };\n  next?: { href: string; title: string };\n  /** Where those who may change it edit the article. */\n  edit?: string;\n}) {\n  return (\n    <article data-kit=\"article\" className=\"mx-auto max-w-3xl space-y-6\">\n      {picture && (\n        <img\n          src={picture.src}\n          alt={picture.alt}\n          width={picture.width}\n          height={picture.height}\n          fetchPriority=\"high\"\n          className=\"aspect-[3/2] w-full rounded-xl object-cover\"\n        />\n      )}\n      <header className=\"space-y-2\">\n        <h1 data-part=\"title\" className=\"text-3xl leading-tight font-bold sm:text-4xl\">\n          {title}\n        </h1>\n        {(date || author) && (\n          <p className=\"text-muted-foreground\">{[date, author].filter(Boolean).join(\" · \")}</p>\n        )}\n        {edit && (\n          <a href={edit} className=\"text-sm font-medium text-primary\">\n            Edit\n          </a>\n        )}\n      </header>\n      <div className=\"text-lg\">\n        <MarkdownText text={body} />\n      </div>\n      {(previous || next) && (\n        <nav aria-label=\"Other articles\" className=\"flex justify-between gap-4 border-t pt-6\">\n          {previous ? (\n            <a href={previous.href} className=\"text-primary\">\n              ← {previous.title}\n            </a>\n          ) : (\n            <span />\n          )}\n          {next && (\n            <a href={next.href} className=\"text-right text-primary\">\n              {next.title} →\n            </a>\n          )}\n        </nav>\n      )}\n    </article>\n  );\n}\n",
  "src/kit/Calculator.tsx": "// Smithable app kit: a calculator (docs/design/calculator.md). A form of inputs whose results\n// are computed as you type and stored nowhere: the same fields, inputs and formulas as a\n// record's form, without a record. To change it, copy this file into src/custom/components/\n// and edit the copy.\nimport { Calculator as CalculatorIcon } from \"lucide-react\";\nimport { useState } from \"react\";\nimport { Card } from \"#/components/ui/card\";\nimport { Label } from \"#/components/ui/input\";\nimport { cn } from \"#/lib/utils\";\nimport { FieldInput } from \"./FieldInput\";\nimport { formatValue, fromInput, toInput } from \"./format\";\nimport type { AppUi, ModelUi } from \"./model\";\n\nexport function Calculator({\n  ui,\n  app,\n  resultsTitle = \"Results\",\n  layout = \"beside\",\n}: {\n  ui: ModelUi;\n  app: AppUi;\n  resultsTitle?: string;\n  /** Where the results go on a wide screen (smithable.ux.yml); a phone shows them below. */\n  layout?: \"beside\" | \"below\";\n}) {\n  const inputs = ui.fields.filter((f) => !f.computed);\n  const results = ui.fields.filter((f) => f.computed);\n  const [values, setValues] = useState<Record<string, string | boolean>>(() =>\n    Object.fromEntries(inputs.map((f) => [f.name, toInput(f, f.default ?? null, app.timeZone)])),\n  );\n  const entered = Object.fromEntries(\n    inputs.map((f) => [f.name, fromInput(f, values[f.name] ?? \"\", app.timeZone)]),\n  );\n  const computed = ui.compute?.(entered) ?? {};\n  return (\n    <div\n      data-kit=\"calculator\"\n      className={cn(\n        \"grid gap-6\",\n        layout === \"beside\" && \"lg:grid-cols-[minmax(0,3fr)_minmax(0,2fr)]\",\n      )}\n    >\n      <Card className=\"space-y-6 p-card\">\n        {inputs.map((field) => {\n          const id = `calc-${field.name}`;\n          const inline = field.kind === \"bool\";\n          return (\n            <div key={field.name} className={inline ? \"flex items-center gap-3\" : \"space-y-2\"}>\n              {!inline && <Label htmlFor={id}>{field.label}</Label>}\n              <FieldInput\n                field={field}\n                id={id}\n                value={values[field.name] ?? \"\"}\n                invalid={false}\n                describedBy={field.help ? `${id}-help` : undefined}\n                onChange={(value) => setValues((v) => ({ ...v, [field.name]: value }))}\n              />\n              {inline && <Label htmlFor={id}>{field.label}</Label>}\n              {field.help && (\n                <p id={`${id}-help`} className=\"text-sm text-muted-foreground\">\n                  {field.help}\n                </p>\n              )}\n            </div>\n          );\n        })}\n      </Card>\n      <Card data-part=\"results\" className=\"space-y-4 p-card lg:self-start\" aria-live=\"polite\">\n        <h2 className=\"flex items-center gap-2 text-lg font-semibold\">\n          <CalculatorIcon aria-hidden className=\"size-5 text-muted-foreground\" />\n          {resultsTitle}\n        </h2>\n        <dl className=\"space-y-3\">\n          {results.map((field) => (\n            <div key={field.name} className=\"flex items-baseline justify-between gap-4\">\n              <dt className=\"text-sm text-muted-foreground\">{field.label}</dt>\n              <dd className=\"text-xl font-semibold tabular-nums\">\n                {formatValue(field, computed[field.name], app)}\n              </dd>\n            </div>\n          ))}\n        </dl>\n      </Card>\n    </div>\n  );\n}\n",
  "src/kit/Calendar.tsx": "// Smithable app kit: a calendar of records by week or month, in the app's time zone.\n// Each day is a section with its records as a list; on wide screens the week's days become\n// columns with the records as blocks from their start to their end, overlapping ones side by\n// side. The list is the content and the grid only its layout, so screen readers get one list\n// per day. To change it, copy this file into src/custom/components/ and edit the copy.\nimport { ChevronLeft, ChevronRight } from \"lucide-react\";\nimport { useRef, useState } from \"react\";\nimport { Button } from \"#/components/ui/button\";\nimport { instantOf, wallTime } from \"./zoned\";\n\n/** Where a calendar is: a week (`2026-W40`) or a month (`2026-10`), as in the page's address. */\nexport type CalendarSearch = { week?: string; month?: string };\n\nexport interface CalendarItem {\n  id: number;\n  start: Date | string;\n  end: Date | string;\n  title: string;\n}\n\nconst DAY = 86_400_000;\nconst day = (text: string) => new Date(`${text}T00:00:00Z`);\nconst iso = (date: Date) => date.toISOString().slice(0, 10);\nconst addDays = (text: string, n: number) => iso(new Date(day(text).getTime() + n * DAY));\n/** Monday of the week a date is in. */\nconst monday = (text: string) => addDays(text, -((day(text).getUTCDay() + 6) % 7));\n\n/** The ISO week of a date, e.g. 2026-W40 (the week with the year's first Thursday is week 1). */\nfunction isoWeek(text: string): string {\n  const thursday = addDays(monday(text), 3);\n  const year = thursday.slice(0, 4);\n  const first = monday(addDays(`${year}-01-04`, 0));\n  const week = Math.round((day(monday(text)).getTime() - day(first).getTime()) / (7 * DAY)) + 1;\n  return `${year}-W${String(week).padStart(2, \"0\")}`;\n}\n\n/** The Monday of an ISO week. */\nfunction weekStart(week: string): string {\n  const [year, n] = week.split(\"-W\");\n  return addDays(monday(`${year}-01-04`), (Number(n) - 1) * 7);\n}\n\n/**\n * What a calendar shows for its address: the days (a week, or the month's full weeks), the range\n * of instants to load (with a day on each side, for records crossing midnight), its heading and\n * where Previous, Today and Next and the other view go.\n */\nexport function calendarRange(search: CalendarSearch, timeZone?: string) {\n  const today = wallTime(new Date(), timeZone).slice(0, 10);\n  const view: \"week\" | \"month\" = search.month ? \"month\" : \"week\";\n  let days: string[];\n  let label: string;\n  let prev: CalendarSearch;\n  let next: CalendarSearch;\n  const heading = (options: Intl.DateTimeFormatOptions, text: string) =>\n    new Intl.DateTimeFormat(undefined, { ...options, timeZone: \"UTC\" }).format(day(text));\n  if (view === \"month\") {\n    const month = search.month as string;\n    const first = `${month}-01`;\n    const last = addDays(`${addDays(first, 31).slice(0, 7)}-01`, -1);\n    const start = monday(first);\n    const end = addDays(monday(last), 6);\n    days = Array.from({ length: (day(end).getTime() - day(start).getTime()) / DAY + 1 }, (_, i) =>\n      addDays(start, i),\n    );\n    label = heading({ month: \"long\", year: \"numeric\" }, first);\n    prev = { month: addDays(first, -1).slice(0, 7) };\n    next = { month: addDays(last, 1).slice(0, 7) };\n  } else {\n    const start = search.week ? weekStart(search.week) : monday(today);\n    days = Array.from({ length: 7 }, (_, i) => addDays(start, i));\n    label = `${heading({ day: \"numeric\", month: \"long\" }, start)} – ${heading(\n      { day: \"numeric\", month: \"long\", year: \"numeric\" },\n      addDays(start, 6),\n    )}`;\n    prev = { week: isoWeek(addDays(start, -7)) };\n    next = { week: isoWeek(addDays(start, 7)) };\n  }\n  const first = days[0] as string;\n  const last = days.at(-1) as string;\n  return {\n    view,\n    days,\n    label,\n    prev,\n    next,\n    today: view === \"month\" ? { month: today.slice(0, 7) } : { week: isoWeek(today) },\n    /** The other view, around the same days. */\n    other:\n      view === \"month\"\n        ? { week: isoWeek(first < today && today <= last ? today : (days[7] ?? first)) }\n        : { month: (days[3] as string).slice(0, 7) },\n    month: view === \"month\" ? (search.month as string) : undefined,\n    from: instantOf(`${addDays(first, -1)}T00:00`, timeZone),\n    to: instantOf(`${addDays(last, 2)}T00:00`, timeZone),\n  };\n}\n\ninterface Placed extends CalendarItem {\n  day: string;\n  /** Minutes after midnight, in the app's time zone. */\n  from: number;\n  to: number;\n  column: number;\n  columns: number;\n}\n\n/** A day's records with their columns: overlapping ones side by side (records sorted by start). */\nfunction place(items: Placed[]): Placed[] {\n  const sorted = [...items].sort((a, b) => a.from - b.from || b.to - a.to);\n  let group: Placed[] = [];\n  let groupEnd = -1;\n  const close = () => {\n    const columns = Math.max(0, ...group.map((p) => p.column)) + 1;\n    for (const p of group) p.columns = columns;\n    group = [];\n  };\n  for (const item of sorted) {\n    if (item.from >= groupEnd) {\n      close();\n      groupEnd = -1;\n    }\n    const busy = new Set(group.filter((p) => p.to > item.from).map((p) => p.column));\n    let column = 0;\n    while (busy.has(column)) column++;\n    item.column = column;\n    group.push(item);\n    groupEnd = Math.max(groupEnd, item.to);\n  }\n  close();\n  return sorted;\n}\n\nconst minutes = (wall: string) => Number(wall.slice(11, 13)) * 60 + Number(wall.slice(14, 16));\nconst clock = (m: number) =>\n  `${String(Math.floor(m / 60)).padStart(2, \"0\")}:${String(m % 60).padStart(2, \"0\")}`;\nconst HOUR = 3; // rem per hour on the week grid\n\nexport function Calendar({\n  search,\n  items,\n  timeZone,\n  dateOnly,\n  onNavigate,\n  onOpen,\n  onCreate,\n  newLabel,\n  details,\n}: {\n  search: CalendarSearch;\n  items: CalendarItem[];\n  timeZone?: string;\n  /** Records placed by a date, not a date and time: no hours. */\n  dateOnly: boolean;\n  onNavigate: (search: CalendarSearch) => void;\n  /** Opens a record on its own page; without it, a record's details open in a panel. */\n  onOpen?: (id: number) => void;\n  /** Starts a new record at a wall time (\"2026-09-30T09:00\"), for those who may create one. */\n  onCreate?: (start: string) => void;\n  /** \"New session\", for the empty hours' buttons. */\n  newLabel: string;\n  /** More about a record in its panel, e.g. its places and a Book button. */\n  details?: (id: number) => React.ReactNode;\n}) {\n  const range = calendarRange(search, timeZone);\n  const [shown, setShown] = useState<Placed>();\n  const panel = useRef<HTMLDialogElement>(null);\n  const today = wallTime(new Date(), timeZone).slice(0, 10);\n  const longDay = (text: string) =>\n    new Intl.DateTimeFormat(undefined, {\n      weekday: \"long\",\n      day: \"numeric\",\n      month: \"long\",\n      timeZone: \"UTC\",\n    }).format(day(text));\n  const shortDay = (text: string) =>\n    new Intl.DateTimeFormat(undefined, {\n      weekday: \"short\",\n      day: \"numeric\",\n      timeZone: \"UTC\",\n    }).format(day(text));\n\n  // Each record on the day it starts, in the app's time zone.\n  const placed: Placed[] = items.map((item) => {\n    const start = wallTime(new Date(item.start), timeZone);\n    const end = wallTime(new Date(item.end), timeZone);\n    const sameDay = end.slice(0, 10) === start.slice(0, 10);\n    return {\n      ...item,\n      day: start.slice(0, 10),\n      from: dateOnly ? 0 : minutes(start),\n      to: dateOnly ? 24 * 60 : sameDay ? Math.max(minutes(end), minutes(start) + 15) : 24 * 60,\n      column: 0,\n      columns: 1,\n    };\n  });\n  const byDay = new Map(range.days.map((d) => [d, place(placed.filter((p) => p.day === d))]));\n  // Hours shown: 07:00 to 21:00, widened to the week's earliest and latest record.\n  const timed = !dateOnly && range.view === \"week\";\n  const inWeek = placed.filter((p) => byDay.has(p.day));\n  const firstHour = Math.min(7, ...inWeek.map((p) => Math.floor(p.from / 60)));\n  const lastHour = Math.max(21, ...inWeek.map((p) => Math.ceil(p.to / 60)));\n  const hours = Array.from({ length: lastHour - firstHour }, (_, i) => firstHour + i);\n  const span = (lastHour - firstHour) * 60;\n\n  const when = (p: Placed) =>\n    dateOnly\n      ? longDay(p.day)\n      : `${longDay(p.day)}, ${clock(p.from)}–${clock(Math.min(p.to, 24 * 60 - 1))}`;\n  const open = (p: Placed) => {\n    if (onOpen) return onOpen(p.id);\n    setShown(p);\n    panel.current?.showModal();\n  };\n\n  return (\n    <div data-kit=\"calendar\" className=\"space-y-4\">\n      <div className=\"flex flex-wrap items-center gap-2\">\n        <Button\n          type=\"button\"\n          variant=\"outline\"\n          aria-label=\"Previous\"\n          onClick={() => onNavigate(range.prev)}\n        >\n          <ChevronLeft aria-hidden className=\"size-4\" />\n        </Button>\n        <Button type=\"button\" variant=\"outline\" onClick={() => onNavigate(range.today)}>\n          Today\n        </Button>\n        <Button\n          type=\"button\"\n          variant=\"outline\"\n          aria-label=\"Next\"\n          onClick={() => onNavigate(range.next)}\n        >\n          <ChevronRight aria-hidden className=\"size-4\" />\n        </Button>\n        <h2 aria-live=\"polite\" className=\"mx-2 text-lg font-semibold\">\n          {range.label}\n        </h2>\n        <Button\n          type=\"button\"\n          variant=\"ghost\"\n          className=\"ml-auto\"\n          onClick={() => onNavigate(range.other)}\n        >\n          {range.view === \"week\" ? \"Month\" : \"Week\"}\n        </Button>\n      </div>\n\n      <div\n        className={\n          timed\n            ? \"md:grid md:grid-cols-[3rem_repeat(7,minmax(0,1fr))] md:gap-x-1\"\n            : \"md:grid md:grid-cols-7 md:gap-1\"\n        }\n      >\n        {timed && (\n          <div aria-hidden className=\"hidden md:block md:pt-10\">\n            {hours.map((h) => (\n              <div\n                key={h}\n                className=\"text-right text-xs text-muted-foreground\"\n                style={{ height: `${HOUR}rem` }}\n              >\n                {clock(h * 60)}\n              </div>\n            ))}\n          </div>\n        )}\n        {range.days.map((d) => {\n          const records = byDay.get(d) ?? [];\n          const outside = range.month !== undefined && !d.startsWith(range.month);\n          return (\n            <section\n              key={d}\n              aria-label={longDay(d)}\n              className={`border-b py-3 md:border md:border-border md:py-0 ${outside ? \"md:opacity-50\" : \"\"} ${range.view === \"month\" ? \"md:min-h-28 md:p-1\" : \"\"}`}\n            >\n              <h3\n                className={`text-sm font-medium md:flex md:h-10 md:items-center md:justify-center ${d === today ? \"text-primary\" : \"\"}`}\n              >\n                <span className=\"md:hidden\">{longDay(d)}</span>\n                <span className=\"hidden md:inline\">{shortDay(d)}</span>\n              </h3>\n              <div\n                className={timed ? \"relative md:h-[var(--grid)]\" : \"\"}\n                style={\n                  timed\n                    ? ({ \"--grid\": `${(span / 60) * HOUR}rem` } as React.CSSProperties)\n                    : undefined\n                }\n              >\n                {timed &&\n                  onCreate &&\n                  // Only hours no record overlaps: a block never hides part of a button.\n                  hours\n                    .filter((h) => !records.some((p) => p.from < (h + 1) * 60 && p.to > h * 60))\n                    .map((h) => (\n                      <button\n                        key={h}\n                        type=\"button\"\n                        aria-label={`${newLabel}, ${longDay(d)} at ${clock(h * 60)}`}\n                        className=\"absolute inset-x-0 hidden border-t border-border/50 hover:bg-muted md:block\"\n                        style={{\n                          top: `${((h - firstHour) * 60 * 100) / span}%`,\n                          height: `${HOUR}rem`,\n                        }}\n                        onClick={() => onCreate(`${d}T${clock(h * 60)}`)}\n                      />\n                    ))}\n                {records.length === 0 ? (\n                  <p className=\"text-sm text-muted-foreground md:sr-only\">Nothing</p>\n                ) : (\n                  <ol className=\"space-y-1 md:space-y-0\">\n                    {records.map((p) => (\n                      <li\n                        key={p.id}\n                        className={timed ? \"md:absolute md:px-0.5\" : \"md:mt-1\"}\n                        style={\n                          timed\n                            ? ({\n                                top: `${((p.from - firstHour * 60) * 100) / span}%`,\n                                height: `${((p.to - p.from) * 100) / span}%`,\n                                left: `${(p.column * 100) / p.columns}%`,\n                                width: `${100 / p.columns}%`,\n                              } as React.CSSProperties)\n                            : undefined\n                        }\n                      >\n                        <button\n                          type=\"button\"\n                          onClick={() => open(p)}\n                          className=\"block h-full w-full overflow-hidden rounded-md bg-primary/10 px-2 py-1 text-left text-sm text-foreground hover:bg-primary/20 md:text-xs\"\n                        >\n                          <span className=\"font-medium\">{p.title}</span>\n                          <span className=\"sr-only\">, {when(p)}</span>\n                          {!dateOnly && (\n                            <span aria-hidden className=\"block text-muted-foreground\">\n                              {clock(p.from)}\n                            </span>\n                          )}\n                        </button>\n                      </li>\n                    ))}\n                  </ol>\n                )}\n              </div>\n            </section>\n          );\n        })}\n      </div>\n\n      <dialog\n        ref={panel}\n        aria-labelledby=\"calendar-record\"\n        className=\"m-auto w-[calc(100%-2.5rem)] max-w-sm rounded-lg border bg-card p-card text-card-foreground backdrop:bg-black/50\"\n      >\n        {shown && (\n          <>\n            <h2 id=\"calendar-record\" className=\"text-lg font-semibold\">\n              {shown.title}\n            </h2>\n            <p className=\"mt-2 text-muted-foreground\">{when(shown)}</p>\n            {details && <div className=\"mt-4\">{details(shown.id)}</div>}\n          </>\n        )}\n        <div className=\"mt-6 flex justify-end\">\n          <Button type=\"button\" variant=\"outline\" onClick={() => panel.current?.close()}>\n            Close\n          </Button>\n        </div>\n      </dialog>\n    </div>\n  );\n}\n",
  "src/kit/Combobox.tsx": "// Smithable app kit: a searchable choice of a related record (the WAI-ARIA combobox pattern).\n// Type to filter, arrow keys to move, Enter to choose, Escape to close.\nimport { ChevronDown, X } from \"lucide-react\";\nimport { useId, useState } from \"react\";\nimport { fieldClassName } from \"#/components/ui/input\";\nimport { cn } from \"#/lib/utils\";\n\ninterface ComboboxProps {\n  id: string;\n  /** The chosen record's id as text, or \"\" for none. */\n  value: string;\n  options: { value: string | number; label: string }[];\n  required: boolean;\n  invalid: boolean;\n  describedBy?: string;\n  onChange: (value: string) => void;\n}\n\nexport function Combobox({\n  id,\n  value,\n  options,\n  required,\n  invalid,\n  describedBy,\n  onChange,\n}: ComboboxProps) {\n  const list = useId();\n  const labelOf = (v: string) => options.find((o) => String(o.value) === v)?.label ?? \"\";\n  const [text, setText] = useState(() => labelOf(value));\n  const [open, setOpen] = useState(false);\n  const [active, setActive] = useState(0);\n  const typed = text !== labelOf(value);\n  const shown = typed\n    ? options.filter((o) => o.label.toLowerCase().includes(text.trim().toLowerCase()))\n    : options;\n\n  const choose = (v: string) => {\n    onChange(v);\n    setText(labelOf(v));\n    setOpen(false);\n  };\n  const close = () => {\n    setOpen(false);\n    // Leaving the field: empty text clears an optional choice; otherwise the choice stays.\n    if (text.trim() === \"\" && !required) choose(\"\");\n    else setText(labelOf(value));\n  };\n  const onKeyDown = (event: React.KeyboardEvent) => {\n    if (event.key === \"ArrowDown\" || event.key === \"ArrowUp\") {\n      event.preventDefault();\n      if (!open) setOpen(true);\n      const step = event.key === \"ArrowDown\" ? 1 : -1;\n      setActive((i) => (shown.length ? (i + step + shown.length) % shown.length : 0));\n    } else if (event.key === \"Enter\" && open) {\n      event.preventDefault();\n      const option = shown[active];\n      if (option) choose(String(option.value));\n    } else if (event.key === \"Escape\" && open) {\n      event.preventDefault();\n      setOpen(false);\n      setText(labelOf(value));\n    }\n  };\n\n  return (\n    <div className=\"relative\">\n      <input\n        id={id}\n        role=\"combobox\"\n        aria-expanded={open}\n        aria-controls={list}\n        aria-autocomplete=\"list\"\n        aria-activedescendant={open && shown[active] ? `${list}-${active}` : undefined}\n        aria-invalid={invalid || undefined}\n        aria-describedby={describedBy}\n        autoComplete=\"off\"\n        placeholder=\"Search…\"\n        className={cn(fieldClassName, \"h-control pr-18\")}\n        value={text}\n        onChange={(e) => {\n          setText(e.target.value);\n          setActive(0);\n          setOpen(true);\n        }}\n        onFocus={() => setOpen(true)}\n        onBlur={close}\n        onKeyDown={onKeyDown}\n      />\n      <div className=\"absolute inset-y-0 right-1 flex items-center\">\n        {value && !required && (\n          <button\n            type=\"button\"\n            aria-label=\"Clear\"\n            className=\"flex size-9 cursor-pointer items-center justify-center rounded-md text-muted-foreground hover:text-foreground\"\n            onMouseDown={(e) => e.preventDefault()}\n            onClick={() => choose(\"\")}\n          >\n            <X aria-hidden className=\"size-4\" />\n          </button>\n        )}\n        <ChevronDown\n          aria-hidden\n          className=\"pointer-events-none mr-2 size-4 text-muted-foreground\"\n        />\n      </div>\n      {open && (\n        <div className=\"absolute z-20 mt-1 max-h-64 w-full overflow-y-auto rounded-md border bg-card py-1 shadow-lg\">\n          <div id={list} role=\"listbox\" aria-label=\"Options\">\n            {shown.map((option, i) => (\n              <div\n                key={option.value}\n                id={`${list}-${i}`}\n                role=\"option\"\n                tabIndex={-1}\n                aria-selected={String(option.value) === value}\n                className={cn(\n                  \"cursor-pointer px-3 py-2 text-sm aria-selected:font-semibold\",\n                  i === active && \"bg-accent text-accent-foreground\",\n                )}\n                onMouseDown={(e) => {\n                  e.preventDefault();\n                  choose(String(option.value));\n                }}\n              >\n                {option.label}\n              </div>\n            ))}\n          </div>\n          {shown.length === 0 && (\n            <p className=\"px-3 py-2 text-sm text-muted-foreground\">\n              {options.length\n                ? `Nothing matches “${text.trim()}”.`\n                : \"There is nothing to choose yet.\"}\n            </p>\n          )}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/kit/ContactOwner.tsx": "// Smithable app kit: \"Contact the seller\" on a record's page (marketplace.md §2.4). The message\n// is mailed to the record's owner by the page's server function, with the sender's address as\n// the reply-to; the owner's address is never shown, and nothing is kept unless the app keeps it.\nimport { CircleAlert, Send } from \"lucide-react\";\nimport { useId, useState } from \"react\";\nimport { Button } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\nimport { Input, Label } from \"#/components/ui/input\";\n\nexport interface ContactValues {\n  name: string;\n  email: string;\n  message: string;\n}\n\nexport function ContactOwner({\n  recipient,\n  viewer,\n  onSend,\n}: {\n  /** Who receives it, as the block names them, e.g. \"seller\" or \"owner\". */\n  recipient: string;\n  /** The signed-in viewer: their name and email are filled in and locked. */\n  viewer?: { name: string; email: string } | null;\n  onSend: (values: ContactValues) => Promise<unknown>;\n}) {\n  const id = useId();\n  const [values, setValues] = useState<ContactValues>({\n    name: viewer?.name ?? \"\",\n    email: viewer?.email ?? \"\",\n    message: \"\",\n  });\n  const [state, setState] = useState<\"idle\" | \"sending\" | \"sent\">(\"idle\");\n  const [failure, setFailure] = useState<string>();\n  async function send(event: React.FormEvent) {\n    event.preventDefault();\n    setState(\"sending\");\n    setFailure(undefined);\n    try {\n      await onSend(values);\n      setState(\"sent\");\n    } catch (error) {\n      setFailure(error instanceof Error ? error.message : \"The message could not be sent.\");\n      setState(\"idle\");\n    }\n  }\n  return (\n    <Card data-kit=\"contact-owner\" className=\"mt-10 max-w-3xl p-card\">\n      <h2 id={`${id}-title`} className=\"text-lg font-semibold\">\n        Contact the {recipient}\n      </h2>\n      {state === \"sent\" ? (\n        <p role=\"status\" className=\"mt-4\">\n          Your message is sent.\n        </p>\n      ) : (\n        <form onSubmit={send} aria-labelledby={`${id}-title`} className=\"mt-4 space-y-4\">\n          <div className=\"grid gap-4 sm:grid-cols-2\">\n            <div className=\"space-y-2\">\n              <Label htmlFor={`${id}-name`}>Your name</Label>\n              <Input\n                id={`${id}-name`}\n                required\n                maxLength={200}\n                readOnly={Boolean(viewer)}\n                value={values.name}\n                onChange={(e) => setValues({ ...values, name: e.target.value })}\n              />\n            </div>\n            <div className=\"space-y-2\">\n              <Label htmlFor={`${id}-email`}>Your email</Label>\n              <Input\n                id={`${id}-email`}\n                type=\"email\"\n                required\n                maxLength={200}\n                readOnly={Boolean(viewer)}\n                value={values.email}\n                onChange={(e) => setValues({ ...values, email: e.target.value })}\n              />\n            </div>\n          </div>\n          <div className=\"space-y-2\">\n            <Label htmlFor={`${id}-message`}>Message</Label>\n            <textarea\n              id={`${id}-message`}\n              required\n              maxLength={2000}\n              rows={4}\n              value={values.message}\n              onChange={(e) => setValues({ ...values, message: e.target.value })}\n              className=\"w-full rounded-md border border-input bg-card px-3 py-2\"\n            />\n          </div>\n          {failure && (\n            <p role=\"alert\" className=\"flex items-center gap-2 text-sm text-destructive\">\n              <CircleAlert aria-hidden className=\"size-4\" /> {failure}\n            </p>\n          )}\n          <Button type=\"submit\" disabled={state === \"sending\"}>\n            <Send aria-hidden className=\"size-4\" /> {state === \"sending\" ? \"Sending…\" : \"Send\"}\n          </Button>\n        </form>\n      )}\n    </Card>\n  );\n}\n",
  "src/kit/Dashboard.tsx": "// Smithable app kit: dashboard tiles. A number, and a bar chart with one bar per month.\n// To change one, copy this file into src/custom/components/ and edit the copy.\nimport { Card } from \"#/components/ui/card\";\nimport type { AppUi } from \"./model\";\n\ntype Kind = \"money\" | \"int\" | \"decimal\";\n\n/** A number as the app shows it: money in the app's currency (stored in cents). */\nexport function formatNumber(\n  kind: Kind,\n  value: number | null,\n  app: AppUi,\n  compact = false,\n): string {\n  if (value === null) return \"—\";\n  const options: Intl.NumberFormatOptions = compact ? { notation: \"compact\" } : {};\n  if (kind === \"money\")\n    return new Intl.NumberFormat(undefined, {\n      ...options,\n      style: \"currency\",\n      currency: app.currency,\n    }).format(value / 100);\n  return new Intl.NumberFormat(undefined, {\n    ...options,\n    maximumFractionDigits: kind === \"int\" ? 0 : 2,\n  }).format(value);\n}\n\nexport function StatCard({ label, value }: { label: string; value: string }) {\n  return (\n    <Card data-kit=\"tile\" className=\"space-y-2 p-card\">\n      <h2 className=\"text-sm font-semibold text-muted-foreground\">{label}</h2>\n      <p className=\"text-3xl font-bold tabular-nums\">{value}</p>\n    </Card>\n  );\n}\n\n/** Bars with their values written on them, so the chart reads without a pointer or color. */\nexport function BarChart({\n  label,\n  kind,\n  app,\n  bars,\n}: {\n  label: string;\n  kind: Kind;\n  app: AppUi;\n  bars: { month: string; value: number }[];\n}) {\n  const max = Math.max(...bars.map((b) => b.value), 1);\n  const month = new Intl.DateTimeFormat(undefined, { month: \"short\", timeZone: \"UTC\" });\n  return (\n    <Card data-kit=\"tile\" className=\"p-card\">\n      <h2 className=\"font-semibold\">{label}</h2>\n      {bars.length === 0 ? (\n        <p className=\"mt-4 text-muted-foreground\">No activity in this period.</p>\n      ) : (\n        <ol className=\"mt-6 flex h-56 items-end gap-2 sm:gap-4\">\n          {bars.map((bar) => (\n            <li\n              key={bar.month}\n              className=\"flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-1\"\n            >\n              <span className=\"text-xs font-semibold tabular-nums\">\n                {formatNumber(kind, bar.value, app, true)}\n              </span>\n              <span\n                aria-hidden\n                className=\"w-full max-w-16 rounded-t-md bg-chart-1\"\n                style={{ height: `${(bar.value / max) * 100}%` }}\n              />\n              <span className=\"text-xs text-muted-foreground\">\n                {month.format(new Date(`${bar.month}-01T00:00:00Z`))}\n              </span>\n            </li>\n          ))}\n        </ol>\n      )}\n    </Card>\n  );\n}\n",
  "src/kit/FieldInput.tsx": "// Smithable app kit: the input control for one field, chosen by its kind.\nimport { Button } from \"#/components/ui/button\";\nimport { Checkbox, Input, NativeSelect, Textarea } from \"#/components/ui/input\";\nimport { Combobox } from \"./Combobox\";\nimport type { FieldUi, Options } from \"./model\";\n\ninterface FieldInputProps {\n  field: FieldUi;\n  id: string;\n  value: string | boolean;\n  invalid: boolean;\n  /** Ids of the field's help and error text. */\n  describedBy?: string;\n  /** Choices for reference fields. */\n  options?: Options;\n  /** The record being edited, when it exists (a picture shows from its address). */\n  record?: number;\n  onChange: (value: string | boolean) => void;\n}\n\nconst inputTypes: Partial<Record<FieldUi[\"kind\"], string>> = {\n  email: \"email\",\n  phone: \"tel\",\n  url: \"url\",\n  date: \"date\",\n  datetime: \"datetime-local\",\n};\n\nexport function FieldInput({\n  field,\n  id,\n  value,\n  invalid,\n  describedBy,\n  options,\n  record,\n  onChange,\n}: FieldInputProps) {\n  const common = {\n    id,\n    name: field.name,\n    \"data-part\": \"input\",\n    \"data-field\": field.name,\n    \"aria-invalid\": invalid || undefined,\n    \"aria-describedby\": describedBy,\n  };\n  if (field.kind === \"bool\" && field.control === \"radio\") {\n    return (\n      <Radios\n        {...common}\n        value={value === true ? \"yes\" : value === false ? \"no\" : \"\"}\n        choices={[\n          { value: \"yes\", label: \"Yes\" },\n          { value: \"no\", label: \"No\" },\n        ]}\n        onChange={(v) => onChange(v === \"yes\")}\n      />\n    );\n  }\n  if (field.kind === \"bool\") {\n    return (\n      <Checkbox\n        {...common}\n        role={field.control === \"switch\" ? \"switch\" : undefined}\n        checked={value === true}\n        onChange={(e) => onChange(e.target.checked)}\n      />\n    );\n  }\n  const text = typeof value === \"string\" ? value : \"\";\n  if (field.input) {\n    const Control = field.input;\n    return <Control {...common} value={text} record={record} onChange={onChange} />;\n  }\n  if (field.kind === \"text\" || field.kind === \"markdown\" || field.control === \"textarea\") {\n    return <Textarea {...common} value={text} onChange={(e) => onChange(e.target.value)} />;\n  }\n  // A number as a slider (the value shown beside it) or a stepper.\n  if (field.control === \"slider\" && field.min !== undefined && field.max !== undefined) {\n    const step = field.kind === \"int\" ? 1 : Math.max((field.max - field.min) / 100, 0.01);\n    return (\n      <div className=\"flex items-center gap-3\" data-part=\"slider\">\n        <input\n          {...common}\n          type=\"range\"\n          min={field.min}\n          max={field.max}\n          step={step}\n          value={text === \"\" ? field.min : Number(text)}\n          onChange={(e) => onChange(e.target.value)}\n          className=\"h-2 grow accent-primary\"\n        />\n        <output htmlFor={id} className=\"min-w-12 text-right text-sm tabular-nums\">\n          {text === \"\" ? \"—\" : text}\n        </output>\n      </div>\n    );\n  }\n  if (field.control === \"stepper\") {\n    const n = text === \"\" ? undefined : Number(text);\n    const step = (by: number) => {\n      const next = (n ?? field.min ?? 0) + by;\n      if (field.min !== undefined && next < field.min) return;\n      if (field.max !== undefined && next > field.max) return;\n      onChange(String(next));\n    };\n    return (\n      <div className=\"flex items-center gap-2\" data-part=\"stepper\">\n        <Button\n          type=\"button\"\n          variant=\"outline\"\n          size=\"icon\"\n          aria-label=\"Less\"\n          onClick={() => step(-1)}\n        >\n          −\n        </Button>\n        <Input\n          {...common}\n          type=\"number\"\n          inputMode=\"numeric\"\n          min={field.min}\n          max={field.max}\n          value={text}\n          onChange={(e) => onChange(e.target.value)}\n          className=\"w-24 text-center\"\n        />\n        <Button\n          type=\"button\"\n          variant=\"outline\"\n          size=\"icon\"\n          aria-label=\"More\"\n          onClick={() => step(1)}\n        >\n          +\n        </Button>\n      </div>\n    );\n  }\n  if (field.control === \"radio\" && field.choices) {\n    return (\n      <Radios\n        {...common}\n        value={text}\n        choices={field.choices}\n        required={field.required}\n        onChange={onChange}\n      />\n    );\n  }\n  if ((field.kind === \"relation\" || field.kind === \"user\") && field.control === \"select\") {\n    return (\n      <NativeSelect {...common} value={text} onChange={(e) => onChange(e.target.value)}>\n        {!field.required && <option value=\"\">—</option>}\n        {(options?.[field.name] ?? []).map((option) => (\n          <option key={option.value} value={option.value}>\n            {option.label}\n          </option>\n        ))}\n      </NativeSelect>\n    );\n  }\n  if (field.kind === \"relation\" || field.kind === \"user\") {\n    return (\n      <Combobox\n        id={id}\n        value={text}\n        options={options?.[field.name] ?? []}\n        required={field.required}\n        invalid={invalid}\n        describedBy={describedBy}\n        onChange={onChange}\n      />\n    );\n  }\n  if (field.kind === \"choice\") {\n    return (\n      <NativeSelect {...common} value={text} onChange={(e) => onChange(e.target.value)}>\n        {!field.required && <option value=\"\">—</option>}\n        {field.choices?.map((choice) => (\n          <option key={choice.value} value={choice.value}>\n            {choice.label}\n          </option>\n        ))}\n      </NativeSelect>\n    );\n  }\n  const numeric = field.kind === \"int\" || field.kind === \"decimal\" || field.kind === \"money\";\n  return (\n    <Input\n      {...common}\n      type={inputTypes[field.kind] ?? \"text\"}\n      inputMode={numeric ? (field.kind === \"int\" ? \"numeric\" : \"decimal\") : undefined}\n      value={text}\n      onChange={(e) => onChange(e.target.value)}\n    />\n  );\n}\n\n/** A choice as radio buttons: a small choice reads at a glance. */\nfunction Radios({\n  id,\n  name,\n  value,\n  choices,\n  required,\n  onChange,\n  ...aria\n}: {\n  id: string;\n  name: string;\n  value: string;\n  choices: { value: string; label: string }[];\n  required?: boolean;\n  onChange: (value: string) => void;\n  \"aria-invalid\"?: boolean;\n  \"aria-describedby\"?: string;\n}) {\n  return (\n    <div\n      role=\"radiogroup\"\n      id={id}\n      {...aria}\n      className=\"flex flex-wrap gap-x-5 gap-y-2\"\n      data-part=\"radios\"\n    >\n      {choices.map((choice) => (\n        <label key={choice.value} className=\"flex items-center gap-2 text-sm\">\n          <input\n            type=\"radio\"\n            name={name}\n            value={choice.value}\n            checked={value === choice.value}\n            required={required}\n            onChange={() => onChange(choice.value)}\n            className=\"size-4 accent-primary\"\n          />\n          {choice.label}\n        </label>\n      ))}\n    </div>\n  );\n}\n",
  "src/kit/Filters.tsx": "// Smithable app kit: a list's filters and its sort order, above the list beside the search box.\n// The state lives in the address (?segment=enterprise&creditLimit=1000..&sort=-creditLimit), so a\n// filtered view can be linked and reloaded; the page passes it in and gets the next state back.\n// On phones the filters fold behind a \"Filters\" button; the active ones show as removable chips.\nimport { SlidersHorizontal, X } from \"lucide-react\";\nimport { useEffect, useId, useState } from \"react\";\nimport { Button } from \"#/components/ui/button\";\nimport { Input, Label } from \"#/components/ui/input\";\nimport { cn } from \"#/lib/utils\";\n\nexport interface FilterUi {\n  /** The field's name: its key in the address. */\n  name: string;\n  label: string;\n  /**\n   * chips (a choice or a reference), range (a number, amount or date), toggle (yes/no), mine\n   * (the viewer's own records, for those signed in).\n   */\n  kind: \"chips\" | \"range\" | \"toggle\" | \"mine\";\n  options?: { value: string; label: string }[];\n  /** A range's inputs: numbers, amounts (in the currency's units) or dates. */\n  input?: \"number\" | \"date\";\n}\n\nexport interface SortUi {\n  value: string;\n  label: string;\n}\n\n/** A filter's state in the address: chips as \"a,b\", a range as \"from..to\", a toggle as \"true\". */\nexport type FilterValues = Record<string, string | undefined>;\n\nexport function Filters({\n  filters,\n  values,\n  sorts = [],\n  sort,\n  signedIn = false,\n  onChange,\n}: {\n  filters: FilterUi[];\n  values: FilterValues;\n  sorts?: SortUi[];\n  sort?: string;\n  /** Whether the viewer is signed in: only then is there a \"Mine\". */\n  signedIn?: boolean;\n  onChange: (next: FilterValues & { sort?: string }) => void;\n}) {\n  const [open, setOpen] = useState(false);\n  const id = useId();\n  const shown = filters.filter((f) => f.kind !== \"mine\" || signedIn);\n  const active = shown.filter((f) => values[f.name]);\n  const set = (name: string, value: string | undefined) =>\n    onChange({ ...values, [name]: value || undefined, sort });\n  return (\n    <div data-kit=\"filters\" className=\"mb-6 space-y-3\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        {shown.length > 0 && (\n          <Button\n            type=\"button\"\n            variant=\"outline\"\n            aria-expanded={open}\n            aria-controls={`${id}-panel`}\n            onClick={() => setOpen(!open)}\n            className=\"md:hidden\"\n          >\n            <SlidersHorizontal aria-hidden className=\"size-4\" /> Filters\n            {active.length > 0 && ` (${active.length})`}\n          </Button>\n        )}\n        {sorts.length > 0 && (\n          <div className=\"ml-auto flex items-center gap-2\">\n            <Label htmlFor={`${id}-sort`} className=\"text-sm\">\n              Sort by\n            </Label>\n            <select\n              id={`${id}-sort`}\n              value={sort ?? \"\"}\n              onChange={(e) => onChange({ ...values, sort: e.target.value || undefined })}\n              className=\"h-control rounded-md border border-input bg-card px-3 text-sm\"\n            >\n              <option value=\"\">Newest first</option>\n              {sorts.map((s) => (\n                <option key={s.value} value={s.value}>\n                  {s.label}\n                </option>\n              ))}\n            </select>\n          </div>\n        )}\n      </div>\n      {shown.length > 0 && (\n        <div\n          id={`${id}-panel`}\n          className={cn(\"flex-wrap items-end gap-x-6 gap-y-3 md:flex\", open ? \"flex\" : \"hidden\")}\n        >\n          {shown.map((f) => (\n            <Filter\n              key={f.name}\n              filter={f}\n              value={values[f.name]}\n              onChange={(v) => set(f.name, v)}\n            />\n          ))}\n        </div>\n      )}\n      {active.length > 0 && (\n        <ul aria-label=\"Active filters\" className=\"flex flex-wrap gap-2\">\n          {active.map((f) => (\n            <li key={f.name}>\n              <button\n                type=\"button\"\n                onClick={() => set(f.name, undefined)}\n                className=\"inline-flex items-center gap-1 rounded-full bg-accent px-3 py-1 text-sm text-accent-foreground\"\n              >\n                {f.label}: {describe(f, values[f.name] as string)}\n                <X aria-label={`Remove the ${f.label.toLowerCase()} filter`} className=\"size-4\" />\n              </button>\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  );\n}\n\nfunction Filter({\n  filter,\n  value,\n  onChange,\n}: {\n  filter: FilterUi;\n  value: string | undefined;\n  onChange: (value: string | undefined) => void;\n}) {\n  const id = useId();\n  const chosen = new Set((value ?? \"\").split(\",\").filter(Boolean));\n  if (filter.kind === \"mine\")\n    return (\n      <label className=\"flex h-control items-center gap-2 text-sm font-semibold\">\n        <input\n          type=\"checkbox\"\n          checked={value === \"mine\"}\n          onChange={(e) => onChange(e.target.checked ? \"mine\" : undefined)}\n          className=\"size-4 accent-primary\"\n        />\n        {filter.label}\n      </label>\n    );\n  if (filter.kind === \"toggle\")\n    return (\n      <div className=\"space-y-1\">\n        <Label htmlFor={id}>{filter.label}</Label>\n        <select\n          id={id}\n          value={value ?? \"\"}\n          onChange={(e) => onChange(e.target.value || undefined)}\n          className=\"h-control rounded-md border border-input bg-card px-3 text-sm\"\n        >\n          <option value=\"\">Any</option>\n          <option value=\"true\">Yes</option>\n          <option value=\"false\">No</option>\n        </select>\n      </div>\n    );\n  if (filter.kind === \"range\") return <Range filter={filter} value={value} onChange={onChange} />;\n  const options = filter.options ?? [];\n  // Many values read better as a list to pick one from than as a row of chips.\n  if (options.length > 8)\n    return (\n      <div className=\"space-y-1\">\n        <Label htmlFor={id}>{filter.label}</Label>\n        <select\n          id={id}\n          value={value ?? \"\"}\n          onChange={(e) => onChange(e.target.value || undefined)}\n          className=\"h-control max-w-60 rounded-md border border-input bg-card px-3 text-sm\"\n        >\n          <option value=\"\">Any</option>\n          {options.map((o) => (\n            <option key={o.value} value={o.value}>\n              {o.label}\n            </option>\n          ))}\n        </select>\n      </div>\n    );\n  return (\n    <fieldset className=\"space-y-1\">\n      <legend className=\"text-sm font-semibold\">{filter.label}</legend>\n      <div className=\"flex flex-wrap gap-2\">\n        {options.map((o) => {\n          const on = chosen.has(o.value);\n          return (\n            <button\n              key={o.value}\n              type=\"button\"\n              aria-pressed={on}\n              onClick={() => {\n                const next = new Set(chosen);\n                if (on) next.delete(o.value);\n                else next.add(o.value);\n                onChange([...next].join(\",\") || undefined);\n              }}\n              className={cn(\n                \"rounded-full border px-3 py-1 text-sm\",\n                on\n                  ? \"border-primary bg-primary text-primary-foreground\"\n                  : \"bg-card hover:bg-accent\",\n              )}\n            >\n              {o.label}\n            </button>\n          );\n        })}\n      </div>\n    </fieldset>\n  );\n}\n\n/** \"From\" and \"to\", applied once typing pauses, so the list never jumps on every key. */\nfunction Range({\n  filter,\n  value,\n  onChange,\n}: {\n  filter: FilterUi;\n  value: string | undefined;\n  onChange: (value: string | undefined) => void;\n}) {\n  const id = useId();\n  const [from = \"\", to = \"\"] = (value ?? \"\").split(\"..\");\n  const [text, setText] = useState({ from, to });\n  useEffect(() => {\n    const next = text.from || text.to ? `${text.from}..${text.to}` : undefined;\n    if (next === value) return;\n    const timer = setTimeout(() => onChange(next), 400);\n    return () => clearTimeout(timer);\n  }, [text, value, onChange]);\n  const type = filter.input === \"date\" ? \"date\" : \"number\";\n  return (\n    <fieldset className=\"space-y-1\">\n      <legend className=\"text-sm font-semibold\">{filter.label}</legend>\n      <div className=\"flex items-center gap-2\">\n        <Label htmlFor={`${id}-from`} className=\"sr-only\">\n          {filter.label} from\n        </Label>\n        <Input\n          id={`${id}-from`}\n          type={type}\n          placeholder=\"From\"\n          value={text.from}\n          onChange={(e) => setText({ ...text, from: e.target.value })}\n          className=\"w-32\"\n        />\n        <span aria-hidden>–</span>\n        <Label htmlFor={`${id}-to`} className=\"sr-only\">\n          {filter.label} to\n        </Label>\n        <Input\n          id={`${id}-to`}\n          type={type}\n          placeholder=\"To\"\n          value={text.to}\n          onChange={(e) => setText({ ...text, to: e.target.value })}\n          className=\"w-32\"\n        />\n      </div>\n    </fieldset>\n  );\n}\n\n/** An active filter in words, for its removable chip. */\nfunction describe(filter: FilterUi, value: string): string {\n  if (filter.kind === \"mine\") return \"yes\";\n  if (filter.kind === \"toggle\") return value === \"true\" ? \"Yes\" : \"No\";\n  if (filter.kind === \"range\") {\n    const [from, to] = value.split(\"..\");\n    return from && to ? `${from}–${to}` : from ? `from ${from}` : `up to ${to}`;\n  }\n  const labels = new Map((filter.options ?? []).map((o) => [o.value, o.label]));\n  return value\n    .split(\",\")\n    .map((v) => labels.get(v) ?? v)\n    .join(\", \");\n}\n\n/** All records or only the viewer's saved ones (marketplace.md §2.3): two tabs above the list. */\nexport function SavedTabs({\n  saved,\n  onChange,\n}: {\n  saved: boolean;\n  onChange: (saved: boolean) => void;\n}) {\n  const tab = (active: boolean, label: string, value: boolean) => (\n    <button\n      type=\"button\"\n      aria-pressed={active}\n      onClick={() => onChange(value)}\n      className={cn(\n        \"min-h-11 cursor-pointer rounded-md px-4 text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring\",\n        active\n          ? \"bg-background text-foreground shadow-sm\"\n          : \"text-muted-foreground hover:text-foreground\",\n      )}\n    >\n      {label}\n    </button>\n  );\n  return (\n    <div data-part=\"saved-tabs\" className=\"mb-4 inline-flex gap-1 rounded-lg bg-muted p-1\">\n      {tab(!saved, \"All\", false)}\n      {tab(saved, \"Saved\", true)}\n    </div>\n  );\n}\n",
  "src/kit/Landing.tsx": "// Smithable app kit: a landing page's layout and sections. Each section takes its texts as\n// props, and the generated page composes them. To change one, copy this file into\n// src/custom/components/ and edit the copy.\nimport { Link, type LinkProps } from \"@tanstack/react-router\";\nimport {\n  Check,\n  ChevronDown,\n  ChevronLeft,\n  ChevronRight,\n  Clock,\n  type LucideIcon,\n  Mail,\n  MapPin,\n  Menu,\n  Phone,\n  X,\n} from \"lucide-react\";\nimport { useId, useRef, useState } from \"react\";\nimport { buttonVariants } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\nimport { cn } from \"#/lib/utils\";\nimport { PicturePlaceholder } from \"./ModelTable\";\nimport { textMarker } from \"./model\";\n\nexport interface LandingLink {\n  to: LinkProps[\"to\"];\n  label: string;\n}\n\n/** A hero's shortcut: a page, shown as a round icon with its title under it. */\nexport interface LandingShortcut extends LandingLink {\n  icon: LucideIcon;\n}\n\n/** A footer of its own: a line of text and links (a page's address, or a full one). */\nexport interface LandingFooter {\n  text?: string;\n  links: { label?: string; link?: string }[];\n  texts?: string;\n}\n\n/** The page frame: the app's name, a link into the app, the sections and the footer. */\n/** The public site's frame (src/generated/site.ts): its menu and how to reach the business. */\nexport interface LandingSite {\n  /** The landing page's address: the app's name leads there. */\n  home?: LinkProps[\"to\"];\n  menu: LandingLink[];\n  contact?: { address?: string; phone?: string; email?: string; hours?: string };\n}\n\nexport function LandingLayout({\n  appName,\n  link,\n  footer,\n  site,\n  children,\n}: {\n  appName: string;\n  link?: LandingLink;\n  footer?: LandingFooter;\n  site?: LandingSite;\n  children: React.ReactNode;\n}) {\n  const [open, setOpen] = useState(false);\n  const menu = site?.menu ?? [];\n  const contact = site?.contact;\n  // Columns when there is something to put in them; otherwise the one line it always had.\n  const columns = menu.length > 0 || contact !== undefined;\n  const name = site?.home ? (\n    <Link to={site.home} className=\"min-w-0 truncate text-xl font-bold\">\n      {appName}\n    </Link>\n  ) : (\n    <p className=\"min-w-0 truncate text-xl font-bold\">{appName}</p>\n  );\n  const footerLinks = footer && footer.links.length > 0 && (\n    <ul className=\"flex flex-wrap gap-x-6 gap-y-2\">\n      {footer.links.map((l, i) => (\n        <li key={l.link ?? i}>\n          <a\n            href={l.link}\n            className=\"underline-offset-4 hover:text-foreground hover:underline\"\n            {...mark(footer.texts, `items.${i}.label`)}\n          >\n            {l.label}\n          </a>\n        </li>\n      ))}\n    </ul>\n  );\n  return (\n    <div data-kit=\"landing\" className=\"flex min-h-screen flex-col\">\n      <header data-part=\"header\" className=\"border-b bg-card\">\n        <div className=\"mx-auto flex h-18 max-w-6xl items-center justify-between gap-4 px-5\">\n          {name}\n          {menu.length > 0 && (\n            <nav aria-label=\"Site\" className=\"hidden md:block\">\n              <ul className=\"flex items-center gap-6 text-sm font-medium\">\n                {menu.map((m) => (\n                  <li key={String(m.to)}>\n                    <Link\n                      to={m.to}\n                      className=\"underline-offset-4 hover:underline\"\n                      activeProps={{ \"aria-current\": \"page\", className: \"text-primary\" }}\n                    >\n                      {m.label}\n                    </Link>\n                  </li>\n                ))}\n              </ul>\n            </nav>\n          )}\n          <div className=\"flex items-center gap-2\">\n            {link && (\n              <Link to={link.to} className={buttonVariants({ variant: \"outline\" })}>\n                {link.label}\n              </Link>\n            )}\n            {menu.length > 0 && (\n              <button\n                type=\"button\"\n                aria-expanded={open}\n                aria-controls=\"site-menu\"\n                aria-label=\"Menu\"\n                onClick={() => setOpen(!open)}\n                className={cn(buttonVariants({ variant: \"ghost\" }), \"md:hidden\")}\n              >\n                {open ? (\n                  <X aria-hidden className=\"size-5\" />\n                ) : (\n                  <Menu aria-hidden className=\"size-5\" />\n                )}\n              </button>\n            )}\n          </div>\n        </div>\n        {open && menu.length > 0 && (\n          <nav id=\"site-menu\" aria-label=\"Site\" className=\"border-t md:hidden\">\n            <ul className=\"mx-auto max-w-6xl px-5 py-2\">\n              {menu.map((m) => (\n                <li key={String(m.to)}>\n                  <Link to={m.to} onClick={() => setOpen(false)} className=\"block py-3 font-medium\">\n                    {m.label}\n                  </Link>\n                </li>\n              ))}\n            </ul>\n          </nav>\n        )}\n      </header>\n      <main className=\"flex-1\">{children}</main>\n      <footer data-part=\"footer\" className=\"border-t\">\n        {columns ? (\n          <div className=\"mx-auto max-w-6xl px-5 py-12 text-sm\">\n            <div className=\"grid gap-10 sm:grid-cols-2 lg:grid-cols-3\">\n              <div className=\"space-y-2\">\n                <p className=\"text-base font-semibold\">{appName}</p>\n                {contact?.address && <p className=\"text-muted-foreground\">{contact.address}</p>}\n                {contact?.phone && (\n                  <p>\n                    <a href={`tel:${contact.phone.replace(/\\s/g, \"\")}`} className=\"hover:underline\">\n                      {contact.phone}\n                    </a>\n                  </p>\n                )}\n                {contact?.email && (\n                  <p>\n                    <a href={`mailto:${contact.email}`} className=\"hover:underline\">\n                      {contact.email}\n                    </a>\n                  </p>\n                )}\n                {contact?.hours && <p className=\"text-muted-foreground\">{contact.hours}</p>}\n              </div>\n              {menu.length > 0 && (\n                <nav aria-label=\"Pages\" className=\"space-y-2\">\n                  <p className=\"text-base font-semibold\">Pages</p>\n                  <ul className=\"space-y-2\">\n                    {menu.map((m) => (\n                      <li key={String(m.to)}>\n                        <Link\n                          to={m.to}\n                          className=\"text-muted-foreground hover:text-foreground hover:underline\"\n                        >\n                          {m.label}\n                        </Link>\n                      </li>\n                    ))}\n                  </ul>\n                </nav>\n              )}\n              {(footer?.text || footerLinks) && (\n                <div className=\"space-y-3 text-muted-foreground\">\n                  {footer?.text && <p {...mark(footer.texts, \"text\")}>{footer.text}</p>}\n                  {footerLinks && <nav aria-label=\"Footer\">{footerLinks}</nav>}\n                </div>\n              )}\n            </div>\n            <p className=\"mt-10 border-t pt-6 text-muted-foreground\">\n              © {new Date().getFullYear()} {appName}\n            </p>\n          </div>\n        ) : (\n          <div className=\"mx-auto flex max-w-6xl flex-col gap-4 px-5 py-8 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between\">\n            <p {...mark(footer?.texts, \"text\")}>{footer?.text ?? appName}</p>\n            {footerLinks && <nav aria-label=\"Footer\">{footerLinks}</nav>}\n          </div>\n        )}\n      </footer>\n    </div>\n  );\n}\n\n/** A section's hooks for custom styles: its name, the last part of where its texts are kept. */\nconst sectionHooks = (texts: string | undefined) => ({\n  \"data-kit\": \"section\",\n  \"data-section\": texts?.split(\".\").at(-1),\n});\n\n/** Marks one of a section's texts with where it is kept, e.g. \"pages.home.hero.title\". */\nconst mark = (texts: string | undefined, key: string) =>\n  texts ? textMarker(`${texts}.${key}`) : {};\n\nexport function Section({\n  texts,\n  id,\n  title,\n  text,\n  children,\n}: {\n  id: string;\n  title?: string;\n  text?: string;\n  children: React.ReactNode;\n  texts?: string;\n}) {\n  return (\n    <section\n      {...sectionHooks(texts)}\n      aria-labelledby={title ? `${id}-title` : undefined}\n      className=\"mx-auto max-w-6xl px-5 py-12\"\n    >\n      {title && (\n        <h2\n          id={`${id}-title`}\n          className=\"text-2xl leading-tight font-(--heading-weight) tracking-(--heading-tracking) sm:text-[2rem]\"\n          {...mark(texts, \"title\")}\n        >\n          {title}\n        </h2>\n      )}\n      {text && (\n        <p className=\"mt-3 max-w-2xl text-lg text-muted-foreground\" {...mark(texts, \"text\")}>\n          {text}\n        </p>\n      )}\n      <div className={text ? \"mt-8\" : title ? \"mt-6\" : undefined}>{children}</div>\n    </section>\n  );\n}\n\n/** A picture from public/, e.g. { src: \"/images/hero.webp\", alt: \"A yoga class\" }. */\nexport interface LandingImage {\n  src: string;\n  alt: string;\n}\n\nexport function Hero({\n  texts,\n  title,\n  subtitle,\n  link,\n  image,\n  more,\n  shortcuts = [],\n  layout = \"split\",\n  imageSide = \"right\",\n}: {\n  title: string;\n  subtitle?: string;\n  link?: LandingLink;\n  image?: LandingImage;\n  /** Sections follow: a quiet arrow under the content says the page goes on. */\n  more?: boolean;\n  /** Up to four pages, as round icons over the hero's lower edge. */\n  shortcuts?: LandingShortcut[];\n  /**\n   * split: text beside the picture; centered: text over it; plain: no picture; cover: the\n   * picture across the width with the theme's primary washing over it under the text.\n   */\n  layout?: \"split\" | \"centered\" | \"plain\" | \"cover\";\n  /** The picture's side in a split hero on wide screens. */\n  imageSide?: \"left\" | \"right\";\n  texts?: string;\n}) {\n  const after = useId();\n  // A link to where the next section starts, so it works by keyboard and without JavaScript.\n  const cue = more && (\n    <a\n      href={`#${after}`}\n      aria-label=\"More below\"\n      className=\"mx-auto flex size-11 items-center justify-center rounded-full text-muted-foreground hover:text-foreground lg:col-span-2\"\n    >\n      <ChevronDown aria-hidden className=\"size-6 motion-safe:animate-bounce\" />\n    </a>\n  );\n  const end = more && <span id={after} tabIndex={-1} />;\n  const shortcutList = shortcuts.length > 0 && (\n    <nav aria-label=\"Shortcuts\" className=\"relative z-10 mx-auto -mt-12 max-w-4xl px-5\">\n      <ul className=\"grid grid-cols-2 gap-4 sm:flex sm:justify-center sm:gap-8\">\n        {shortcuts.map((s) => (\n          <li key={String(s.to)} data-part=\"shortcut\">\n            <Link\n              to={s.to}\n              className=\"group flex flex-col items-center gap-2 rounded-lg text-center text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n            >\n              <span className=\"flex size-20 items-center justify-center rounded-full border bg-card text-primary shadow-md transition group-hover:-translate-y-0.5 group-hover:shadow-lg\">\n                <s.icon aria-hidden className=\"size-8\" />\n              </span>\n              <span className=\"max-w-32\">{s.label}</span>\n            </Link>\n          </li>\n        ))}\n      </ul>\n    </nav>\n  );\n  const text = (\n    <div>\n      <h1\n        className=\"max-w-3xl text-4xl leading-tight font-(--heading-weight) tracking-(--heading-tracking) sm:text-5xl lg:text-6xl\"\n        {...mark(texts, \"title\")}\n      >\n        {title}\n      </h1>\n      {subtitle && (\n        <p className=\"mt-6 max-w-2xl text-lg text-muted-foreground\" {...mark(texts, \"subtitle\")}>\n          {subtitle}\n        </p>\n      )}\n      {link && (\n        <Link to={link.to} className={cn(buttonVariants(), \"mt-10 h-12 px-6 text-base\")}>\n          <span {...mark(texts, \"button\")}>{link.label}</span>\n        </Link>\n      )}\n    </div>\n  );\n  // Without a picture every look is plain, so a missing picture never breaks the page.\n  if (!image || layout === \"plain\")\n    return (\n      <section\n        {...sectionHooks(texts)}\n        className={cn(\"mx-auto max-w-6xl px-5 py-20 sm:py-28\", more && \"pb-6 sm:pb-6\")}\n      >\n        {text}\n        {shortcutList && <div className=\"mt-16 [&_nav]:mt-0 [&_nav]:px-0\">{shortcutList}</div>}\n        {cue && <div className=\"mt-12\">{cue}</div>}\n        {end}\n      </section>\n    );\n  // Across the width: the primary washes over the picture where the text is, so the text keeps\n  // the theme's own contrast (primary against its foreground), checked like the rest; on a phone,\n  // where the text spans the picture, the wash is nearly solid.\n  if (layout === \"cover\")\n    return (\n      <>\n        <section {...sectionHooks(texts)} className=\"relative isolate overflow-hidden\">\n          <img\n            src={image.src}\n            alt={image.alt}\n            width={1600}\n            height={900}\n            fetchPriority=\"high\"\n            className=\"absolute inset-0 -z-10 size-full object-cover\"\n          />\n          <div\n            aria-hidden\n            className=\"absolute inset-0 -z-10 bg-primary/90 sm:bg-transparent sm:bg-linear-to-r sm:from-primary sm:via-primary/85 sm:to-primary/10\"\n          />\n          <div\n            className={cn(\n              \"mx-auto max-w-6xl px-5 py-24 text-primary-foreground sm:py-32 [&_a]:bg-background [&_a]:text-foreground [&_a:hover]:bg-background/90 [&_p]:text-primary-foreground/90\",\n              shortcutList && \"pb-28 sm:pb-36\",\n            )}\n          >\n            {text}\n          </div>\n        </section>\n        {shortcutList}\n        {cue && <div className=\"mt-8\">{cue}</div>}\n        {end}\n      </>\n    );\n  // Shortcuts sit over the hero's lower edge; the arrow down, if any, then comes after them.\n  const framed = (hero: React.ReactNode) =>\n    shortcutList ? (\n      <>\n        {hero}\n        {shortcutList}\n        {cue && <div className=\"mt-8\">{cue}</div>}\n        {end}\n      </>\n    ) : (\n      hero\n    );\n  // Over the picture: a dark veil keeps the text readable on any picture.\n  if (layout === \"centered\")\n    return framed(\n      <section {...sectionHooks(texts)} className=\"relative isolate overflow-hidden\">\n        <img\n          src={image.src}\n          alt={image.alt}\n          width={1200}\n          height={800}\n          fetchPriority=\"high\"\n          className=\"absolute inset-0 -z-10 size-full object-cover\"\n        />\n        <div aria-hidden className=\"absolute inset-0 -z-10 bg-black/60\" />\n        <div\n          className={cn(\n            \"mx-auto flex max-w-4xl flex-col items-center px-5 py-24 text-center text-white sm:py-36 [&_h1]:mx-auto [&_p]:mx-auto [&_p]:text-white/90\",\n            shortcutList && \"pb-28 sm:pb-40\",\n          )}\n        >\n          {text}\n          {!shortcutList && cue && <div className=\"mt-12 text-white/80\">{cue}</div>}\n          {!shortcutList && end}\n        </div>\n      </section>,\n    );\n  // Beside the text on wide screens, above it on narrow ones; the first thing loaded.\n  return framed(\n    <section\n      {...sectionHooks(texts)}\n      className={cn(\n        \"mx-auto grid max-w-6xl items-center gap-10 px-5 py-12 sm:py-20 lg:grid-cols-2\",\n        shortcutList && \"pb-20 sm:pb-28\",\n      )}\n    >\n      <img\n        src={image.src}\n        alt={image.alt}\n        width={1200}\n        height={800}\n        fetchPriority=\"high\"\n        className={cn(\n          \"aspect-[3/2] w-full rounded-xl object-cover\",\n          imageSide === \"right\" && \"lg:order-2\",\n        )}\n      />\n      {text}\n      {!shortcutList && cue}\n      {!shortcutList && end}\n    </section>,\n  );\n}\n\nexport function Features({\n  texts,\n  title,\n  text,\n  items,\n  columns = 3,\n}: {\n  title?: string;\n  text?: string;\n  items: { title?: string; text?: string }[];\n  /** Items side by side on wide screens: 2, 3 or 4. */\n  columns?: 2 | 3 | 4;\n  texts?: string;\n}) {\n  const grid = {\n    2: \"sm:grid-cols-2\",\n    3: \"sm:grid-cols-2 lg:grid-cols-3\",\n    4: \"sm:grid-cols-2 lg:grid-cols-4\",\n  }[columns];\n  return (\n    <Section id=\"features\" texts={texts} title={title} text={text}>\n      <ul className={cn(\"grid gap-4\", grid)}>\n        {items.map((item, i) => (\n          <li key={item.title ?? item.text}>\n            <Card className=\"h-full space-y-2 p-card\">\n              {item.title && (\n                <h3 className=\"text-lg font-semibold\" {...mark(texts, `items.${i}.title`)}>\n                  {item.title}\n                </h3>\n              )}\n              {item.text && (\n                <p className=\"text-muted-foreground\" {...mark(texts, `items.${i}.text`)}>\n                  {item.text}\n                </p>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </Section>\n  );\n}\n\n/** Records shown as cards, e.g. the classes a studio offers. */\nexport function RecordCards({\n  texts,\n  id,\n  title,\n  text,\n  cards,\n  layout = \"cards\",\n  icon,\n  door,\n}: {\n  id: string;\n  title?: string;\n  text?: string;\n  cards: {\n    key: string | number;\n    title: string;\n    text?: string;\n    badge?: string;\n    /** Where the card opens, e.g. its article. */\n    href?: string;\n    picture?: { src: string; alt: string; width: number; height: number };\n  }[];\n  /** cards: a grid of cards; list: rows with a small picture; grid: the pictures, titled. */\n  layout?: \"cards\" | \"list\" | \"grid\";\n  /** The model's icon, for a model with pictures: the placeholder where a record has none. */\n  icon?: LucideIcon;\n  texts?: string;\n  /**\n   * A catalog's door: a search box and filter chips that open the model's list (`to`) with\n   * the same address state, e.g. /?q=sofa or /?category=furniture.\n   */\n  door?: {\n    to: string;\n    search?: { label: string; placeholder: string };\n    chips?: { name: string; label: string; options: { value: string; label: string }[] }[];\n  };\n}) {\n  if (cards.length === 0 && !door) return null;\n  type CardItem = (typeof cards)[number];\n  // The whole card or row opens it; the link is the title.\n  const heading = (card: CardItem) =>\n    card.href ? (\n      <a\n        href={card.href}\n        className=\"outline-none after:absolute after:inset-0 focus-visible:underline\"\n      >\n        {card.title}\n      </a>\n    ) : (\n      card.title\n    );\n  // A record without a picture gets the placeholder when its model has pictures (it is given\n  // an icon then), so the cards stay even; a model without pictures keeps text cards.\n  const picture = (card: CardItem, className: string) =>\n    !card.picture ? (\n      icon && <PicturePlaceholder icon={icon} className={className} />\n    ) : (\n      <img\n        src={card.picture.src}\n        alt={card.picture.alt}\n        width={card.picture.width}\n        height={card.picture.height}\n        loading=\"lazy\"\n        className={className}\n      />\n    );\n  const details = (card: CardItem) => (\n    <>\n      {card.text && <p className=\"flex-1 text-muted-foreground\">{card.text}</p>}\n      {card.badge && (\n        <p className=\"mt-2\">\n          <span className=\"rounded-md bg-accent px-2 py-0.5 text-xs font-semibold text-accent-foreground\">\n            {card.badge}\n          </span>\n        </p>\n      )}\n    </>\n  );\n  return (\n    <Section id={id} texts={texts} title={title} text={text}>\n      {door && (\n        <div data-part=\"door\" className=\"mb-8 space-y-4\">\n          {door.search && (\n            <search>\n              <form action={door.to} method=\"get\" className=\"flex max-w-xl gap-2\">\n                <input\n                  type=\"search\"\n                  name=\"q\"\n                  aria-label={door.search.label}\n                  placeholder={door.search.placeholder}\n                  className=\"h-control min-w-0 flex-1 rounded-md border border-input bg-background px-3 text-base outline-none focus-visible:ring-2 focus-visible:ring-ring\"\n                />\n                <button type=\"submit\" className={buttonVariants()}>\n                  Search\n                </button>\n              </form>\n            </search>\n          )}\n          {door.chips?.map((chip) => (\n            <nav key={chip.name} aria-label={chip.label} className=\"flex flex-wrap gap-2\">\n              {chip.options.map((option) => (\n                <a\n                  key={option.value}\n                  href={`${door.to}?${new URLSearchParams({ [chip.name]: option.value })}`}\n                  className=\"inline-flex min-h-11 items-center rounded-full border px-4 text-sm font-medium outline-none hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring\"\n                >\n                  {option.label}\n                </a>\n              ))}\n            </nav>\n          ))}\n        </div>\n      )}\n      {layout === \"list\" ? (\n        <ul className=\"divide-y border-y\">\n          {cards.map((card) => (\n            <li\n              key={card.key}\n              className={cn(\n                \"relative flex items-start gap-4 py-4\",\n                card.href && \"hover:bg-accent/40\",\n              )}\n            >\n              {picture(card, \"aspect-[3/2] w-28 shrink-0 rounded-md object-cover sm:w-40\")}\n              <div className=\"flex flex-1 flex-col gap-1\">\n                <h3 className=\"text-lg font-semibold\">{heading(card)}</h3>\n                {details(card)}\n              </div>\n            </li>\n          ))}\n        </ul>\n      ) : layout === \"grid\" ? (\n        <ul className=\"grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4\">\n          {cards.map((card) => (\n            <li key={card.key} className=\"relative\">\n              <figure className=\"space-y-2\">\n                {picture(card, \"aspect-square w-full rounded-lg object-cover\")}\n                <figcaption className=\"font-semibold\">{heading(card)}</figcaption>\n              </figure>\n            </li>\n          ))}\n        </ul>\n      ) : (\n        <ul className=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-3\">\n          {cards.map((card) => (\n            <li key={card.key}>\n              <Card\n                className={cn(\n                  \"relative flex h-full flex-col gap-2 overflow-hidden\",\n                  card.href && \"hover:bg-accent/40\",\n                )}\n              >\n                {picture(card, \"aspect-[3/2] w-full object-cover\")}\n                <div className=\"flex flex-1 flex-col gap-2 p-card\">\n                  <h3 className=\"text-lg font-semibold\">{heading(card)}</h3>\n                  {details(card)}\n                </div>\n              </Card>\n            </li>\n          ))}\n        </ul>\n      )}\n    </Section>\n  );\n}\n\nexport function Pricing({\n  texts,\n  title,\n  text,\n  plans,\n  link,\n  highlight,\n}: {\n  title?: string;\n  text?: string;\n  /** The plan drawn forward, by its name. */\n  highlight?: string;\n  plans: {\n    name?: string;\n    price?: string;\n    period?: string;\n    text?: string;\n    features?: string[];\n    button?: string;\n  }[];\n  link?: LandingLink;\n  texts?: string;\n}) {\n  const forward = (name?: string) =>\n    Boolean(highlight && name && name.trim().toLowerCase() === highlight.trim().toLowerCase());\n  return (\n    <Section id=\"pricing\" texts={texts} title={title} text={text}>\n      <ul className=\"grid gap-4 md:grid-cols-2 lg:grid-cols-3\">\n        {plans.map((plan, i) => (\n          <li key={plan.name}>\n            <Card\n              data-part={forward(plan.name) ? \"highlight\" : undefined}\n              className={cn(\n                \"flex h-full flex-col gap-4 p-card\",\n                forward(plan.name) && \"border-primary ring-2 ring-primary\",\n              )}\n            >\n              <h3 className=\"text-lg font-semibold\" {...mark(texts, `items.${i}.name`)}>\n                {plan.name}\n              </h3>\n              {plan.price && (\n                <p>\n                  <span\n                    className=\"text-3xl font-bold tabular-nums\"\n                    {...mark(texts, `items.${i}.price`)}\n                  >\n                    {plan.price}\n                  </span>{\" \"}\n                  {plan.period && (\n                    <span className=\"text-muted-foreground\" {...mark(texts, `items.${i}.period`)}>\n                      {plan.period}\n                    </span>\n                  )}\n                </p>\n              )}\n              {plan.text && (\n                <p className=\"text-muted-foreground\" {...mark(texts, `items.${i}.text`)}>\n                  {plan.text}\n                </p>\n              )}\n              {plan.features && (\n                <ul className=\"flex-1 space-y-2\">\n                  {plan.features.map((feature, j) => (\n                    <li key={feature} className=\"flex gap-2\">\n                      <Check aria-hidden className=\"mt-0.5 size-5 shrink-0 text-primary\" />\n                      <span {...mark(texts, `items.${i}.features.${j}`)}>{feature}</span>\n                    </li>\n                  ))}\n                </ul>\n              )}\n              {link && (\n                <Link\n                  to={link.to}\n                  className={buttonVariants({\n                    variant: forward(plan.name) ? \"default\" : \"outline\",\n                  })}\n                >\n                  <span {...mark(texts, `items.${i}.button`)}>{plan.button ?? link.label}</span>\n                </Link>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n    </Section>\n  );\n}\n\nexport function Testimonials({\n  texts,\n  title,\n  items,\n  layout = \"cards\",\n}: {\n  title?: string;\n  items: { quote?: string; name?: string; role?: string }[];\n  /** cards: side by side; carousel: a row that scrolls sideways; one: the first quote, large. */\n  layout?: \"cards\" | \"carousel\" | \"one\";\n  texts?: string;\n}) {\n  const quote = (item: (typeof items)[number], i: number, large = false) => (\n    <figure className={cn(\"space-y-4\", large && \"mx-auto max-w-3xl text-center\")}>\n      <blockquote className={large ? \"text-2xl leading-snug sm:text-3xl\" : \"text-lg\"}>\n        “<span {...mark(texts, `items.${i}.quote`)}>{item.quote}</span>”\n      </blockquote>\n      <figcaption className=\"text-sm\">\n        <span className=\"font-semibold\" {...mark(texts, `items.${i}.name`)}>\n          {item.name}\n        </span>\n        {item.role && (\n          <span className=\"text-muted-foreground\">\n            , <span {...mark(texts, `items.${i}.role`)}>{item.role}</span>\n          </span>\n        )}\n      </figcaption>\n    </figure>\n  );\n  const first = items[0];\n  return (\n    <Section id=\"testimonials\" texts={texts} title={title}>\n      {layout === \"one\" && first ? (\n        quote(first, 0, true)\n      ) : (\n        <ul\n          className={\n            layout === \"carousel\"\n              ? \"flex snap-x snap-mandatory gap-4 overflow-x-auto pb-2\"\n              : \"grid gap-4 md:grid-cols-2 lg:grid-cols-3\"\n          }\n          // A row that scrolls sideways: reachable with the keyboard's arrow keys.\n          {...(layout === \"carousel\" ? { tabIndex: 0, \"aria-label\": title ?? \"Testimonials\" } : {})}\n        >\n          {items.map((item, i) => (\n            <li\n              key={item.quote}\n              className={\n                layout === \"carousel\"\n                  ? \"w-[85%] shrink-0 snap-start sm:w-[45%] lg:w-[31%]\"\n                  : undefined\n              }\n            >\n              <Card className=\"h-full p-card\">{quote(item, i)}</Card>\n            </li>\n          ))}\n        </ul>\n      )}\n    </Section>\n  );\n}\n\n/** Questions that open in place; the browser handles the keyboard and the expanded state. */\nexport function Faq({\n  texts,\n  title,\n  items,\n  layout = \"accordion\",\n}: {\n  title?: string;\n  items: { question?: string; answer?: string }[];\n  /** accordion: answers open on a click; list: every answer shown. */\n  layout?: \"accordion\" | \"list\";\n  texts?: string;\n}) {\n  if (layout === \"list\")\n    return (\n      <Section id=\"faq\" texts={texts} title={title}>\n        <dl className=\"max-w-3xl space-y-6\">\n          {items.map((item, i) => (\n            <div key={item.question}>\n              <dt className=\"font-semibold\" {...mark(texts, `items.${i}.question`)}>\n                {item.question}\n              </dt>\n              <dd className=\"mt-1 text-muted-foreground\" {...mark(texts, `items.${i}.answer`)}>\n                {item.answer}\n              </dd>\n            </div>\n          ))}\n        </dl>\n      </Section>\n    );\n  return (\n    <Section id=\"faq\" texts={texts} title={title}>\n      <div className=\"max-w-3xl divide-y border-y\">\n        {items.map((item, i) => (\n          <details key={item.question} className=\"group\">\n            <summary className=\"flex min-h-14 cursor-pointer list-none items-center justify-between gap-4 py-3 font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring [&::-webkit-details-marker]:hidden\">\n              <span {...mark(texts, `items.${i}.question`)}>{item.question}</span>\n              <ChevronDown\n                aria-hidden\n                className=\"size-5 shrink-0 transition-transform group-open:rotate-180\"\n              />\n            </summary>\n            <p className=\"pb-4 text-muted-foreground\" {...mark(texts, `items.${i}.answer`)}>\n              {item.answer}\n            </p>\n          </details>\n        ))}\n      </div>\n    </Section>\n  );\n}\n\nexport function CallToAction({\n  texts,\n  title,\n  text,\n  link,\n}: {\n  title: string;\n  text?: string;\n  link?: LandingLink;\n  texts?: string;\n}) {\n  return (\n    <section {...sectionHooks(texts)} className=\"mx-auto max-w-6xl px-5 py-12\">\n      <div className=\"rounded-xl bg-primary px-6 py-12 text-primary-foreground sm:px-12\">\n        <h2\n          className=\"text-2xl leading-tight font-(--heading-weight) tracking-(--heading-tracking) sm:text-[2rem]\"\n          {...mark(texts, \"title\")}\n        >\n          {title}\n        </h2>\n        {text && (\n          <p className=\"mt-3 max-w-2xl text-lg\" {...mark(texts, \"text\")}>\n            {text}\n          </p>\n        )}\n        {link && (\n          <Link\n            to={link.to}\n            className={cn(buttonVariants({ variant: \"secondary\" }), \"mt-8 h-12 px-6 text-base\")}\n          >\n            <span {...mark(texts, \"button\")}>{link.label}</span>\n          </Link>\n        )}\n      </div>\n    </section>\n  );\n}\n\n/**\n * Contact details (address with a map link, phone, email, opening hours one per line) and,\n * when the app has one, a form visitors send; `thanks` replaces it once sent.\n */\nexport function Contact({\n  texts,\n  title,\n  text,\n  address,\n  phone,\n  email,\n  hours,\n  thanks,\n  form,\n}: {\n  title?: string;\n  text?: string;\n  address?: string;\n  phone?: string;\n  email?: string;\n  hours?: string;\n  thanks?: string;\n  /**\n   * The form; it calls `sent` once the message is stored, and stores it only when `human()`:\n   * a field people never see stays empty, while form-filling bots fill it.\n   */\n  form?: (sent: () => void, human: () => boolean) => React.ReactNode;\n  texts?: string;\n}) {\n  const [sent, setSent] = useState(false);\n  const trap = useRef<HTMLInputElement>(null);\n  const details = (\n    <dl className=\"space-y-5\">\n      {address && (\n        <div className=\"flex gap-3\">\n          <dt>\n            <MapPin aria-hidden className=\"mt-0.5 size-5 text-primary\" />\n            <span className=\"sr-only\">Address</span>\n          </dt>\n          <dd>\n            <p className=\"whitespace-pre-line\" {...mark(texts, \"address\")}>\n              {address}\n            </p>\n            {/* A link, not an embedded map: no third party is called when the page opens. */}\n            <a\n              href={`https://www.openstreetmap.org/search?query=${encodeURIComponent(address)}`}\n              className=\"text-sm text-primary underline-offset-4 hover:underline\"\n              rel=\"noopener noreferrer\"\n              target=\"_blank\"\n            >\n              Show on map\n            </a>\n          </dd>\n        </div>\n      )}\n      {phone && (\n        <div className=\"flex gap-3\">\n          <dt>\n            <Phone aria-hidden className=\"mt-0.5 size-5 text-primary\" />\n            <span className=\"sr-only\">Phone</span>\n          </dt>\n          <dd>\n            <a href={`tel:${phone.replace(/[^+\\d]/g, \"\")}`} {...mark(texts, \"phone\")}>\n              {phone}\n            </a>\n          </dd>\n        </div>\n      )}\n      {email && (\n        <div className=\"flex gap-3\">\n          <dt>\n            <Mail aria-hidden className=\"mt-0.5 size-5 text-primary\" />\n            <span className=\"sr-only\">Email</span>\n          </dt>\n          <dd>\n            <a href={`mailto:${email}`} {...mark(texts, \"email\")}>\n              {email}\n            </a>\n          </dd>\n        </div>\n      )}\n      {hours && (\n        <div className=\"flex gap-3\">\n          <dt>\n            <Clock aria-hidden className=\"mt-0.5 size-5 text-primary\" />\n            <span className=\"sr-only\">Opening hours</span>\n          </dt>\n          <dd className=\"whitespace-pre-line\" {...mark(texts, \"hours\")}>\n            {hours}\n          </dd>\n        </div>\n      )}\n    </dl>\n  );\n  return (\n    <Section id=\"contact\" texts={texts} title={title} text={text}>\n      <div className={cn(\"grid gap-10\", form && \"lg:grid-cols-2\")}>\n        {details}\n        {form &&\n          (sent ? (\n            <Card className=\"p-card\">\n              <p role=\"status\" className=\"text-lg\" {...mark(texts, \"thanks\")}>\n                {thanks ?? \"Thank you! We will get back to you soon.\"}\n              </p>\n            </Card>\n          ) : (\n            <div>\n              {/* Off screen and out of the tab order: only a bot fills it in. */}\n              <div aria-hidden className=\"absolute -left-[9999px] h-px w-px overflow-hidden\">\n                <label>\n                  Leave this empty\n                  <input ref={trap} tabIndex={-1} autoComplete=\"off\" name=\"company-website\" />\n                </label>\n              </div>\n              {/* The form draws its own card. */}\n              {form(\n                () => setSent(true),\n                () => !trap.current?.value,\n              )}\n            </div>\n          ))}\n      </div>\n    </Section>\n  );\n}\n\n/** Pictures in a grid; one opens large in a lightbox, with the arrow keys to move on. */\nexport function Gallery({\n  texts,\n  title,\n  text,\n  items,\n}: {\n  title?: string;\n  text?: string;\n  items: { image?: LandingImage; caption?: string }[];\n  texts?: string;\n}) {\n  const pictures = items.filter((i): i is { image: LandingImage; caption?: string } =>\n    Boolean(i.image),\n  );\n  const dialog = useRef<HTMLDialogElement>(null);\n  const [open, setOpen] = useState(0);\n  const show = (i: number) => setOpen((i + pictures.length) % pictures.length);\n  const current = pictures[open];\n  return (\n    <Section id=\"gallery\" texts={texts} title={title} text={text}>\n      <ul className=\"grid grid-cols-2 gap-3 md:grid-cols-3\">\n        {pictures.map((item, i) => (\n          <li key={item.image.src}>\n            <figure>\n              <button\n                type=\"button\"\n                className=\"block w-full overflow-hidden rounded-lg focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none\"\n                aria-label={`Open ${item.image.alt}`}\n                onClick={() => {\n                  show(i);\n                  dialog.current?.showModal();\n                }}\n              >\n                <img\n                  src={item.image.src}\n                  alt={item.image.alt}\n                  loading=\"lazy\"\n                  width={600}\n                  height={400}\n                  className=\"aspect-[3/2] w-full object-cover transition-transform hover:scale-105\"\n                />\n              </button>\n              {item.caption && (\n                <figcaption\n                  className=\"mt-2 text-sm text-muted-foreground\"\n                  {...mark(texts, `items.${items.indexOf(item)}.caption`)}\n                >\n                  {item.caption}\n                </figcaption>\n              )}\n            </figure>\n          </li>\n        ))}\n      </ul>\n      {/* The browser's own dialog: Escape closes it, focus stays inside. */}\n      <dialog\n        ref={dialog}\n        aria-label={current?.image.alt}\n        className=\"m-auto max-h-[92vh] w-[min(1200px,94vw)] bg-transparent p-0 backdrop:bg-black/85\"\n        onClick={(e) => e.target === e.currentTarget && dialog.current?.close()}\n        onKeyDown={(e) => {\n          if (e.key === \"ArrowRight\") show(open + 1);\n          if (e.key === \"ArrowLeft\") show(open - 1);\n        }}\n      >\n        {current && (\n          <figure className=\"relative\">\n            <img\n              src={current.image.src}\n              alt={current.image.alt}\n              className=\"max-h-[80vh] w-full rounded-lg object-contain\"\n            />\n            {current.caption && (\n              <figcaption className=\"mt-3 text-center text-white\">{current.caption}</figcaption>\n            )}\n            <div className=\"mt-3 flex justify-center gap-2\">\n              {pictures.length > 1 && (\n                <button\n                  type=\"button\"\n                  aria-label=\"Previous picture\"\n                  className={buttonVariants({ variant: \"secondary\", size: \"icon\" })}\n                  onClick={() => show(open - 1)}\n                >\n                  <ChevronLeft aria-hidden />\n                </button>\n              )}\n              <button\n                type=\"button\"\n                aria-label=\"Close\"\n                className={buttonVariants({ variant: \"secondary\", size: \"icon\" })}\n                onClick={() => dialog.current?.close()}\n              >\n                <X aria-hidden />\n              </button>\n              {pictures.length > 1 && (\n                <button\n                  type=\"button\"\n                  aria-label=\"Next picture\"\n                  className={buttonVariants({ variant: \"secondary\", size: \"icon\" })}\n                  onClick={() => show(open + 1)}\n                >\n                  <ChevronRight aria-hidden />\n                </button>\n              )}\n            </div>\n          </figure>\n        )}\n      </dialog>\n    </Section>\n  );\n}\n",
  "src/kit/Markdown.tsx": "// Smithable app kit: Markdown fields. An editor with Write and Preview, and the formatted text.\n// The formatter loads only where Markdown is shown, so other pages do not pay for it.\nimport { lazy, Suspense, useState } from \"react\";\nimport { Textarea } from \"#/components/ui/input\";\nimport type { FieldControlProps } from \"./model\";\n\nconst Formatted = lazy(() => import(\"./MarkdownFormatted\"));\n\n/** Markdown as formatted text; raw HTML in it is shown as text, never run. */\nexport function MarkdownText({ text }: { text: string }) {\n  return (\n    <Suspense fallback={<p className=\"whitespace-pre-wrap\">{text}</p>}>\n      <Formatted text={text} />\n    </Suspense>\n  );\n}\n\nexport function MarkdownEditor({ value, onChange, record: _, ...control }: FieldControlProps) {\n  const [preview, setPreview] = useState(false);\n  const tab = (on: boolean) =>\n    on\n      ? \"rounded-md bg-muted px-3 py-1 text-sm font-medium\"\n      : \"rounded-md px-3 py-1 text-sm text-muted-foreground hover:text-foreground\";\n  return (\n    <div className=\"space-y-2\">\n      <div className=\"flex gap-1\">\n        <button\n          type=\"button\"\n          className={tab(!preview)}\n          aria-pressed={!preview}\n          onClick={() => setPreview(false)}\n        >\n          Write\n        </button>\n        <button\n          type=\"button\"\n          className={tab(preview)}\n          aria-pressed={preview}\n          onClick={() => setPreview(true)}\n        >\n          Preview\n        </button>\n      </div>\n      {preview ? (\n        <div className=\"min-h-24 rounded-md border px-3 py-2\">\n          {value.trim() ? (\n            <MarkdownText text={value} />\n          ) : (\n            <p className=\"text-muted-foreground\">Nothing to preview.</p>\n          )}\n        </div>\n      ) : (\n        <Textarea {...control} rows={10} value={value} onChange={(e) => onChange(e.target.value)} />\n      )}\n      <p className=\"text-xs text-muted-foreground\">\n        Markdown: **bold**, *italic*, ## a heading, - a list, [a link](https://…)\n      </p>\n    </div>\n  );\n}\n",
  "src/kit/MarkdownFormatted.tsx": "// Smithable app kit: Markdown turned into React elements (react-markdown), with no HTML string\n// anywhere to inject into. Headings start at h2, under the page's own h1; links to other sites\n// get rel=\"noopener nofollow\"; pictures belong in picture fields, not in the text.\nimport Markdown, { type Components } from \"react-markdown\";\n\nconst components: Components = {\n  h1: ({ node: _, ...props }) => <h2 className=\"mt-6 mb-3 text-2xl font-bold\" {...props} />,\n  h2: ({ node: _, ...props }) => <h3 className=\"mt-6 mb-3 text-xl font-bold\" {...props} />,\n  h3: ({ node: _, ...props }) => <h4 className=\"mt-5 mb-2 text-lg font-semibold\" {...props} />,\n  h4: ({ node: _, ...props }) => <h5 className=\"mt-4 mb-2 font-semibold\" {...props} />,\n  p: ({ node: _, ...props }) => <p className=\"my-3 leading-relaxed\" {...props} />,\n  ul: ({ node: _, ...props }) => <ul className=\"my-3 list-disc space-y-1 pl-6\" {...props} />,\n  ol: ({ node: _, ...props }) => <ol className=\"my-3 list-decimal space-y-1 pl-6\" {...props} />,\n  blockquote: ({ node: _, ...props }) => (\n    <blockquote className=\"my-4 border-l-4 pl-4 text-muted-foreground\" {...props} />\n  ),\n  code: ({ node: _, ...props }) => (\n    <code className=\"rounded bg-muted px-1 font-mono text-sm\" {...props} />\n  ),\n  a: ({ node: _, href, ...props }) => (\n    <a\n      href={href}\n      className=\"text-primary underline underline-offset-4\"\n      {...(href && /^https?:\\/\\//.test(href) ? { rel: \"noopener nofollow\" } : {})}\n      {...props}\n    />\n  ),\n};\n\nexport default function MarkdownFormatted({ text }: { text: string }) {\n  return (\n    <div className=\"[&>*:first-child]:mt-0\">\n      <Markdown components={components} disallowedElements={[\"img\"]} unwrapDisallowed>\n        {text}\n      </Markdown>\n    </div>\n  );\n}\n",
  "src/kit/ModelForm.tsx": "// Smithable app kit: a create/edit form for any model, validated with the model's Zod schema.\n// To customize a form, copy this file into src/custom/components/ and edit the copy.\nimport { Calculator, CircleAlert } from \"lucide-react\";\nimport { useRef, useState } from \"react\";\nimport type { z } from \"zod\";\nimport { Button } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\nimport { Label } from \"#/components/ui/input\";\nimport { FieldInput } from \"./FieldInput\";\nimport { formatValue, fromInput, toInput } from \"./format\";\nimport {\n  type AppUi,\n  editorMarker,\n  type FieldUi,\n  type ModelUi,\n  type Options,\n  textMarker,\n} from \"./model\";\n\ninterface ModelFormProps<S extends z.ZodType> {\n  ui: ModelUi;\n  app: AppUi;\n  schema: S;\n  /** The stored record when editing; omit to create a new one. */\n  initial?: Record<string, unknown>;\n  /** Values a new record starts with, e.g. the start of the hour chosen in a calendar. */\n  preset?: Record<string, unknown>;\n  /** Choices for reference fields, e.g. { customerId: [...] }. */\n  options?: Options;\n  submitLabel: string;\n  onSubmit: (values: z.output<S>) => Promise<unknown>;\n  onCancel?: () => void;\n  /** The cancel button's text, e.g. \"Back\" in a step of an onboarding. */\n  cancelLabel?: string;\n  onDelete?: () => Promise<unknown>;\n  /** Shows the record without letting it be changed. */\n  readOnly?: boolean;\n  /** These fields first, in this order; the others follow. */\n  fieldOrder?: string[];\n  /** The form's groups, columns and controls, when the page chose them (the ux file). */\n  sections?: { name: string; title: string; fields: string[] }[];\n  formColumns?: 1 | 2;\n  control?: Record<string, FieldUi[\"control\"]>;\n}\n\nexport function ModelForm<S extends z.ZodType>(props: ModelFormProps<S>) {\n  const {\n    app,\n    schema,\n    initial,\n    options,\n    submitLabel,\n    onSubmit,\n    onCancel,\n    cancelLabel,\n    onDelete,\n    readOnly,\n  } = props;\n  const ui = presented(props.ui, props);\n  const [inputs, setInputs] = useState(() =>\n    initialInputs(ui, initial ?? props.preset, app.timeZone, !initial),\n  );\n  const [errors, setErrors] = useState<Record<string, string>>({});\n  // Computed fields follow what has been entered so far.\n  // The record comes first so values that are not inputs (like related lines) are included.\n  const computed = ui.compute?.({ ...initial, ...storedValues(ui, inputs, app.timeZone) }) ?? {};\n  const [failure, setFailure] = useState<string>();\n  const [busy, setBusy] = useState(false);\n  const confirmDelete = useRef<HTMLDialogElement>(null);\n  const recordName = initial?.[ui.titleField];\n\n  async function submit(event: React.FormEvent) {\n    event.preventDefault();\n    const values = storedValues(ui, inputs, app.timeZone);\n    const result = schema.safeParse(values);\n    if (!result.success) {\n      const messages: Record<string, string> = {};\n      for (const issue of result.error.issues) {\n        const field = ui.fields.find((f) => f.name === issue.path[0]);\n        if (field && !messages[field.name])\n          messages[field.name] = friendly(field, issue, values[field.name]);\n      }\n      setErrors(messages);\n      return;\n    }\n    setErrors({});\n    await run(() => onSubmit(result.data));\n  }\n\n  async function run(action: () => Promise<unknown>) {\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      await action();\n    } catch (error) {\n      setFailure(failureMessage(ui, error));\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  // A long text, a picture or a list takes the full width when the form has two columns.\n  const wide = (field: FieldUi) =>\n    ui.formColumns === 2 &&\n    (field.kind === \"text\" ||\n      field.kind === \"markdown\" ||\n      field.kind === \"picture\" ||\n      field.kind === \"pictures\" ||\n      field.control === \"textarea\");\n  const renderField = (field: FieldUi) => {\n    const id = `field-${field.name}`;\n    const error = errors[field.name];\n    const inline = field.kind === \"bool\";\n    const described =\n      [field.help && `${id}-help`, error && `${id}-error`].filter(Boolean).join(\" \") || undefined;\n    return (\n      <div\n        key={field.name}\n        data-kit=\"field\"\n        data-field={field.name}\n        className={`${inline ? \"flex items-center gap-3\" : \"space-y-2\"}${wide(field) ? \" sm:col-span-2\" : \"\"}`}\n        {...editorMarker(ui, field, \"field\")}\n      >\n        {!inline && (\n          <Label htmlFor={id} data-part=\"label\">\n            <span {...textMarker(`models.${ui.model}.fields.${field.name}.label`)}>\n              {field.label}\n            </span>\n            {field.required && <span className=\"text-destructive\"> *</span>}\n          </Label>\n        )}\n        {field.computed ? (\n          <p\n            id={id}\n            className=\"flex min-h-control items-center gap-2 rounded-md bg-muted px-3 text-sm font-semibold tabular-nums\"\n          >\n            <Calculator aria-hidden className=\"size-5 text-muted-foreground\" />\n            {formatValue(field, computed[field.name], app)}\n            <span className=\"sr-only\">(calculated)</span>\n          </p>\n        ) : (\n          <FieldInput\n            field={field}\n            id={id}\n            value={inputs[field.name] ?? \"\"}\n            invalid={error !== undefined}\n            describedBy={described}\n            options={options}\n            record={typeof initial?.id === \"number\" ? initial.id : undefined}\n            onChange={(value) => setInputs((current) => ({ ...current, [field.name]: value }))}\n          />\n        )}\n        {inline && (\n          <Label htmlFor={id} data-part=\"label\">\n            {field.label}\n          </Label>\n        )}\n        {field.help && (\n          <p id={`${id}-help`} data-part=\"help\" className=\"text-sm text-muted-foreground\">\n            {field.help}\n          </p>\n        )}\n        {error && (\n          <p\n            id={`${id}-error`}\n            data-part=\"error\"\n            className=\"flex items-center gap-1.5 text-sm text-destructive\"\n          >\n            <CircleAlert aria-hidden className=\"size-4 shrink-0\" />\n            {error}\n          </p>\n        )}\n      </div>\n    );\n  };\n\n  return (\n    <Card data-kit=\"model-form\" className=\"max-w-3xl\">\n      <form onSubmit={submit} noValidate className=\"space-y-6 p-card\">\n        {!readOnly && ui.fields.some((f) => f.required && !f.computed) && (\n          <p className=\"text-sm text-muted-foreground\">\n            Fields marked <span className=\"text-destructive\">*</span> are required.\n          </p>\n        )}\n        <fieldset disabled={readOnly} className=\"space-y-6\">\n          {groups(ui).map((group) => (\n            <div key={group.name ?? \"\"} data-part=\"section\" className=\"space-y-4\">\n              {group.title && (\n                <h2 className=\"text-base font-semibold\" data-part=\"title\">\n                  {group.title}\n                </h2>\n              )}\n              <div className={ui.formColumns === 2 ? \"grid gap-6 sm:grid-cols-2\" : \"space-y-6\"}>\n                {group.fields.map((field) => renderField(field))}\n              </div>\n            </div>\n          ))}\n        </fieldset>\n        {failure && (\n          <p\n            role=\"alert\"\n            className=\"flex items-start gap-2 rounded-md border border-destructive p-3 text-sm text-destructive\"\n          >\n            <CircleAlert aria-hidden className=\"mt-0.5 size-4 shrink-0\" />\n            {failure}\n          </p>\n        )}\n        <div data-part=\"actions\" className=\"flex flex-wrap items-center gap-3 border-t pt-6\">\n          {!readOnly && (\n            <Button type=\"submit\" disabled={busy}>\n              {busy ? \"Saving…\" : submitLabel}\n            </Button>\n          )}\n          {onCancel && (\n            <Button type=\"button\" variant=\"outline\" onClick={onCancel} disabled={busy}>\n              {cancelLabel ?? (readOnly ? \"Back\" : \"Cancel\")}\n            </Button>\n          )}\n          {onDelete && (\n            <Button\n              type=\"button\"\n              variant=\"outline\"\n              className=\"ml-auto border-destructive text-destructive\"\n              disabled={busy}\n              onClick={() => confirmDelete.current?.showModal()}\n            >\n              Delete\n            </Button>\n          )}\n          {onDelete && (\n            // Opening it focuses Cancel, the first button; Escape closes it.\n            <dialog\n              ref={confirmDelete}\n              aria-labelledby=\"delete-title\"\n              className=\"m-auto w-[calc(100%-2.5rem)] max-w-md rounded-lg border bg-card p-card text-card-foreground backdrop:bg-black/50\"\n            >\n              <h2 id=\"delete-title\" className=\"text-lg font-semibold\">\n                Delete{\" \"}\n                {typeof recordName === \"string\" && recordName\n                  ? `“${recordName}”`\n                  : `this ${ui.label.toLowerCase()}`}\n                ?\n              </h2>\n              <p className=\"mt-2 text-muted-foreground\">This cannot be undone.</p>\n              <div className=\"mt-6 flex flex-wrap justify-end gap-3\">\n                <Button\n                  type=\"button\"\n                  variant=\"outline\"\n                  onClick={() => confirmDelete.current?.close()}\n                >\n                  Cancel\n                </Button>\n                <Button\n                  type=\"button\"\n                  variant=\"destructive\"\n                  onClick={() => {\n                    confirmDelete.current?.close();\n                    run(onDelete);\n                  }}\n                >\n                  Delete {ui.label.toLowerCase()}\n                </Button>\n              </div>\n            </dialog>\n          )}\n        </div>\n      </form>\n    </Card>\n  );\n}\n\n/** A message a non-developer understands, instead of Zod's technical text. */\nfunction friendly(field: FieldUi, issue: z.core.$ZodIssue, value: unknown): string {\n  if (value === null || value === undefined) return \"Required\";\n  if (issue.code !== \"invalid_type\") return issue.message;\n  switch (field.kind) {\n    case \"int\":\n      return \"Enter a whole number\";\n    case \"decimal\":\n    case \"money\":\n      return \"Enter a number\";\n    case \"date\":\n      return \"Enter a valid date\";\n    case \"datetime\":\n      return \"Enter a valid date and time\";\n    default:\n      return issue.message;\n  }\n}\n\n/** Explains server errors (see refusal in access.ts): a unique field taken, a record in use. */\nfunction failureMessage(ui: ModelUi, error: unknown): string {\n  const message = error instanceof Error ? error.message : \"\";\n  const column = /^taken:(\\w+)$/.exec(message)?.[1];\n  const field = ui.fields.find(\n    (f) => f.name.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`) === column,\n  );\n  if (field)\n    return `Another ${ui.label.toLowerCase()} already has this ${field.label.toLowerCase()}.`;\n  if (message === \"in-use\")\n    return `This ${ui.label.toLowerCase()} is still used by other records. Change or delete those first.`;\n  if (message === \"full\") return \"No places left.\";\n  const booked = /^booked:(\\d+)$/.exec(message)?.[1];\n  if (booked)\n    return `${booked} ${booked === \"1\" ? \"is\" : \"are\"} already taken; the number cannot go below that.`;\n  return message || \"Something went wrong. Please try again.\";\n}\n\n/** Form inputs for a record being edited, or for a new one: defaults, including formula defaults. */\nfunction initialInputs(\n  ui: ModelUi,\n  initial: Record<string, unknown> | undefined,\n  timeZone: string | undefined,\n  /** A new record: what `initial` leaves out comes from the defaults. */\n  fresh = false,\n): Record<string, string | boolean> {\n  const inputs: Record<string, string | boolean> = {};\n  const values: Record<string, unknown> = {};\n  for (const field of ui.fields) {\n    if (field.computed) continue;\n    const suggested = ui.defaults?.[field.name];\n    const value =\n      initial && (!fresh || initial[field.name] !== undefined)\n        ? initial[field.name]\n        : suggested\n          ? suggested(values)\n          : field.default;\n    values[field.name] = value;\n    inputs[field.name] = toInput(field, value, timeZone);\n  }\n  return inputs;\n}\n\n/** The values to validate and save: every entered field, never computed ones. */\nfunction storedValues(\n  ui: ModelUi,\n  inputs: Record<string, string | boolean>,\n  timeZone: string | undefined,\n): Record<string, unknown> {\n  return Object.fromEntries(\n    ui.fields\n      .filter((f) => !f.computed)\n      .map((f) => [f.name, fromInput(f, inputs[f.name] ?? \"\", timeZone)]),\n  );\n}\n\n/** The model's fields with `order` first, in that order. */\n/** The model's description with the page's presentation: field order, sections, columns, controls. */\nfunction presented(\n  ui: ModelUi,\n  page: {\n    fieldOrder?: string[];\n    sections?: ModelUi[\"sections\"];\n    formColumns?: 1 | 2;\n    control?: Record<string, FieldUi[\"control\"]>;\n  },\n): ModelUi {\n  const order = page.fieldOrder ?? page.sections?.flatMap((s) => s.fields);\n  const rank = (name: string) => {\n    const i = order?.indexOf(name) ?? -1;\n    return i === -1 ? (order?.length ?? 0) : i;\n  };\n  const fields = [...ui.fields]\n    .sort((a, b) => (order ? rank(a.name) - rank(b.name) : 0))\n    .map((f) => (page.control?.[f.name] ? { ...f, control: page.control[f.name] } : f));\n  return {\n    ...ui,\n    fields,\n    ...(page.sections ? { sections: page.sections } : {}),\n    ...(page.formColumns ? { formColumns: page.formColumns } : {}),\n  };\n}\n\n/** The form's fields in their groups: the sections given, then the rest under no heading. */\nfunction groups(ui: ModelUi): { name?: string; title?: string; fields: FieldUi[] }[] {\n  if (!ui.sections?.length) return [{ fields: ui.fields }];\n  const placed = new Set(ui.sections.flatMap((s) => s.fields));\n  const byName = new Map(ui.fields.map((f) => [f.name, f]));\n  const sections = ui.sections.map((s) => ({\n    name: s.name,\n    title: s.title,\n    fields: s.fields.flatMap((name) => byName.get(name) ?? []),\n  }));\n  const rest = ui.fields.filter((f) => !placed.has(f.name));\n  return rest.length ? [...sections, { fields: rest }] : sections;\n}\n",
  "src/kit/ModelTable.tsx": "// Smithable app kit: a table of records for any model. Choice values show as badges.\n// To customize a table, copy this file into src/custom/components/ and edit the copy.\nimport { ChevronRight, Heart, ImageIcon, type LucideIcon } from \"lucide-react\";\nimport { Badge } from \"#/components/ui/badge\";\nimport { Card } from \"#/components/ui/card\";\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"#/components/ui/table\";\nimport { cn } from \"#/lib/utils\";\nimport { displayValue, formatValue } from \"./format\";\nimport { type AppUi, editorMarker, type RecordFieldUi, type RecordUi, type Row } from \"./model\";\n\ninterface ModelTableProps<R extends Row> {\n  ui: RecordUi<R>;\n  app: AppUi;\n  rows: R[];\n  /** Opens a row; without it rows are not clickable. */\n  onOpen?: (row: R) => void;\n  /** Columns to leave out, e.g. the reference back to the record a list belongs to. */\n  hide?: (keyof R & string)[];\n  /** Shown when there are no records, e.g. a \"New …\" button. */\n  emptyAction?: React.ReactNode;\n  /** Replaces \"No … yet\", e.g. when a search matches nothing. */\n  emptyMessage?: string;\n  /** The columns to show, in order, instead of the model's default ones. */\n  columns?: (keyof R & string)[];\n  /** A second field shown under a column's value, e.g. { email: \"phone\" }. */\n  below?: Partial<Record<keyof R & string, keyof R & string>>;\n  /** The page showing the table, so the preview editor can change its columns. */\n  page?: string;\n  /** Cards on wide screens too, instead of a table (a phone shows cards anyway). */\n  view?: \"table\" | \"cards\";\n  /** The model's icon, shown where a picture is missing. */\n  icon?: LucideIcon;\n  /** A heart on each record: the ids the viewer saved, and what a click does (sign in, for a visitor). */\n  saved?: { ids: number[]; onToggle: (id: number) => void };\n}\n\n/** Saves a record for the viewer, or unsaves it: a toggle above the row's own link. */\nexport function SaveButton({\n  saved,\n  label,\n  onToggle,\n}: {\n  saved: boolean;\n  label: string;\n  onToggle: () => void;\n}) {\n  return (\n    <button\n      type=\"button\"\n      data-part=\"save\"\n      aria-pressed={saved}\n      aria-label={`Save ${label}`}\n      onClick={onToggle}\n      className=\"relative z-10 -m-2.5 flex size-11 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring\"\n    >\n      <Heart aria-hidden className={cn(\"size-5\", saved && \"fill-current text-primary\")} />\n    </button>\n  );\n}\n\n/** Where a picture is missing: the theme's muted tone with the model's icon. */\nexport function PicturePlaceholder({\n  icon: Icon = ImageIcon,\n  className,\n}: {\n  icon?: LucideIcon;\n  className?: string;\n}) {\n  return (\n    <div\n      aria-hidden\n      data-part=\"placeholder\"\n      className={cn(\"flex items-center justify-center bg-muted text-muted-foreground\", className)}\n    >\n      <Icon className=\"size-1/3 max-h-12 max-w-12 min-h-4 min-w-4\" />\n    </div>\n  );\n}\n\nexport function ModelTable<R extends Row>({\n  ui,\n  app,\n  rows,\n  onOpen,\n  hide = [],\n  emptyAction,\n  emptyMessage,\n  columns: chosen,\n  below = {},\n  page,\n  view = \"table\",\n  icon,\n  saved,\n}: ModelTableProps<R>) {\n  const shown = ui.compute ? rows.map((row) => ({ ...row, ...ui.compute?.(row) }) as R) : rows;\n  const columns = (chosen ?? ui.columns)\n    .filter((name) => !(hide as string[]).includes(name))\n    .flatMap((name) => ui.fields.filter((f) => f.name === name));\n  if (rows.length === 0) {\n    return (\n      <Card\n        data-kit=\"model-table\"\n        data-part=\"empty\"\n        className=\"flex flex-col items-center gap-3 px-6 py-16 text-center\"\n      >\n        {emptyMessage ? (\n          <p className=\"font-medium\">{emptyMessage}</p>\n        ) : (\n          <>\n            <p className=\"font-medium\">No {ui.pluralLabel.toLowerCase()} yet</p>\n            <p className=\"text-sm text-muted-foreground\">Create the first one to get started.</p>\n            {emptyAction}\n          </>\n        )}\n      </Card>\n    );\n  }\n  const second = (field: RecordFieldUi<R>) =>\n    ui.fields.find((f) => f.name === (below as Record<string, string>)[field.name]);\n  // A column with a second field below its value: both on their own line.\n  const stacked = (field: RecordFieldUi<R>, row: R) => {\n    const other = second(field);\n    return other ? (\n      <>\n        <span className=\"block\">{cell(field, row)}</span>\n        <span className=\"block text-muted-foreground\">{cell(other, row)}</span>\n      </>\n    ) : (\n      cell(field, row)\n    );\n  };\n  const title = columns.find((f) => f.name === ui.titleField) ?? columns[0];\n  // Cards view shows the picture on top, so not again among the details.\n  const others = columns.filter(\n    (f) => f !== title && !(view === \"cards\" && (f.kind === \"picture\" || f.kind === \"pictures\")),\n  );\n  const status = others.find((f) => f.kind === \"choice\");\n  const amount = others.find((f) => numeric(f.kind));\n  const date = others.find((f) => f.kind === \"date\" || f.kind === \"datetime\");\n  const secondary = others.find((f) => f !== status && f !== amount && f !== date);\n  const description = ui.fields.find((f) => f.name === ui.descriptionField);\n  const pictureField = ui.fields.find((f) => f.kind === \"picture\" || f.kind === \"pictures\");\n  // A picture's address; for several pictures, the cover's (the first).\n  const pictureSrc = (field: RecordFieldUi<R>, row: R) =>\n    `/files/${ui.model?.replace(/[A-Z]/g, (c, i) => `${i ? \"-\" : \"\"}${c.toLowerCase()}`)}/${row.id}/${field.name}${field.kind === \"pictures\" ? \"/0\" : \"\"}`;\n  const cell = (field: RecordFieldUi<R>, row: R) => {\n    const text = formatValue(field, displayValue(field, row), app);\n    if ((field.kind === \"picture\" || field.kind === \"pictures\") && text === \"—\")\n      return <PicturePlaceholder icon={icon} className=\"size-10 rounded-md border\" />;\n    // A picture as a thumbnail; its address is the record's, so it is as private as the record.\n    if ((field.kind === \"picture\" || field.kind === \"pictures\") && text !== \"—\" && ui.model)\n      return (\n        <img\n          src={pictureSrc(field, row)}\n          alt={text}\n          className=\"h-10 w-10 rounded-md border object-cover\"\n        />\n      );\n    if (field.kind !== \"choice\" || text === \"—\") return text;\n    const tone = field.choices?.find((c) => c.value === displayValue(field, row))?.tone;\n    return <Badge variant={tone}>{text}</Badge>;\n  };\n  // Opening a record is a real button (keyboard and screen readers), stretched over the row.\n  const open = (row: R, children: React.ReactNode, className?: string) =>\n    onOpen ? (\n      <button\n        type=\"button\"\n        onClick={() => onOpen(row)}\n        className={cn(\n          \"cursor-pointer text-left font-semibold outline-none after:absolute after:inset-0 focus-visible:after:rounded-md focus-visible:after:ring-2 focus-visible:after:ring-ring\",\n          className,\n        )}\n      >\n        {children}\n      </button>\n    ) : (\n      children\n    );\n  const heart = (row: R) =>\n    saved && (\n      <SaveButton\n        saved={saved.ids.includes(row.id)}\n        label={title ? formatValue(title, displayValue(title, row), app) : String(row.id)}\n        onToggle={() => saved.onToggle(row.id)}\n      />\n    );\n  return (\n    <div data-kit=\"model-table\">\n      {/* Phones: one card per record: its name and status, a contact or other identifier, its description, then a date and a key amount. */}\n      <ul\n        className={\n          view === \"cards\" ? \"grid gap-3 md:grid-cols-2 xl:grid-cols-3\" : \"space-y-3 md:hidden\"\n        }\n      >\n        {shown.map((row) => (\n          <li key={row.id} data-part=\"row\">\n            <Card\n              className={cn(\n                \"relative space-y-3 p-5 hover:bg-accent/40\",\n                view === \"cards\" && pictureField && \"overflow-hidden pt-0\",\n              )}\n            >\n              {/* Cards of a model with pictures show the record's, or a placeholder without one. */}\n              {view === \"cards\" &&\n                pictureField &&\n                (formatValue(pictureField, displayValue(pictureField, row), app) !== \"—\" ? (\n                  <img\n                    src={pictureSrc(pictureField, row)}\n                    alt={formatValue(pictureField, displayValue(pictureField, row), app)}\n                    loading=\"lazy\"\n                    className=\"-mx-5 aspect-[3/2] w-[calc(100%+2.5rem)] max-w-none object-cover\"\n                  />\n                ) : (\n                  <PicturePlaceholder\n                    icon={icon}\n                    className=\"-mx-5 aspect-[3/2] w-[calc(100%+2.5rem)]\"\n                  />\n                ))}\n              <div className=\"flex items-start justify-between gap-3\">\n                <div className=\"min-w-0 space-y-1\">\n                  {title && open(row, cell(title, row), \"break-words text-base font-semibold\")}\n                  {secondary && <p className=\"break-words text-sm\">{stacked(secondary, row)}</p>}\n                  {description && Boolean(displayValue(description, row)) && (\n                    <p\n                      data-part=\"description\"\n                      className=\"line-clamp-2 break-words text-sm text-muted-foreground\"\n                    >\n                      {formatValue(description, displayValue(description, row), app)}\n                    </p>\n                  )}\n                </div>\n                {status || saved ? (\n                  <div className=\"flex shrink-0 items-start gap-3\">\n                    {status && cell(status, row)}\n                    {heart(row)}\n                  </div>\n                ) : (\n                  onOpen && <ChevronRight aria-hidden className=\"mt-0.5 size-5 shrink-0\" />\n                )}\n              </div>\n              {(date || amount) && (\n                <p className=\"flex items-baseline justify-between gap-3 pt-2 text-sm\">\n                  <span className=\"text-muted-foreground\">\n                    {date ? cell(date, row) : amount?.label}\n                  </span>\n                  {amount && (\n                    <span className=\"text-lg font-semibold whitespace-nowrap tabular-nums\">\n                      {cell(amount, row)}\n                    </span>\n                  )}\n                </p>\n              )}\n            </Card>\n          </li>\n        ))}\n      </ul>\n      {view === \"table\" && (\n        <Card className=\"hidden overflow-hidden md:block\">\n          <Table>\n            <TableHeader data-part=\"header\">\n              <TableRow className=\"hover:bg-transparent\">\n                {columns.map((field) => (\n                  <TableHead\n                    key={field.name}\n                    className={numeric(field.kind) ? \"text-right\" : undefined}\n                    {...editorMarker(ui, field, \"column\", page)}\n                  >\n                    {second(field) ? `${field.label} / ${second(field)?.label}` : field.label}\n                  </TableHead>\n                ))}\n                {saved && (\n                  <TableHead className=\"w-12\">\n                    <span className=\"sr-only\">Saved</span>\n                  </TableHead>\n                )}\n              </TableRow>\n            </TableHeader>\n            <TableBody>\n              {shown.map((row) => (\n                <TableRow\n                  key={row.id}\n                  data-part=\"row\"\n                  className={onOpen ? \"relative cursor-pointer\" : undefined}\n                >\n                  {columns.map((field) => (\n                    <TableCell\n                      key={field.name}\n                      data-part=\"cell\"\n                      data-field={field.name}\n                      className={cn(\n                        numeric(field.kind) && \"text-right tabular-nums\",\n                        field.name === ui.titleField && \"font-semibold\",\n                      )}\n                    >\n                      {field === title ? open(row, cell(field, row)) : stacked(field, row)}\n                    </TableCell>\n                  ))}\n                  {saved && <TableCell className=\"py-0\">{heart(row)}</TableCell>}\n                </TableRow>\n              ))}\n            </TableBody>\n          </Table>\n        </Card>\n      )}\n    </div>\n  );\n}\n\nfunction numeric(kind: string): boolean {\n  return kind === \"int\" || kind === \"decimal\" || kind === \"money\";\n}\n",
  "src/kit/Onboarding.tsx": "// Smithable app kit: the frame of a first-time setup in steps, with its progress.\n// To change it, copy this file into src/custom/components/ and edit the copy.\nimport { cn } from \"#/lib/utils\";\n\nexport function OnboardingLayout({\n  title,\n  subtitle,\n  step,\n  count,\n  stepTitle,\n  stepText,\n  footer,\n  children,\n}: {\n  title: string;\n  subtitle?: string;\n  /** The current step, from 0. */\n  step: number;\n  count: number;\n  stepTitle: string;\n  stepText?: string;\n  /** E.g. a \"Do this later\" link. */\n  footer?: React.ReactNode;\n  children: React.ReactNode;\n}) {\n  return (\n    <main data-kit=\"onboarding\" className=\"mx-auto max-w-3xl px-5 py-12 sm:py-20\">\n      <h1 className=\"text-3xl font-bold sm:text-4xl\">{title}</h1>\n      {subtitle && <p className=\"mt-2 text-muted-foreground\">{subtitle}</p>}\n      <p className=\"mt-8 text-xs font-semibold uppercase tracking-wide text-muted-foreground\">\n        Step {step + 1} of {count}\n      </p>\n      <div aria-hidden className=\"mt-2 flex gap-2\">\n        {Array.from({ length: count }, (_, i) => i).map((n) => (\n          <span\n            key={n}\n            className={cn(\"h-1 flex-1 rounded-full\", n <= step ? \"bg-primary\" : \"bg-border\")}\n          />\n        ))}\n      </div>\n      <h2 className=\"mt-8 text-xl font-semibold\">{stepTitle}</h2>\n      {stepText && <p className=\"mt-1 text-muted-foreground\">{stepText}</p>}\n      <div className=\"mt-4\">{children}</div>\n      {footer && <div className=\"mt-6\">{footer}</div>}\n    </main>\n  );\n}\n",
  "src/kit/PictureInput.tsx": "// Smithable app kit: choosing a picture for a record. The browser scales it to at most 1600 px\n// on the long side and encodes WebP, so a phone's 12 MB photo never travels; the server checks\n// the file again (src/kit/uploads.ts). The form keeps the picture as JSON text, as its other\n// values are text, and stores { file, alt, width, height } on the record.\nimport { ChevronLeft, ChevronRight, ImagePlus, X } from \"lucide-react\";\nimport { useId, useRef, useState } from \"react\";\nimport { Button } from \"#/components/ui/button\";\nimport { Input, Label } from \"#/components/ui/input\";\nimport type { FieldControlProps } from \"./model\";\n\nexport interface PictureValue {\n  file: string;\n  alt: string;\n  width: number;\n  height: number;\n}\n\nconst MAX_SIDE = 1600;\n\n/** A picture as WebP, scaled down to at most MAX_SIDE on the long side. */\nasync function toWebp(file: File): Promise<Blob> {\n  const bitmap = await createImageBitmap(file);\n  const scale = Math.min(1, MAX_SIDE / Math.max(bitmap.width, bitmap.height));\n  const canvas = document.createElement(\"canvas\");\n  canvas.width = Math.round(bitmap.width * scale);\n  canvas.height = Math.round(bitmap.height * scale);\n  canvas.getContext(\"2d\")?.drawImage(bitmap, 0, 0, canvas.width, canvas.height);\n  bitmap.close();\n  return new Promise((resolve, reject) =>\n    canvas.toBlob(\n      (blob) => (blob ? resolve(blob) : reject(new Error(\"The picture could not be read.\"))),\n      \"image/webp\",\n      0.82,\n    ),\n  );\n}\n\n/** The picture input for one field of `model`, bound for the form's `input` hook. */\nexport function bindPicture(model: string, field: string) {\n  return (props: FieldControlProps) => <PictureInput {...props} model={model} field={field} />;\n}\n\nexport function PictureInput({\n  id,\n  name,\n  value,\n  record,\n  onChange,\n  model,\n  field,\n  ...aria\n}: FieldControlProps & { model: string; field: string }) {\n  const picture = parse(value);\n  // The description may be edited while a picture uploads: the upload keeps the latest.\n  const latest = useRef(value);\n  latest.current = value;\n  const [busy, setBusy] = useState(false);\n  const [failure, setFailure] = useState<string>();\n  const [preview, setPreview] = useState<string>();\n  const fileInput = useRef<HTMLInputElement>(null);\n  const altId = useId();\n\n  async function choose(file: File | undefined) {\n    if (!file) return;\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      const webp = await toWebp(file);\n      const response = await fetch(`/files/${model}/${field}`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"image/webp\" },\n        body: webp,\n      });\n      if (!response.ok) throw new Error((await response.text()) || \"The picture was refused.\");\n      const stored = (await response.json()) as Omit<PictureValue, \"alt\">;\n      if (preview) URL.revokeObjectURL(preview);\n      setPreview(URL.createObjectURL(webp));\n      onChange(JSON.stringify({ ...stored, alt: parse(latest.current)?.alt ?? \"\" }));\n    } catch (error) {\n      setFailure(error instanceof Error ? error.message : \"The picture could not be added.\");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  // A stored picture shows from its record's address; a picture just chosen from the browser's copy.\n  const src =\n    preview ?? (picture && record !== undefined ? `/files/${model}/${record}/${field}` : undefined);\n  return (\n    <div className=\"space-y-3\" {...aria}>\n      {picture ? (\n        <div className=\"flex flex-wrap items-start gap-4\">\n          {src ? (\n            <img\n              src={src}\n              alt={picture.alt}\n              width={picture.width}\n              height={picture.height}\n              className=\"h-32 w-auto rounded-md border object-cover\"\n            />\n          ) : (\n            <div className=\"flex h-32 w-32 items-center justify-center rounded-md border bg-muted text-sm text-muted-foreground\">\n              {picture.width}×{picture.height}\n            </div>\n          )}\n          <div className=\"grow space-y-2\">\n            <Label htmlFor={altId}>Description (for those who cannot see it)</Label>\n            <Input\n              id={altId}\n              value={picture.alt}\n              maxLength={200}\n              onChange={(e) => onChange(JSON.stringify({ ...picture, alt: e.target.value }))}\n            />\n            <div className=\"flex gap-2\">\n              <Button\n                type=\"button\"\n                variant=\"outline\"\n                disabled={busy}\n                onClick={() => fileInput.current?.click()}\n              >\n                Replace\n              </Button>\n              <Button type=\"button\" variant=\"ghost\" disabled={busy} onClick={() => onChange(\"\")}>\n                <X aria-hidden className=\"size-4\" /> Remove\n              </Button>\n            </div>\n          </div>\n        </div>\n      ) : (\n        <Button\n          type=\"button\"\n          variant=\"outline\"\n          disabled={busy}\n          onClick={() => fileInput.current?.click()}\n        >\n          <ImagePlus aria-hidden className=\"size-4\" /> {busy ? \"Adding…\" : \"Choose a picture\"}\n        </Button>\n      )}\n      <input\n        ref={fileInput}\n        id={id}\n        name={name}\n        type=\"file\"\n        accept=\"image/*\"\n        className=\"sr-only\"\n        tabIndex={-1}\n        onChange={(e) => choose(e.target.files?.[0])}\n      />\n      {failure && (\n        <p role=\"alert\" className=\"text-sm text-destructive\">\n          {failure}\n        </p>\n      )}\n    </div>\n  );\n}\n\nfunction parse(value: string): PictureValue | undefined {\n  try {\n    const parsed = value ? (JSON.parse(value) as PictureValue) : undefined;\n    return parsed && typeof parsed.file === \"string\" ? parsed : undefined;\n  } catch {\n    return undefined;\n  }\n}\n\n/** The pictures input (several pictures, the first the cover) for one field of `model`. */\nexport function bindPictures(model: string, field: string, max: number) {\n  return (props: FieldControlProps) => (\n    <PicturesInput {...props} model={model} field={field} max={max} />\n  );\n}\n\n/**\n * Several pictures as a strip: add (several at once), describe, move, remove; the first is the\n * cover. The form keeps them as JSON text, a list of { file, alt, width, height }.\n */\nexport function PicturesInput({\n  id,\n  name,\n  value,\n  record,\n  onChange,\n  model,\n  field,\n  max,\n  ...aria\n}: FieldControlProps & { model: string; field: string; max: number }) {\n  const pictures = parseList(value);\n  // A stored picture is served by its place in the saved record, which moving does not change\n  // until the record is saved; a new one shows from the browser's copy.\n  const [stored] = useState(() => new Map(parseList(value).map((p, i) => [p.file, i])));\n  const [previews] = useState(() => new Map<string, string>());\n  const latest = useRef(pictures);\n  latest.current = pictures;\n  const [busy, setBusy] = useState(false);\n  const [failure, setFailure] = useState<string>();\n  const [dragged, setDragged] = useState<number>();\n  const fileInput = useRef<HTMLInputElement>(null);\n  const set = (next: PictureValue[]) => onChange(next.length ? JSON.stringify(next) : \"\");\n  const move = (from: number, to: number) => {\n    const next = [...pictures];\n    const [moved] = next.splice(from, 1);\n    if (moved) next.splice(to, 0, moved);\n    set(next);\n  };\n\n  async function add(files: FileList | null) {\n    if (!files?.length) return;\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      for (const file of [...files].slice(0, max - latest.current.length)) {\n        const webp = await toWebp(file);\n        const response = await fetch(`/files/${model}/${field}`, {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"image/webp\" },\n          body: webp,\n        });\n        if (!response.ok) throw new Error((await response.text()) || \"The picture was refused.\");\n        const saved = (await response.json()) as Omit<PictureValue, \"alt\">;\n        previews.set(saved.file, URL.createObjectURL(webp));\n        latest.current = [...latest.current, { ...saved, alt: \"\" }];\n        set(latest.current);\n      }\n      if (files.length > max - pictures.length)\n        setFailure(`At most ${max} pictures; the rest were left out.`);\n    } catch (error) {\n      setFailure(error instanceof Error ? error.message : \"The picture could not be added.\");\n    } finally {\n      setBusy(false);\n      if (fileInput.current) fileInput.current.value = \"\";\n    }\n  }\n\n  const src = (p: PictureValue) =>\n    previews.get(p.file) ??\n    (record !== undefined && stored.has(p.file)\n      ? `/files/${model}/${record}/${field}/${stored.get(p.file)}`\n      : undefined);\n  return (\n    <div className=\"space-y-3\" {...aria}>\n      {pictures.length > 0 && (\n        <ol className=\"grid gap-4 sm:grid-cols-2\">\n          {pictures.map((p, i) => (\n            <li\n              key={p.file}\n              data-part=\"picture\"\n              draggable\n              onDragStart={() => setDragged(i)}\n              onDragOver={(e) => e.preventDefault()}\n              onDrop={() => {\n                if (dragged !== undefined && dragged !== i) move(dragged, i);\n                setDragged(undefined);\n              }}\n              className=\"space-y-2 rounded-md border p-3\"\n            >\n              <div className=\"relative\">\n                {src(p) ? (\n                  // Opens large: a link, so it works where the form is read only.\n                  <a href={src(p)} target=\"_blank\" rel=\"noreferrer\">\n                    <img\n                      src={src(p)}\n                      alt={p.alt}\n                      width={p.width}\n                      height={p.height}\n                      className=\"aspect-[3/2] w-full rounded-md object-cover\"\n                    />\n                  </a>\n                ) : (\n                  <div className=\"flex aspect-[3/2] items-center justify-center rounded-md bg-muted text-sm text-muted-foreground\">\n                    {p.width}×{p.height}\n                  </div>\n                )}\n                {i === 0 && (\n                  <span className=\"absolute top-2 left-2 rounded-md bg-background px-2 py-0.5 text-xs font-semibold\">\n                    Cover\n                  </span>\n                )}\n              </div>\n              <Label htmlFor={`${id}-alt-${i}`}>Description of picture {i + 1}</Label>\n              <Input\n                id={`${id}-alt-${i}`}\n                value={p.alt}\n                maxLength={200}\n                onChange={(e) =>\n                  set(pictures.map((q, j) => (j === i ? { ...q, alt: e.target.value } : q)))\n                }\n              />\n              <div className=\"flex flex-wrap gap-2\">\n                <Button\n                  type=\"button\"\n                  variant=\"outline\"\n                  disabled={busy || i === 0}\n                  aria-label={`Move picture ${i + 1} earlier`}\n                  onClick={() => move(i, i - 1)}\n                >\n                  <ChevronLeft aria-hidden className=\"size-4\" />\n                </Button>\n                <Button\n                  type=\"button\"\n                  variant=\"outline\"\n                  disabled={busy || i === pictures.length - 1}\n                  aria-label={`Move picture ${i + 1} later`}\n                  onClick={() => move(i, i + 1)}\n                >\n                  <ChevronRight aria-hidden className=\"size-4\" />\n                </Button>\n                <Button\n                  type=\"button\"\n                  variant=\"ghost\"\n                  disabled={busy}\n                  aria-label={`Remove picture ${i + 1}`}\n                  onClick={() => set(pictures.filter((_, j) => j !== i))}\n                >\n                  <X aria-hidden className=\"size-4\" /> Remove\n                </Button>\n              </div>\n            </li>\n          ))}\n        </ol>\n      )}\n      {pictures.length < max && (\n        <Button\n          type=\"button\"\n          variant=\"outline\"\n          disabled={busy}\n          onClick={() => fileInput.current?.click()}\n        >\n          <ImagePlus aria-hidden className=\"size-4\" />{\" \"}\n          {busy ? \"Adding…\" : pictures.length ? \"Add pictures\" : \"Choose pictures\"}\n        </Button>\n      )}\n      <input\n        ref={fileInput}\n        id={id}\n        name={name}\n        type=\"file\"\n        accept=\"image/*\"\n        multiple\n        className=\"sr-only\"\n        tabIndex={-1}\n        onChange={(e) => add(e.target.files)}\n      />\n      {failure && (\n        <p role=\"alert\" className=\"text-sm text-destructive\">\n          {failure}\n        </p>\n      )}\n    </div>\n  );\n}\n\nfunction parseList(value: string): PictureValue[] {\n  try {\n    const parsed = value ? (JSON.parse(value) as PictureValue[]) : [];\n    return Array.isArray(parsed) ? parsed.filter((p) => typeof p?.file === \"string\") : [];\n  } catch {\n    return [];\n  }\n}\n",
  "src/kit/Reserve.tsx": "// Smithable app kit: the reservation block. On a record with places (a session), a signed-in\n// person books one in a step, sees that they are booked, and cancels; visitors are asked to\n// sign in. The places are checked again where the booking is written: two people cannot both\n// take the last one. To change it, copy this file into src/custom/components/ and edit the copy.\nimport { CircleAlert, CircleCheck } from \"lucide-react\";\nimport { useEffect, useState } from \"react\";\nimport { Button, buttonVariants } from \"#/components/ui/button\";\n\nexport interface Places {\n  left: number;\n  max: number;\n  /** The viewer's own booking, if they have one. */\n  mine?: number;\n  canBook: boolean;\n  signedIn: boolean;\n}\n\nexport function Reserve({\n  id,\n  load,\n  book,\n  cancel,\n  bookLabel = \"Book a place\",\n  cancelLabel = \"Cancel booking\",\n  fullLabel = \"Full\",\n  bookedLabel = \"You're booked\",\n}: {\n  /** The record whose places these are (the session). */\n  id: number;\n  load: (options: { data: number }) => Promise<Places | null>;\n  book: (options: { data: number }) => Promise<unknown>;\n  /** Deletes the viewer's booking. */\n  cancel: (options: { data: number }) => Promise<unknown>;\n  bookLabel?: string;\n  cancelLabel?: string;\n  fullLabel?: string;\n  bookedLabel?: string;\n}) {\n  const [places, setPlaces] = useState<Places | null>();\n  const [busy, setBusy] = useState(false);\n  const [asking, setAsking] = useState(false);\n  const [failure, setFailure] = useState<string>();\n  useEffect(() => {\n    load({ data: id }).then(setPlaces, () => setPlaces(null));\n  }, [id, load]);\n  if (places === undefined)\n    return <p className=\"text-sm text-muted-foreground\">Checking places…</p>;\n  if (places === null) return null;\n\n  const run = async (action: () => Promise<unknown>) => {\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      await action();\n    } catch (error) {\n      const message = error instanceof Error ? error.message : \"\";\n      setFailure(\n        message === \"full\"\n          ? \"Sorry, the last place was just taken.\"\n          : message.startsWith(\"Too many \")\n            ? message\n            : \"Something went wrong. Please try again.\",\n      );\n    } finally {\n      setAsking(false);\n      setPlaces(await load({ data: id }).catch(() => null));\n      setBusy(false);\n    }\n  };\n  // Back to this page after signing in.\n  const here =\n    typeof window === \"undefined\" ? \"/\" : window.location.pathname + window.location.search;\n  const full = places.left === 0;\n\n  return (\n    <div data-kit=\"reserve\" className=\"space-y-3\">\n      <p className=\"font-semibold tabular-nums\">\n        {full\n          ? fullLabel\n          : `${places.left} of ${places.max} ${places.max === 1 ? \"place\" : \"places\"} left`}\n      </p>\n      {places.mine !== undefined ? (\n        <div className=\"space-y-3\">\n          <p className=\"flex items-center gap-2 text-success\">\n            <CircleCheck aria-hidden className=\"size-5 shrink-0\" />\n            {bookedLabel}\n          </p>\n          {asking ? (\n            <div className=\"flex flex-wrap items-center gap-2\">\n              <span>Cancel your booking?</span>\n              <Button\n                type=\"button\"\n                variant=\"destructive\"\n                disabled={busy}\n                onClick={() => run(() => cancel({ data: places.mine as number }))}\n              >\n                Yes, cancel it\n              </Button>\n              <Button\n                type=\"button\"\n                variant=\"outline\"\n                disabled={busy}\n                onClick={() => setAsking(false)}\n              >\n                Keep it\n              </Button>\n            </div>\n          ) : (\n            <Button type=\"button\" variant=\"outline\" onClick={() => setAsking(true)}>\n              {cancelLabel}\n            </Button>\n          )}\n        </div>\n      ) : !places.signedIn ? (\n        <a\n          href={`/sign-in?redirect=${encodeURIComponent(here)}`}\n          className={buttonVariants({ variant: \"default\" })}\n        >\n          Sign in to book\n        </a>\n      ) : places.canBook && !full ? (\n        <Button type=\"button\" disabled={busy} onClick={() => run(() => book({ data: id }))}>\n          {busy ? \"Booking…\" : bookLabel}\n        </Button>\n      ) : null}\n      {failure && (\n        <p role=\"alert\" className=\"flex items-center gap-2 text-sm text-destructive\">\n          <CircleAlert aria-hidden className=\"size-4 shrink-0\" />\n          {failure}\n        </p>\n      )}\n    </div>\n  );\n}\n",
  "src/kit/SearchBox.tsx": "// Smithable app kit: a search box that reports its text shortly after typing stops.\nimport { Search } from \"lucide-react\";\nimport { useEffect, useState } from \"react\";\nimport { Input } from \"#/components/ui/input\";\n\nexport function SearchBox({\n  value,\n  placeholder,\n  onSearch,\n}: {\n  value: string;\n  placeholder: string;\n  onSearch: (text: string) => void;\n}) {\n  const [text, setText] = useState(value);\n  useEffect(() => {\n    if (text === value) return;\n    const timer = setTimeout(() => onSearch(text.trim()), 250);\n    return () => clearTimeout(timer);\n  }, [text, value, onSearch]);\n  return (\n    <div data-kit=\"search-box\" className=\"relative mb-6 max-w-md\">\n      <Input\n        type=\"search\"\n        aria-label={placeholder}\n        placeholder={placeholder}\n        value={text}\n        onChange={(e) => setText(e.target.value)}\n        className=\"pr-10\"\n      />\n      <Search\n        aria-hidden\n        className=\"pointer-events-none absolute top-1/2 right-3 size-5 -translate-y-1/2 text-muted-foreground\"\n      />\n    </div>\n  );\n}\n",
  "src/kit/SignIn.tsx": "// Smithable app kit: the sign-in card, with a button per sign-in provider.\n// In development it also offers signing in as any role, without contacting a provider.\nimport { useState } from \"react\";\nimport { Button } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\n\nconst PROVIDER_LABELS: Record<string, string> = { google: \"Google\", facebook: \"Facebook\" };\n\nexport function SignIn({\n  appName,\n  providers,\n  missing,\n  invitation,\n  devRoles,\n  demo,\n  onProvider,\n  onDevRole,\n}: {\n  appName: string;\n  /** Providers that are set up, in button order. */\n  providers: string[];\n  /** Providers in the spec whose keys are not configured yet. */\n  missing: string[];\n  /** Whom the invitation link that opened the page is for; the address must sign in itself. */\n  invitation?: { email: string; role: string } | null;\n  /** Roles to sign in as; given in development, and in a demo. */\n  devRoles?: string[];\n  /** A demo: the role buttons are the way in, not a development aid. */\n  demo?: boolean;\n  onProvider: (provider: string) => Promise<unknown>;\n  onDevRole?: (role: string) => Promise<unknown>;\n}) {\n  const [failure, setFailure] = useState<string>();\n  const [busy, setBusy] = useState(false);\n  async function run(action: () => Promise<unknown>) {\n    setBusy(true);\n    setFailure(undefined);\n    try {\n      await action();\n    } catch (error) {\n      setFailure(error instanceof Error ? error.message : \"Could not sign in. Please try again.\");\n      setBusy(false);\n    }\n  }\n  return (\n    <Card data-kit=\"sign-in\" className=\"mx-auto mt-10 max-w-sm space-y-5 p-card\">\n      <h1 className=\"text-2xl font-bold\">Sign in to {appName}</h1>\n      {invitation && (\n        <p className=\"rounded-md bg-accent p-3 text-sm\">\n          You were invited to {appName} as {invitation.role}. Sign in with{\" \"}\n          <strong>{invitation.email}</strong>.\n        </p>\n      )}\n      {providers.map((provider) => (\n        <Button\n          key={provider}\n          className=\"w-full\"\n          disabled={busy}\n          onClick={() => run(() => onProvider(provider))}\n        >\n          Continue with {PROVIDER_LABELS[provider] ?? provider}\n        </Button>\n      ))}\n      {/* Setup notes are for the developer; visitors only learn that sign-in is unavailable. */}\n      {devRoles && missing.length > 0 && (\n        <p className=\"text-xs text-muted-foreground\">\n          Sign-in with {missing.map((p) => PROVIDER_LABELS[p] ?? p).join(\" and \")} is not set up\n          yet: its keys are missing from the environment. See the README.\n        </p>\n      )}\n      {!devRoles && providers.length === 0 && (\n        <p className=\"text-muted-foreground\">\n          Signing in is not available right now. Please contact whoever runs {appName}.\n        </p>\n      )}\n      {failure && (\n        <p className=\"rounded-md bg-destructive/10 p-3 text-sm text-destructive\">{failure}</p>\n      )}\n      {devRoles && onDevRole && (\n        <div className=\"space-y-2 border-t pt-4\">\n          <p className=\"text-xs font-medium uppercase tracking-wide text-muted-foreground\">\n            {demo ? \"Try it as\" : \"Development only\"}\n          </p>\n          {devRoles.map((role) => (\n            <Button\n              key={role}\n              variant=\"outline\"\n              className=\"w-full\"\n              disabled={busy}\n              onClick={() => run(() => onDevRole(role))}\n            >\n              Sign in as {role}\n            </Button>\n          ))}\n        </div>\n      )}\n    </Card>\n  );\n}\n",
  "src/kit/Users.tsx": "// Smithable app kit: who has access. Users with their role, open invitations, and what an\n// administrator does with them: invite by email address, change a role, resend or withdraw an\n// invitation, remove a user. The rules (not yourself, the last administrator stays) are checked\n// on the server; this only shows their answers. A table from tablet width, cards on a phone.\n// To customize it, copy this file into src/custom/components/ and edit the copy.\nimport { useRef, useState } from \"react\";\nimport { Badge } from \"#/components/ui/badge\";\nimport { Button } from \"#/components/ui/button\";\nimport { Card } from \"#/components/ui/card\";\nimport { Input, Label, NativeSelect } from \"#/components/ui/input\";\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"#/components/ui/table\";\n\nexport interface RoleOption {\n  value: string;\n  label: string;\n  description?: string;\n}\n\nexport interface UserRow {\n  id: string;\n  name: string;\n  email: string;\n  role: string;\n}\n\nexport interface InvitationRow {\n  id: string;\n  email: string;\n  role: string;\n  expiresAt: Date | string;\n  /** The link the invitation mail carries; shown so it can be sent by hand too. */\n  link: string;\n}\n\ninterface UsersProps {\n  /** The signed-in user: their own role and account are not theirs to change here. */\n  viewerId?: string;\n  roles: RoleOption[];\n  users: UserRow[];\n  invitations: InvitationRow[];\n  onInvite: (email: string, role: string) => Promise<unknown>;\n  onSetRole: (userId: string, role: string) => Promise<unknown>;\n  onRemove: (userId: string) => Promise<unknown>;\n  onResend: (invitationId: string) => Promise<unknown>;\n  onWithdraw: (invitationId: string) => Promise<unknown>;\n}\n\nconst date = (value: Date | string) =>\n  new Intl.DateTimeFormat(undefined, { dateStyle: \"medium\" }).format(new Date(value));\n\nexport function Users({\n  viewerId,\n  roles,\n  users,\n  invitations,\n  onInvite,\n  onSetRole,\n  onRemove,\n  onResend,\n  onWithdraw,\n}: UsersProps) {\n  const [email, setEmail] = useState(\"\");\n  const [role, setRole] = useState(roles.find((r) => r.value !== \"admin\")?.value ?? \"admin\");\n  const [busy, setBusy] = useState(false);\n  const [failure, setFailure] = useState<string>();\n  const [notice, setNotice] = useState<string>();\n  const [removing, setRemoving] = useState<UserRow>();\n  const confirmRemove = useRef<HTMLDialogElement>(null);\n  const label = (value: string) => roles.find((r) => r.value === value)?.label ?? value;\n  const chosen = roles.find((r) => r.value === role);\n\n  async function run(action: () => Promise<unknown>, done?: string) {\n    setBusy(true);\n    setFailure(undefined);\n    setNotice(undefined);\n    try {\n      await action();\n      if (done) setNotice(done);\n    } catch (error) {\n      setFailure(\n        error instanceof Error ? error.message : \"Something went wrong. Please try again.\",\n      );\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function invite(event: React.FormEvent) {\n    event.preventDefault();\n    const address = email.trim();\n    if (!address) return;\n    await run(async () => {\n      await onInvite(address, role);\n      setEmail(\"\");\n    }, `Invitation sent to ${address}.`);\n  }\n\n  async function copy(link: string) {\n    try {\n      await navigator.clipboard.writeText(link);\n      setNotice(\"Invitation link copied.\");\n    } catch {\n      setNotice(link);\n    }\n  }\n\n  // The same controls in the table and in the phone cards.\n  const roleControl = (u: UserRow) =>\n    u.id === viewerId ? (\n      <span>{label(u.role)}</span>\n    ) : (\n      <NativeSelect\n        aria-label={`Role of ${u.name}`}\n        className=\"h-9 w-auto\"\n        value={u.role}\n        disabled={busy}\n        onChange={(e) => run(() => onSetRole(u.id, e.target.value))}\n      >\n        {roles.map((r) => (\n          <option key={r.value} value={r.value}>\n            {r.label}\n          </option>\n        ))}\n      </NativeSelect>\n    );\n  const removeButton = (u: UserRow) =>\n    u.id !== viewerId && (\n      <Button\n        type=\"button\"\n        variant=\"outline\"\n        size=\"sm\"\n        className=\"border-destructive text-destructive\"\n        disabled={busy}\n        onClick={() => {\n          setRemoving(u);\n          confirmRemove.current?.showModal();\n        }}\n      >\n        Remove\n      </Button>\n    );\n  const expired = (i: InvitationRow) => new Date(i.expiresAt).getTime() < Date.now();\n  const invitationStatus = (i: InvitationRow) =>\n    expired(i) ? (\n      <Badge variant=\"danger\">Invitation expired</Badge>\n    ) : (\n      <Badge variant=\"warning\">Invited, valid until {date(i.expiresAt)}</Badge>\n    );\n  const invitationActions = (i: InvitationRow) => (\n    <div className=\"flex flex-wrap gap-2 md:justify-end\">\n      <Button\n        type=\"button\"\n        variant=\"outline\"\n        size=\"sm\"\n        disabled={busy || expired(i)}\n        onClick={() => copy(i.link)}\n      >\n        Copy link\n      </Button>\n      <Button\n        type=\"button\"\n        variant=\"outline\"\n        size=\"sm\"\n        disabled={busy}\n        onClick={() => run(() => onResend(i.id), `Invitation sent again to ${i.email}.`)}\n      >\n        Resend\n      </Button>\n      <Button\n        type=\"button\"\n        variant=\"outline\"\n        size=\"sm\"\n        disabled={busy}\n        onClick={() => run(() => onWithdraw(i.id))}\n      >\n        Withdraw\n      </Button>\n    </div>\n  );\n  const you = (u: UserRow) =>\n    u.id === viewerId && <span className=\"text-muted-foreground\"> (you)</span>;\n\n  return (\n    <div data-kit=\"users\" className=\"space-y-6\">\n      <Card className=\"p-card\">\n        <form onSubmit={invite} className=\"flex flex-col gap-4 sm:flex-row sm:items-end\">\n          <div className=\"flex-1 space-y-1.5\">\n            <Label htmlFor=\"invite-email\">Email address</Label>\n            <Input\n              id=\"invite-email\"\n              type=\"email\"\n              required\n              value={email}\n              placeholder=\"name@example.com\"\n              onChange={(e) => setEmail(e.target.value)}\n              disabled={busy}\n            />\n          </div>\n          <div className=\"space-y-1.5 sm:w-56\">\n            <Label htmlFor=\"invite-role\">Role</Label>\n            <NativeSelect\n              id=\"invite-role\"\n              value={role}\n              onChange={(e) => setRole(e.target.value)}\n              disabled={busy}\n            >\n              {roles.map((r) => (\n                <option key={r.value} value={r.value}>\n                  {r.label}\n                </option>\n              ))}\n            </NativeSelect>\n          </div>\n          <Button type=\"submit\" disabled={busy}>\n            Send invitation\n          </Button>\n        </form>\n        {chosen?.description && (\n          <p className=\"mt-2 text-sm text-muted-foreground\">{chosen.description}</p>\n        )}\n      </Card>\n      {failure && (\n        <p role=\"alert\" className=\"rounded-md bg-destructive/10 p-3 text-sm text-destructive\">\n          {failure}\n        </p>\n      )}\n      {notice && (\n        <p role=\"status\" className=\"break-all rounded-md bg-accent p-3 text-sm\">\n          {notice}\n        </p>\n      )}\n      {users.length + invitations.length === 0 && (\n        <Card className=\"px-6 py-16 text-center text-muted-foreground\">\n          Nobody yet. Invite the first person above.\n        </Card>\n      )}\n      <ul className=\"space-y-3 md:hidden\">\n        {users.map((u) => (\n          <li key={u.id}>\n            <Card className=\"space-y-3 p-5\">\n              <div className=\"flex items-start justify-between gap-3\">\n                <div className=\"min-w-0\">\n                  <p className=\"font-semibold\">\n                    {u.name}\n                    {you(u)}\n                  </p>\n                  <p className=\"truncate text-sm text-muted-foreground\">{u.email}</p>\n                </div>\n                <Badge variant=\"success\">Active</Badge>\n              </div>\n              <div className=\"flex flex-wrap items-center justify-between gap-2\">\n                {roleControl(u)}\n                {removeButton(u)}\n              </div>\n            </Card>\n          </li>\n        ))}\n        {invitations.map((i) => (\n          <li key={i.id}>\n            <Card className=\"space-y-3 p-5\">\n              <div className=\"min-w-0\">\n                <p className=\"truncate font-semibold\">{i.email}</p>\n                <p className=\"text-sm text-muted-foreground\">{label(i.role)}</p>\n              </div>\n              {invitationStatus(i)}\n              {invitationActions(i)}\n            </Card>\n          </li>\n        ))}\n      </ul>\n      {users.length + invitations.length > 0 && (\n        <Card className=\"hidden overflow-hidden md:block\">\n          <Table>\n            <TableHeader>\n              <TableRow>\n                <TableHead>Name</TableHead>\n                <TableHead>Email</TableHead>\n                <TableHead>Role</TableHead>\n                <TableHead>Status</TableHead>\n                <TableHead className=\"text-right\">Actions</TableHead>\n              </TableRow>\n            </TableHeader>\n            <TableBody>\n              {users.map((u) => (\n                <TableRow key={u.id}>\n                  <TableCell className=\"font-medium\">\n                    {u.name}\n                    {you(u)}\n                  </TableCell>\n                  <TableCell>{u.email}</TableCell>\n                  <TableCell>{roleControl(u)}</TableCell>\n                  <TableCell>\n                    <Badge variant=\"success\">Active</Badge>\n                  </TableCell>\n                  <TableCell className=\"text-right\">{removeButton(u)}</TableCell>\n                </TableRow>\n              ))}\n              {invitations.map((i) => (\n                <TableRow key={i.id}>\n                  <TableCell className=\"text-muted-foreground\">—</TableCell>\n                  <TableCell>{i.email}</TableCell>\n                  <TableCell>{label(i.role)}</TableCell>\n                  <TableCell>{invitationStatus(i)}</TableCell>\n                  <TableCell className=\"text-right\">{invitationActions(i)}</TableCell>\n                </TableRow>\n              ))}\n            </TableBody>\n          </Table>\n        </Card>\n      )}\n      {/* Opening it focuses Cancel, the first button; Escape closes it. */}\n      <dialog\n        ref={confirmRemove}\n        aria-labelledby=\"remove-title\"\n        className=\"m-auto w-[calc(100%-2.5rem)] max-w-md rounded-lg border bg-card p-card text-card-foreground backdrop:bg-black/50\"\n      >\n        <h2 id=\"remove-title\" className=\"text-lg font-semibold\">\n          Remove {removing?.name ?? \"this user\"}?\n        </h2>\n        <p className=\"mt-2 text-muted-foreground\">\n          They can no longer sign in. What they created stays, without an owner. They can be invited\n          again.\n        </p>\n        <div className=\"mt-6 flex flex-wrap justify-end gap-3\">\n          <Button type=\"button\" variant=\"outline\" onClick={() => confirmRemove.current?.close()}>\n            Cancel\n          </Button>\n          <Button\n            type=\"button\"\n            variant=\"destructive\"\n            onClick={() => {\n              confirmRemove.current?.close();\n              if (removing) run(() => onRemove(removing.id));\n            }}\n          >\n            Remove user\n          </Button>\n        </div>\n      </dialog>\n    </div>\n  );\n}\n",
  "src/kit/access.ts": "// Smithable app kit: who may read, create, change and delete records, and open pages.\n// Every generated data function checks access here, so the rules live in one place.\nimport { redirect } from \"@tanstack/react-router\";\n\n/** The signed-in user, or null for a visitor who has not signed in. */\nexport interface Viewer {\n  id: string;\n  name: string;\n  email: string;\n  role: string;\n}\n\n/** Who may do something: anyone (public), users with one of `roles`, and a record's owner. */\nexport interface Rule {\n  public: boolean;\n  roles: readonly string[];\n  owner: boolean;\n  /** Reading only: the records anyone may read, when not all (e.g. { status: \"published\" }). */\n  where?: Readonly<Record<string, string | boolean | readonly string[]>>;\n}\n\nexport interface ModelAccess {\n  read: Rule;\n  create: Rule;\n  write: Rule;\n  delete: Rule;\n}\n\nexport class AccessDenied extends Error {\n  constructor(signedIn: boolean) {\n    super(signedIn ? \"You are not allowed to do this.\" : \"Please sign in first.\");\n  }\n}\n\n/** A change the database refused, as a code the form turns into words: \"taken:<column>\" or \"in-use\". */\nexport class Conflict extends Error {}\n\n/**\n * A database error as people may see it: a unique value already taken, or a record still in\n * use. Anything else stays in the server's log; the page gets a plain apology.\n */\nexport function refusal(error: unknown): Error {\n  const message = error instanceof Error ? error.message : \"\";\n  // With several columns (unique per owner), the last one is the field.\n  const column = /UNIQUE constraint failed: (?:\\w+\\.\\w+, )*\\w+\\.(\\w+)/.exec(message)?.[1];\n  if (column) return new Conflict(`taken:${column}`);\n  if (message.includes(\"FOREIGN KEY constraint failed\")) return new Conflict(\"in-use\");\n  console.error(error);\n  return new Error(\"Something went wrong. Please try again.\");\n}\n\n/** Whether the viewer may do something; `ownerId` is the owner of the record involved, if any. */\nexport function allows(rule: Rule, viewer: Viewer | null, ownerId?: string | null): boolean {\n  if (rule.public) return true;\n  if (!viewer) return false;\n  if (rule.roles.includes(viewer.role)) return true;\n  return rule.owner && ownerId != null && ownerId === viewer.id;\n}\n\nexport function check(rule: Rule, viewer: Viewer | null, ownerId?: string | null): void {\n  if (!allows(rule, viewer, ownerId)) throw new AccessDenied(viewer !== null);\n}\n\n/** Which records the viewer may read: all of them, only their own, or none. */\n/**\n * Which records the viewer may read: all of them, their own (and the public ones where the\n * rule limits those), only the public ones, or none.\n */\nexport function readScope(rule: Rule, viewer: Viewer | null): \"all\" | \"own\" | \"public\" | \"none\" {\n  if (viewer && rule.roles.includes(viewer.role)) return \"all\";\n  if (rule.public && !rule.where) return \"all\";\n  if (viewer && rule.owner) return \"own\";\n  return rule.public ? \"public\" : \"none\";\n}\n\n/** For a page's beforeLoad: sends visitors to sign in, and refuses users without the role. */\nexport function guardPage(rule: Rule, viewer: Viewer | null, href: string): void {\n  if (allows(rule, viewer)) return;\n  if (!viewer) throw redirect({ href: `/sign-in?redirect=${encodeURIComponent(href)}` });\n  throw new AccessDenied(true);\n}\n",
  "src/kit/aggregate.ts": "// Smithable app kit: the numbers a dashboard shows, worked out from records the viewer may read.\n\n/** The sum of a number over records; empty values count as nothing. */\nexport function sum<R>(rows: R[], value: (row: R) => unknown): number {\n  return rows.reduce((total, row) => total + (Number(value(row)) || 0), 0);\n}\n\n/** The average of a number over records that have one, or null when none do. */\nexport function average<R>(rows: R[], value: (row: R) => unknown): number | null {\n  const numbers = rows.map(value).filter((v) => v !== null && v !== undefined) as number[];\n  return numbers.length ? sum(numbers, Number) / numbers.length : null;\n}\n\n/**\n * One total per month, for the last `months` months up to the latest record's month, with\n * empty months as 0. Months are \"2026-09\", from a date or a date and time (in UTC).\n */\nexport function byMonth<R>(\n  rows: R[],\n  date: (row: R) => unknown,\n  value: (row: R) => number,\n  months = 6,\n): { month: string; value: number }[] {\n  const totals = new Map<string, number>();\n  for (const row of rows) {\n    const d = date(row);\n    if (d === null || d === undefined) continue;\n    const month = (d instanceof Date ? d.toISOString() : String(d)).slice(0, 7);\n    totals.set(month, (totals.get(month) ?? 0) + value(row));\n  }\n  const last = [...totals.keys()].sort().at(-1);\n  if (!last) return [];\n  const [year, month] = last.split(\"-\").map(Number) as [number, number];\n  return Array.from({ length: months }, (_, i) => {\n    const d = new Date(Date.UTC(year, month - months + i, 1));\n    const key = d.toISOString().slice(0, 7);\n    return { month: key, value: totals.get(key) ?? 0 };\n  });\n}\n\n/** The newest records first: the highest ids. */\nexport function latest<R extends { id: number }>(rows: R[], limit: number): R[] {\n  return [...rows].sort((a, b) => b.id - a.id).slice(0, limit);\n}\n",
  "src/kit/filter.ts": "// Smithable app kit: the condition for records in a list filter's range (src/kit/Filters.tsx).\nimport { and, asc, type Column, desc, gte, lte, type SQL } from \"drizzle-orm\";\n\n/**\n * Records whose value lies in a filter's range, \"from..to\" with either side left out: numbers\n * (amounts in the currency's units, stored in cents with `scale` 100), or dates as written\n * (\"2026-10-05\"; a date and time column compares from the start of \"from\" to the end of \"to\").\n */\nexport function inRange(\n  column: Column,\n  text: string,\n  kind: \"number\" | \"date\" | \"instant\",\n  scale = 1,\n): SQL | undefined {\n  const [from = \"\", to = \"\"] = text.split(\"..\").map((v) => v.trim());\n  const bound = (value: string, end: boolean) => {\n    if (!value) return undefined;\n    if (kind === \"number\") {\n      const n = Number(value.replace(\",\", \".\"));\n      return Number.isFinite(n) ? Math.round(n * scale) : undefined;\n    }\n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(value)) return undefined;\n    if (kind === \"date\") return value;\n    return new Date(`${value}T${end ? \"23:59:59.999\" : \"00:00:00.000\"}Z`);\n  };\n  const low = bound(from, false);\n  const high = bound(to, true);\n  return and(\n    low === undefined ? undefined : gte(column, low),\n    high === undefined ? undefined : lte(column, high),\n  );\n}\n\n/**\n * The list's order from the address, \"price\" from low and \"-price\" from high, among the columns\n * the page lets its viewer sort by; anything else leaves the newest first.\n */\nexport function orderOf(\n  columns: Record<string, Column>,\n  sort: string | undefined,\n): SQL | undefined {\n  const column = sort ? columns[sort.replace(/^-/, \"\")] : undefined;\n  if (!column || !sort) return undefined;\n  return sort.startsWith(\"-\") ? desc(column) : asc(column);\n}\n",
  "src/kit/format.ts": "// Smithable app kit: converts stored values to display text and to form input text, and back.\nimport type { AppUi, FieldUi, RecordFieldUi } from \"./model\";\nimport { instantOf, wallTime } from \"./zoned\";\n\n/** The value to show for a field of a record: for a reference, the related record's title. */\nexport function displayValue<R>(field: RecordFieldUi<R>, row: R): unknown {\n  return field.get(row);\n}\n\n/** Text for showing a stored value in tables and headings. */\nexport function formatValue(field: FieldUi, value: unknown, app: AppUi): string {\n  if (value === null || value === undefined || value === \"\") return \"—\";\n  switch (field.kind) {\n    case \"money\":\n      return new Intl.NumberFormat(undefined, { style: \"currency\", currency: app.currency }).format(\n        Number(value) / 100,\n      );\n    case \"int\":\n    case \"decimal\":\n      return new Intl.NumberFormat().format(Number(value));\n    case \"bool\":\n      return value ? \"Yes\" : \"No\";\n    case \"picture\":\n      return typeof value === \"object\" && value && \"alt\" in value ? String(value.alt) : \"Picture\";\n    case \"pictures\": {\n      // The cover's description; no pictures reads as nothing.\n      const cover = Array.isArray(value) ? value[0] : undefined;\n      return cover ? String(cover.alt || \"Picture\") : \"—\";\n    }\n    case \"date\":\n      return new Intl.DateTimeFormat(undefined, { dateStyle: \"medium\", timeZone: \"UTC\" }).format(\n        new Date(`${String(value)}T00:00:00Z`),\n      );\n    case \"datetime\":\n      return new Intl.DateTimeFormat(undefined, {\n        dateStyle: \"medium\",\n        timeStyle: \"short\",\n        timeZone: app.timeZone,\n      }).format(value instanceof Date ? value : new Date(String(value)));\n    case \"choice\":\n      return field.choices?.find((c) => c.value === value)?.label ?? String(value);\n    case \"relation\":\n    case \"user\":\n      return String(value);\n    default:\n      return String(value);\n  }\n}\n\n/** The form input's text for a stored value, date-times in `timeZone`. Booleans stay booleans. */\nexport function toInput(field: FieldUi, value: unknown, timeZone?: string): string | boolean {\n  if (field.kind === \"bool\") return Boolean(value);\n  if (value === null || value === undefined) return \"\";\n  if (field.kind === \"money\") return (Number(value) / 100).toFixed(2);\n  if (field.kind === \"datetime\")\n    return wallTime(value instanceof Date ? value : new Date(String(value)), timeZone);\n  if (field.kind === \"picture\" || field.kind === \"pictures\")\n    return typeof value === \"object\" ? JSON.stringify(value) : \"\";\n  return String(value);\n}\n\n/** The stored value for a form input's text, date-times read in `timeZone`. Empty text becomes null. */\nexport function fromInput(field: FieldUi, input: string | boolean, timeZone?: string): unknown {\n  if (typeof input === \"boolean\") return input;\n  const text = input.trim();\n  if (text === \"\") return null;\n  switch (field.kind) {\n    case \"int\":\n    case \"decimal\":\n      return Number(text.replace(\",\", \".\"));\n    case \"money\":\n      return Math.round(Number(text.replace(\",\", \".\")) * 100);\n    case \"datetime\":\n      return instantOf(text, timeZone);\n    case \"relation\":\n      return Number(text);\n    case \"picture\":\n    case \"pictures\":\n      return JSON.parse(text);\n    default:\n      return text;\n  }\n}\n",
  "src/kit/formula.ts": "// Smithable app kit: the spreadsheet functions used by the formulas in src/generated/*.formulas.ts.\n// Blank values behave like blank spreadsheet cells: 0 in arithmetic, \"\" in text.\n\ntype Value = unknown;\n\n/** A number, or 0 for a blank value. */\nfunction n(value: Value): number {\n  return typeof value === \"number\" ? value : value == null || value === \"\" ? 0 : Number(value);\n}\n\n/** Text, or \"\" for a blank value. */\nfunction t(value: Value): string {\n  if (value == null) return \"\";\n  if (value instanceof Date) return value.toISOString();\n  return String(value);\n}\n\n/** A date as YYYY-MM-DD, or \"\" for a blank value. */\nfunction d(value: Value): string {\n  if (value instanceof Date) return value.toISOString().slice(0, 10);\n  return value == null ? \"\" : String(value).slice(0, 10);\n}\n\n/** Comparable form of a value: numbers, dates and text compare like in a spreadsheet. */\nfunction key(value: Value): number | string {\n  if (value instanceof Date) return value.getTime();\n  if (typeof value === \"number\" || typeof value === \"boolean\") return Number(value);\n  return t(value);\n}\n\nfunction compare(op: \"=\" | \"<>\" | \"<\" | \">\" | \"<=\" | \">=\", a: Value, b: Value): boolean {\n  const x = key(a);\n  const y = key(b);\n  switch (op) {\n    case \"=\":\n      return x === y;\n    case \"<>\":\n      return x !== y;\n    case \"<\":\n      return x < y;\n    case \">\":\n      return x > y;\n    case \"<=\":\n      return x <= y;\n    case \">=\":\n      return x >= y;\n  }\n}\n\n/**\n * Rounds half away from zero, like spreadsheets. Float noise far below the last digit is\n * removed first, so 0.5 * 19.99 (9.995) rounds to 10.00 and ROUND(1.005, 2) to 1.01.\n */\nfunction ROUND(value: number, digits = 0): number {\n  const scaled = Number((Math.abs(value) * 10 ** digits).toFixed(9));\n  return (Math.sign(value) * Math.round(scaled)) / 10 ** digits;\n}\n\nfunction TODAY(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\n/** The current date and time, e.g. for \"placed at\" when a record is created. */\nfunction NOW(): string {\n  return new Date().toISOString();\n}\n\nfunction DATEADD(date: string, amount: number, unit: \"day\" | \"month\" | \"year\"): string {\n  if (date === \"\") return \"\";\n  const value = new Date(`${date}T00:00:00Z`);\n  if (unit === \"day\") value.setUTCDate(value.getUTCDate() + amount);\n  else {\n    const day = value.getUTCDate();\n    value.setUTCDate(1);\n    if (unit === \"month\") value.setUTCMonth(value.getUTCMonth() + amount);\n    else value.setUTCFullYear(value.getUTCFullYear() + amount);\n    const last = new Date(\n      Date.UTC(value.getUTCFullYear(), value.getUTCMonth() + 1, 0),\n    ).getUTCDate();\n    value.setUTCDate(Math.min(day, last)); // 31 January + 1 month is 28 or 29 February\n  }\n  return value.toISOString().slice(0, 10);\n}\n\n/**\n * The payment per period that repays `amount` over `periods` at `rate` per period (the\n * spreadsheet PMT, as a positive number); with no interest, the amount split evenly.\n */\nfunction PMT(rate: number, periods: number, amount: number): number {\n  if (!(periods > 0)) return 0;\n  if (rate === 0) return amount / periods;\n  const growth = (1 + rate) ** periods;\n  return (amount * rate * growth) / (growth - 1);\n}\n\n/** Days from `start` to `end`. */\nfunction DAYS(end: string, start: string): number {\n  if (end === \"\" || start === \"\") return 0;\n  return Math.round(\n    (Date.parse(`${end}T00:00:00Z`) - Date.parse(`${start}T00:00:00Z`)) / 86_400_000,\n  );\n}\n\n/** The related records a formula aggregates over (a list relation), or none. */\nfunction list(value: Value): Record<string, unknown>[] {\n  return Array.isArray(value) ? value : [];\n}\n\nconst SUM = (values: number[]) => values.reduce((a, b) => a + b, 0);\nconst AVG = (values: number[]) => (values.length ? SUM(values) / values.length : 0);\nconst MIN = (values: number[]) => (values.length ? Math.min(...values) : 0);\nconst MAX = (values: number[]) => (values.length ? Math.max(...values) : 0);\n\n/** Money is stored in cents; formulas work in whole currency units. */\nconst fromCents = (value: Value) => n(value) / 100;\nconst toCents = (value: number) => Math.round(ROUND(value, 2) * 100);\n\nexport const F = {\n  n,\n  t,\n  d,\n  compare,\n  ROUND,\n  PMT,\n  TODAY,\n  NOW,\n  DATEADD,\n  DAYS,\n  list,\n  SUM,\n  AVG,\n  MIN,\n  MAX,\n  fromCents,\n  toCents,\n};\n",
  "src/kit/limit.ts": "// Smithable app kit: how often one person, or one address, may write. Sign-in and its callbacks\n// are limited by Better Auth itself (3 attempts per 10 seconds in production); this covers the\n// app's own server functions: creating, changing and deleting records, booking, inviting.\n// Counts live in memory: the app runs as one process, so that is the whole picture.\n\n/** Refused because of how often, not because of who: the words are shown as they are. */\nexport class TooMany extends Error {\n  constructor(what: string) {\n    super(`Too many ${what} in a short time. Wait a minute and try again.`);\n  }\n}\n\n/** How many of each within how many seconds. */\nexport const LIMITS = {\n  /** Writes by a signed-in person. */\n  writes: { max: 60, seconds: 60 },\n  /** Writes by a visitor (a contact form), per address. */\n  visitorWrites: { max: 10, seconds: 60 },\n  /** Invitations sent by one administrator. */\n  invitations: { max: 20, seconds: 3600 },\n};\n\nconst counts = new Map<string, { n: number; until: number }>();\n\n/** One more `what` under `key`, or TooMany when `max` happened within `seconds`. */\nexport function count(\n  key: string,\n  { max, seconds }: { max: number; seconds: number },\n  what: string,\n  now = Date.now(),\n): void {\n  if (counts.size > 10_000) for (const [k, v] of counts) if (v.until <= now) counts.delete(k);\n  const entry = counts.get(key);\n  if (!entry || entry.until <= now) {\n    counts.set(key, { n: 1, until: now + seconds * 1000 });\n    return;\n  }\n  if (entry.n >= max) throw new TooMany(what);\n  entry.n += 1;\n}\n\n/**\n * The address a request came from, as the last proxy saw it (the rightmost forwarded address,\n * which a client behind one proxy cannot choose); \"unknown\" when nothing says.\n */\nexport function address(headers: Headers): string {\n  const forwarded = headers.get(\"x-forwarded-for\")?.split(\",\").at(-1)?.trim();\n  return forwarded || headers.get(\"x-real-ip\") || \"unknown\";\n}\n\n/** Counts a write by the viewer, or by the visitor's address (from the request's headers). */\nexport function writeAllowed(viewer: { id: string } | null, headers: Headers): void {\n  if (viewer) count(`write:${viewer.id}`, LIMITS.writes, \"changes\");\n  else count(`write:${address(headers)}`, LIMITS.visitorWrites, \"submissions\");\n}\n\n/** Counts an invitation sent by the viewer. */\nexport function inviteAllowed(viewer: { id: string } | null): void {\n  if (viewer) count(`invite:${viewer.id}`, LIMITS.invitations, \"invitations\");\n}\n",
  "src/kit/mail.ts": "// Smithable app kit: sending mail from hooks and custom code (see src/custom/hooks.ts).\n// The settings come from the environment, never from the code: SMTP_URL, like\n// smtp://user:password@smtp.example.eu:587 (smtps:// for TLS from the first byte), or SMTP_HOST,\n// SMTP_PORT, SMTP_USER and SMTP_PASSWORD; and MAIL_FROM, the sender, like\n// \"Stillwater Yoga <hello@stillwater.ax>\". Without SMTP settings nothing leaves the machine: each\n// mail is written to DATA_DIR/mail/outbox as a .eml file, which is how development and the tests\n// see what would have been sent. In production that also happens, with a warning, so a hook\n// never fails a request over a missing mail setting.\nimport { mkdirSync, readdirSync, readFileSync, writeFileSync } from \"node:fs\";\nimport { join } from \"node:path\";\nimport { createTransport } from \"nodemailer\";\n\nexport interface Mail {\n  to: string | string[];\n  subject: string;\n  /** The plain-text body; `html` is optional and shown by clients that render it. */\n  text: string;\n  html?: string;\n  replyTo?: string;\n}\n\n/** Where mails go without SMTP settings. */\nexport const OUTBOX = join(process.env.DATA_DIR ?? \"data\", \"mail\", \"outbox\");\n\nfunction smtp() {\n  const env = process.env;\n  if (env.SMTP_URL) return env.SMTP_URL;\n  if (env.SMTP_HOST)\n    return {\n      host: env.SMTP_HOST,\n      port: Number(env.SMTP_PORT ?? 587),\n      secure: env.SMTP_PORT === \"465\",\n      ...(env.SMTP_USER ? { auth: { user: env.SMTP_USER, pass: env.SMTP_PASSWORD ?? \"\" } } : {}),\n    };\n  return undefined;\n}\n\n/** Sends a mail, or writes it to the outbox when the app has no SMTP settings. */\nexport async function sendMail(mail: Mail): Promise<void> {\n  const message = { from: process.env.MAIL_FROM ?? \"app@localhost\", ...mail };\n  const settings = smtp();\n  if (settings) {\n    await createTransport(settings).sendMail(message);\n    return;\n  }\n  const transport = createTransport({ streamTransport: true, buffer: true, newline: \"unix\" });\n  const info = await transport.sendMail(message);\n  mkdirSync(OUTBOX, { recursive: true });\n  const stamp = new Date().toISOString().replace(/[:.]/g, \"-\");\n  const id = String(info.messageId)\n    .replace(/[^\\w.-]/g, \"\")\n    .slice(0, 40);\n  writeFileSync(join(OUTBOX, `${stamp}-${id}.eml`), info.message as Buffer);\n  if (process.env.NODE_ENV === \"production\")\n    console.warn(\n      `Mail to ${[mail.to].flat().join(\", \")} was not sent: no SMTP settings (SMTP_URL, or SMTP_HOST and the others). It is kept in ${OUTBOX}.`,\n    );\n}\n\n/** The mails in the outbox, oldest first, as tests read them: the headers and the text body. */\nexport function outbox(): { file: string; to: string; subject: string; text: string }[] {\n  let files: string[];\n  try {\n    files = readdirSync(OUTBOX)\n      .filter((f) => f.endsWith(\".eml\"))\n      .sort();\n  } catch {\n    return [];\n  }\n  return files.map((file) => {\n    const raw = readFileSync(join(OUTBOX, file), \"utf8\");\n    const at = raw.indexOf(\"\\n\\n\");\n    const headers = raw.slice(0, at);\n    const header = (name: string) =>\n      new RegExp(`^${name}: (.*)$`, \"im\").exec(headers)?.[1]?.trim() ?? \"\";\n    return { file, to: header(\"To\"), subject: header(\"Subject\"), text: raw.slice(at + 2).trim() };\n  });\n}\n",
  "src/kit/model.ts": "// Smithable app kit: describes models to the generic table and form components.\n// Each model's description is in src/generated/<model>.ts.\n\nexport type FieldKind =\n  | \"string\"\n  | \"text\"\n  /** Long text with formatting (headings, lists, links), written as Markdown. */\n  | \"markdown\"\n  | \"int\"\n  | \"decimal\"\n  | \"money\"\n  | \"bool\"\n  | \"date\"\n  | \"datetime\"\n  | \"email\"\n  | \"phone\"\n  | \"url\"\n  /** A stored picture with its description: { file, alt, width, height }. */\n  | \"picture\"\n  /** Several stored pictures, the first the cover: a list of { file, alt, width, height }. */\n  | \"pictures\"\n  | \"choice\"\n  | \"relation\"\n  /** A reference to a user who signs in. */\n  | \"user\";\n\nexport interface FieldUi {\n  name: string;\n  label: string;\n  kind: FieldKind;\n  required: boolean;\n  /** Computed by a formula: shown, never entered. */\n  computed?: boolean;\n  help?: string;\n  /** A choice's tone colors its badge by meaning; without one it is neutral. */\n  choices?: { value: string; label: string; tone?: \"success\" | \"warning\" | \"danger\" }[];\n  /** For a reference: the related record's key in a row, and the field that names it. */\n  relation?: { key: string; titleField: string };\n  default?: string | number | boolean;\n  /** Bounds for numbers (a slider or stepper needs them). */\n  min?: number;\n  max?: number;\n  /** How the field is entered, when the ux file chose one (docs/design/look.md §1.1). */\n  control?: \"slider\" | \"stepper\" | \"radio\" | \"select\" | \"combobox\" | \"textarea\" | \"switch\";\n  /** The field's own input control, when a plain one does not do (a Markdown editor). */\n  input?: (props: FieldControlProps) => React.ReactNode;\n}\n\n/** What a field's own input control gets from the form. */\nexport interface FieldControlProps {\n  id: string;\n  name: string;\n  value: string;\n  /** The record being edited, when it exists. */\n  record?: number;\n  onChange: (value: string) => void;\n  \"aria-invalid\"?: boolean;\n  \"aria-describedby\"?: string;\n}\n\nexport interface ModelUi {\n  /** The model's name in the spec, e.g. \"Customer\"; none for an action's form. */\n  model?: string;\n  label: string;\n  pluralLabel: string;\n  /** The field that names a record, e.g. \"name\". */\n  titleField: string;\n  /** The long text a card shows under the record's name, e.g. its description. */\n  descriptionField?: string;\n  /** Fields shown as table columns, in order. */\n  columns: string[];\n  fields: FieldUi[];\n  /** The form's groups with headings; fields in none follow (docs/design/look.md §1.2). */\n  sections?: { name: string; title: string; fields: string[] }[];\n  /** Short fields two abreast on wide screens. */\n  formColumns?: 1 | 2;\n  /** Adds the computed fields to a record. */\n  compute?: (row: Record<string, unknown>) => Record<string, unknown>;\n  /** Values suggested for a new record, computed from the values entered so far. */\n  defaults?: Record<string, (row: Record<string, unknown>) => unknown>;\n}\n\n/** A stored field: also how to read it from a record, typed where its model is generated. */\nexport interface RecordFieldUi<R> extends FieldUi {\n  /** Its value in a record; for a reference, the related record's title. */\n  get: (row: R) => unknown;\n}\n\n/** A stored model's description (src/generated/<model>.ts): its fields read records of type R. */\nexport interface RecordUi<R> extends ModelUi {\n  model: string;\n  fields: RecordFieldUi<R>[];\n}\n\nexport interface AppUi {\n  name: string;\n  currency: string;\n  timeZone?: string;\n}\n\nexport type Row = { id: number } & Record<string, unknown>;\n\n/** Choices for a reference field, keyed by the field's name, e.g. { customerId: [...] }. */\nexport type Options = Record<string, { value: number | string; label: string }[]>;\n\n/**\n * Marks a visible text with where its wording is kept, e.g. \"pages.customers.title\", so the\n * preview editor can change it in place. Only in development.\n */\nexport function textMarker(path: string) {\n  return import.meta.env.DEV ? { \"data-sm-text\": path } : {};\n}\n\n/**\n * Marks an element with the part of the app description it shows, for the preview editor\n * (select a field, drag a column). Only in development: production builds leave it out.\n */\nexport function editorMarker(\n  ui: ModelUi,\n  field?: FieldUi,\n  part?: \"field\" | \"column\",\n  page?: string,\n) {\n  if (!import.meta.env.DEV || !ui.model) return {};\n  const name = field ? (field.relation?.key ?? field.name) : undefined;\n  return {\n    \"data-sm-concept\": name ? `field:${ui.model}.${name}` : `model:${ui.model}`,\n    ...(part ? { \"data-sm-part\": part } : {}),\n    ...(page ? { \"data-sm-page\": page } : {}),\n  };\n}\n\n/** Rows ordered by a field (empty values last), descending when asked; a new list, the given one untouched. */\nexport function sortRows<R extends Record<string, unknown>>(\n  rows: R[],\n  field: string,\n  descending = false,\n): R[] {\n  const value = (row: R) => {\n    const v = row[field];\n    if (v instanceof Date) return v.getTime();\n    if (v && typeof v === \"object\") return String((v as { name?: unknown }).name ?? \"\");\n    return v;\n  };\n  const compare = (a: unknown, b: unknown) => {\n    if (a == null || a === \"\") return b == null || b === \"\" ? 0 : 1;\n    if (b == null || b === \"\") return -1;\n    if (typeof a === \"number\" && typeof b === \"number\") return a - b;\n    if (typeof a === \"boolean\" && typeof b === \"boolean\") return Number(a) - Number(b);\n    return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: \"base\" });\n  };\n  return [...rows].sort((a, b) => {\n    const order = compare(value(a), value(b));\n    return descending && order !== 0 && value(a) != null && value(b) != null ? -order : order;\n  });\n}\n",
  "src/kit/search.ts": "// Smithable app kit: the condition for records matching a search box's text.\nimport { type Column, getTableName, or, type SQL, sql, type Table } from \"drizzle-orm\";\n\n/** Records where any of the columns contains the text, ignoring case (SQLite's LIKE). */\nexport function contains(columns: Column[], text: string): SQL | undefined {\n  // % and _ are wildcards in LIKE; the text is matched literally.\n  const pattern = `%${text.replace(/[\\\\%_]/g, (c) => `\\\\${c}`)}%`;\n  return or(...columns.map((column) => sql`${column} like ${pattern} escape '\\\\'`));\n}\n\n/**\n * Records whose reference points at a related record containing the text, e.g. orders whose\n * customer's name matches. The subquery names its table and columns itself: a list's query\n * would otherwise read them as columns of its own table.\n */\nexport function relatedContains(\n  reference: Column,\n  table: Table,\n  columns: Column[],\n  text: string,\n): SQL {\n  const pattern = `%${text.replace(/[\\\\%_]/g, (c) => `\\\\${c}`)}%`;\n  const name = sql.identifier(getTableName(table));\n  const matches = or(\n    ...columns.map((c) => sql`${name}.${sql.identifier(c.name)} like ${pattern} escape '\\\\'`),\n  );\n  return sql`${reference} in (select ${name}.\"id\" from ${name} where ${matches})`;\n}\n",
  "src/kit/security.ts": "// Smithable app kit: the Content Security Policy of the production app's pages. The other\n// security headers come from server.mjs, on every response. In development there are none,\n// so the app can be previewed inside another page (an iframe) and the dev server works.\n\n/**\n * A page's Content Security Policy: only the app's own scripts and those carrying this page's\n * nonce run. Inline style attributes are allowed (a chart's bars are sized with them); inline\n * style elements need the nonce.\n */\nexport function pageHeaders(nonce: string | undefined): Record<string, string> {\n  if (!import.meta.env.PROD || !nonce) return {};\n  return {\n    \"Content-Security-Policy\": [\n      \"default-src 'self'\",\n      `script-src 'self' 'nonce-${nonce}'`,\n      `style-src 'self' 'nonce-${nonce}'`,\n      \"style-src-attr 'unsafe-inline'\",\n      \"img-src 'self' data:\",\n      \"font-src 'self'\",\n      \"connect-src 'self'\",\n      \"object-src 'none'\",\n      \"base-uri 'self'\",\n      \"form-action 'self'\",\n      \"frame-ancestors 'none'\",\n    ].join(\"; \"),\n  };\n}\n",
  "src/kit/uploads.ts": "// Smithable app kit: pictures on records are files under DATA_DIR/uploads (data, not code:\n// backed up with the database). Saving, reading and deleting them lives here and nowhere\n// else, so a shared file store later replaces this one module. Nothing from the browser is\n// trusted: a picture is WebP by its header, its size is read from the file, and it is at most\n// PICTURE_MAX_BYTES; the file name is made here from the content.\nimport { createHash } from \"node:crypto\";\nimport {\n  copyFileSync,\n  existsSync,\n  mkdirSync,\n  readFileSync,\n  unlinkSync,\n  writeFileSync,\n} from \"node:fs\";\nimport { join } from \"node:path\";\n\n/** What a picture field stores: the file under uploads/, its description, and its size. */\nexport interface Picture {\n  file: string;\n  alt: string;\n  width: number;\n  height: number;\n}\n\nexport const PICTURE_MAX_BYTES = 1_000_000;\n/** The longest side a browser scales a picture to before sending it. */\nexport const PICTURE_MAX_SIDE = 1600;\n\nconst uploadsDir = () => join(process.env.DATA_DIR ?? \"data\", \"uploads\");\n\n/** Refused pictures say why in words the form shows. */\nexport class BadPicture extends Error {}\n\n/** The width and height of a WebP file, from its header; undefined when it is not one. */\nexport function webpSize(bytes: Uint8Array): { width: number; height: number } | undefined {\n  const text = (at: number, n: number) => String.fromCharCode(...bytes.subarray(at, at + n));\n  if (bytes.length < 30 || text(0, 4) !== \"RIFF\" || text(8, 4) !== \"WEBP\") return undefined;\n  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);\n  const chunk = text(12, 4);\n  if (chunk === \"VP8 \")\n    return { width: view.getUint16(26, true) & 0x3fff, height: view.getUint16(28, true) & 0x3fff };\n  if (chunk === \"VP8L\") {\n    const bits = view.getUint32(21, true);\n    return { width: (bits & 0x3fff) + 1, height: ((bits >>> 14) & 0x3fff) + 1 };\n  }\n  if (chunk === \"VP8X\")\n    return {\n      width: (view.getUint16(24, true) | ((bytes[26] as number) << 16)) + 1,\n      height: (view.getUint16(27, true) | ((bytes[29] as number) << 16)) + 1,\n    };\n  return undefined;\n}\n\n/** Stores a picture sent by a browser under `model/`, and returns what the record keeps of it. */\nexport function savePicture(model: string, bytes: Uint8Array, alt: string): Picture {\n  if (bytes.length > PICTURE_MAX_BYTES)\n    throw new BadPicture(\"The picture is too large (at most 1 MB).\");\n  const size = webpSize(bytes);\n  if (!size || size.width < 1 || size.height < 1)\n    throw new BadPicture(\"Choose a picture (JPEG, PNG, WebP or HEIC).\");\n  const hash = createHash(\"sha256\").update(bytes).digest(\"hex\").slice(0, 24);\n  const file = `${model}/${hash}.webp`;\n  mkdirSync(join(uploadsDir(), model), { recursive: true });\n  const path = join(uploadsDir(), file);\n  if (!existsSync(path)) writeFileSync(path, bytes);\n  return { file, alt, ...size };\n}\n\n/** The file of a stored picture, or undefined when it is gone. */\nexport function readPicture(picture: Picture): Buffer | undefined {\n  if (!/^[a-z0-9-]+\\/[a-f0-9]{24}\\.webp$/.test(picture.file)) return undefined;\n  const path = join(uploadsDir(), picture.file);\n  return existsSync(path) ? readFileSync(path) : undefined;\n}\n\n/** Removes a picture's file, unless `stillUsed` says another record keeps it. */\nexport function deletePicture(picture: Picture | null | undefined, stillUsed: boolean): void {\n  if (!picture || stillUsed || !readPicture(picture)) return;\n  unlinkSync(join(uploadsDir(), picture.file));\n}\n\n/** The ETag of a stored picture: its file name carries the content's hash. */\nexport const pictureTag = (picture: Picture) => `\"${picture.file.slice(-29, -5)}\"`;\n\n/**\n * For `pnpm db:seed`: the n-th sample picture (public/images/samples/<n>.webp) as a record's\n * picture, copied into uploads/; null when the app has no sample pictures.\n */\nexport function samplePicture(model: string, n: number | string, alt: string): Picture | null {\n  // A starter's numbered pictures (0.webp, 1.webp, …), or a sample file's own by name.\n  const source = join(\"public\", \"images\", \"samples\", typeof n === \"number\" ? `${n}.webp` : n);\n  if (!existsSync(source)) return null;\n  const bytes = readFileSync(source);\n  const picture = savePicture(model, bytes, alt);\n  const path = join(uploadsDir(), picture.file);\n  if (!existsSync(path)) copyFileSync(source, path);\n  return picture;\n}\n",
  "src/kit/zoned.ts": "// Smithable app kit: date-times in the app's time zone (app.timeZone in generated/app.ts), whoever\n// looks at them and wherever the server runs. A studio in Mariehamn shows a 09:00 class at 09:00\n// to a visitor in Stockholm, and a form entered from anywhere stores the moment the app means.\n// Without a time zone, the browser's own is used, as the tables do.\n\n/** How far `timeZone`'s wall clock is ahead of UTC at an instant, in milliseconds. */\nfunction offsetAt(instant: number, timeZone: string): number {\n  const parts = new Intl.DateTimeFormat(\"en-US\", {\n    timeZone,\n    hourCycle: \"h23\",\n    year: \"numeric\",\n    month: \"2-digit\",\n    day: \"2-digit\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n    second: \"2-digit\",\n  }).formatToParts(new Date(instant));\n  const part = (type: string) => Number(parts.find((p) => p.type === type)?.value);\n  const wall = Date.UTC(\n    part(\"year\"),\n    part(\"month\") - 1,\n    part(\"day\"),\n    part(\"hour\"),\n    part(\"minute\"),\n    part(\"second\"),\n  );\n  return wall - Math.floor(instant / 1000) * 1000;\n}\n\n/** The wall time an instant shows in `timeZone`, as \"2026-09-30T09:00\". */\nexport function wallTime(instant: Date, timeZone?: string): string {\n  const shift = timeZone\n    ? offsetAt(instant.getTime(), timeZone)\n    : -instant.getTimezoneOffset() * 60_000;\n  return new Date(instant.getTime() + shift).toISOString().slice(0, 16);\n}\n\n/**\n * The instant a wall time (\"2026-09-30T09:00\") is in `timeZone`. Around a change to or from summer\n * time both offsets are tried: a wall time that happens twice (03:30 on the autumn night) is its\n * first occurrence, and one the change skips (03:30 in spring) is read with the offset before it.\n */\nexport function instantOf(wall: string, timeZone?: string): Date {\n  if (!timeZone) return new Date(wall);\n  const asUtc = Date.parse(`${wall.slice(0, 16)}:00Z`);\n  const before = asUtc - offsetAt(asUtc - 86_400_000, timeZone);\n  const after = asUtc - offsetAt(asUtc + 86_400_000, timeZone);\n  const shows = (t: number) => wallTime(new Date(t), timeZone) === wall.slice(0, 16);\n  const fits = [before, after].filter(shows).sort((a, b) => a - b);\n  return new Date(fits[0] ?? before);\n}\n",
  "src/lib/auth-client.ts": "// Smithable app kit: Better Auth in the browser, for signing in and out.\nimport { createAuthClient } from \"better-auth/react\";\n\nexport const authClient = createAuthClient();\n",
  "src/lib/utils.ts": "import { type ClassValue, clsx } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n",
  "src/router.tsx": "import { createRouter } from \"@tanstack/react-router\";\nimport { createIsomorphicFn } from \"@tanstack/react-start\";\nimport { Loading } from \"./kit/AppShell\";\nimport { routeTree } from \"./routeTree.gen\";\n\n/**\n * A new nonce for every server-rendered page: the Content Security Policy allows its scripts.\n * Base64, as CSP nonces usually are (a hex nonce's digit runs can look like card numbers).\n */\nconst ssrOptions = createIsomorphicFn().server(() => ({\n  nonce: btoa(String.fromCharCode(...crypto.getRandomValues(new Uint8Array(16)))),\n}));\n\nexport function getRouter() {\n  return createRouter({\n    routeTree,\n    scrollRestoration: true,\n    defaultPreload: \"intent\",\n    defaultPreloadStaleTime: 0,\n    // A page that takes longer than a moment to load shows a placeholder, not the old page.\n    defaultPendingComponent: Loading,\n    defaultPendingMs: 300,\n    defaultPendingMinMs: 300,\n    ssr: ssrOptions(),\n  });\n}\n\ndeclare module \"@tanstack/react-router\" {\n  interface Register {\n    router: ReturnType<typeof getRouter>;\n  }\n}\n",
  "src/routes/api/auth/$.ts": "// Smithable app kit: Better Auth's endpoints (sign-in callbacks, sessions, sign-out).\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { auth } from \"#/lib/auth\";\n\nexport const Route = createFileRoute(\"/api/auth/$\")({\n  server: {\n    handlers: {\n      GET: ({ request }) => auth.handler(request),\n      POST: ({ request }) => auth.handler(request),\n    },\n  },\n});\n",
  "src/routes/files/$model.$field.ts": "// Smithable app kit: a browser sends a record's picture here before saving the record (see\n// src/kit/PictureInput.tsx). Whoever may add or change the model's records may send one; the\n// file is checked and stored by src/kit/uploads.ts and the record keeps what this returns.\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { PICTURES } from \"#/generated/pictures\";\nimport { allows } from \"#/kit/access\";\nimport { writeAllowed } from \"#/kit/limit\";\nimport { BadPicture, PICTURE_MAX_BYTES, savePicture } from \"#/kit/uploads\";\nimport { currentViewer } from \"#/lib/viewer.server\";\n\nexport const Route = createFileRoute(\"/files/$model/$field\")({\n  server: {\n    handlers: {\n      POST: async ({ request, params }) => {\n        const entry = PICTURES[params.model]?.[params.field];\n        if (!entry) return new Response(\"Not found\", { status: 404 });\n        const viewer = await currentViewer();\n        const { create, write } = entry.access;\n        if (!(allows(create, viewer) || allows(write, viewer) || (viewer && write.owner)))\n          return new Response(\n            viewer ? \"You are not allowed to do this.\" : \"Please sign in first.\",\n            {\n              status: viewer ? 403 : 401,\n            },\n          );\n        try {\n          writeAllowed(viewer, request.headers);\n          const length = Number(request.headers.get(\"content-length\") ?? 0);\n          if (length > PICTURE_MAX_BYTES)\n            throw new BadPicture(\"The picture is too large (at most 1 MB).\");\n          const bytes = new Uint8Array(await request.arrayBuffer());\n          const { file, width, height } = savePicture(params.model, bytes, \"\");\n          return Response.json({ file, width, height });\n        } catch (error) {\n          const known =\n            error instanceof BadPicture ||\n            (error instanceof Error && error.message.startsWith(\"Too many \"));\n          if (!known) console.error(error);\n          return new Response(\n            known ? (error as Error).message : \"The picture could not be stored.\",\n            {\n              status: known ? 400 : 500,\n            },\n          );\n        }\n      },\n    },\n  },\n});\n",
  "src/routes/files/$model.$id.$field.$n.ts": "// Smithable app kit: one of a record's several pictures (the n-th, from 0; the first is the\n// cover), loaded through the model's data function like a single picture, so it can be seen\n// exactly when the record can.\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { PICTURES } from \"#/generated/pictures\";\nimport { type Picture, pictureTag, readPicture } from \"#/kit/uploads\";\nimport { currentViewer } from \"#/lib/viewer.server\";\n\nexport const Route = createFileRoute(\"/files/$model/$id/$field/$n\")({\n  server: {\n    handlers: {\n      GET: async ({ request, params }) => {\n        const entry = PICTURES[params.model]?.[params.field];\n        const id = Number(params.id);\n        const n = Number(params.n);\n        if (!entry || !Number.isInteger(id) || !Number.isInteger(n) || n < 0)\n          return new Response(\"Not found\", { status: 404 });\n        const row = (await entry.data.get(await currentViewer(), id)) as Record<\n          string,\n          unknown\n        > | null;\n        const list = row?.[entry.key];\n        const picture = Array.isArray(list) ? (list[n] as Picture | undefined) : undefined;\n        const bytes = picture && readPicture(picture);\n        if (!picture || !bytes) return new Response(\"Not found\", { status: 404 });\n        const tag = pictureTag(picture);\n        const everyone = entry.access.read.public && !entry.access.read.where;\n        const headers = {\n          \"Content-Type\": \"image/webp\",\n          \"X-Content-Type-Options\": \"nosniff\",\n          \"Cache-Control\": everyone ? \"public, max-age=86400\" : \"private, max-age=3600\",\n          ETag: tag,\n        };\n        if (request.headers.get(\"if-none-match\") === tag)\n          return new Response(null, { status: 304, headers });\n        return new Response(new Uint8Array(bytes), { headers });\n      },\n    },\n  },\n});\n",
  "src/routes/files/$model.$id.$field.ts": "// Smithable app kit: a record's picture, loaded through the model's data function, so it can\n// be seen exactly when the record can. Cached by browsers for a day when anyone may read the\n// model (the address changes with the content), privately otherwise.\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { PICTURES } from \"#/generated/pictures\";\nimport { type Picture, pictureTag, readPicture } from \"#/kit/uploads\";\nimport { currentViewer } from \"#/lib/viewer.server\";\n\nexport const Route = createFileRoute(\"/files/$model/$id/$field\")({\n  server: {\n    handlers: {\n      GET: async ({ request, params }) => {\n        const entry = PICTURES[params.model]?.[params.field];\n        const id = Number(params.id);\n        if (!entry || !Number.isInteger(id)) return new Response(\"Not found\", { status: 404 });\n        const row = (await entry.data.get(await currentViewer(), id)) as Record<\n          string,\n          unknown\n        > | null;\n        const picture = row?.[entry.key] as Picture | null | undefined;\n        const bytes = picture && readPicture(picture);\n        if (!picture || !bytes) return new Response(\"Not found\", { status: 404 });\n        const tag = pictureTag(picture);\n        const everyone = entry.access.read.public && !entry.access.read.where;\n        const headers = {\n          \"Content-Type\": \"image/webp\",\n          \"X-Content-Type-Options\": \"nosniff\",\n          \"Cache-Control\": everyone ? \"public, max-age=86400\" : \"private, max-age=3600\",\n          ETag: tag,\n        };\n        if (request.headers.get(\"if-none-match\") === tag)\n          return new Response(null, { status: 304, headers });\n        return new Response(new Uint8Array(bytes), { headers });\n      },\n    },\n  },\n});\n",
  "src/routes/health.ts": "// Smithable app kit: the health endpoint of the deployment contract.\nimport { createFileRoute } from \"@tanstack/react-router\";\nimport { sql } from \"drizzle-orm\";\nimport { db } from \"#/db\";\n\nexport const Route = createFileRoute(\"/health\")({\n  server: {\n    handlers: {\n      GET: () => {\n        db.run(sql`select 1`);\n        return Response.json({ status: \"ok\" });\n      },\n    },\n  },\n});\n",
  "src/styles.css": "/* Smithable app kit: styles built on the theme's tokens in src/theme.css.\n   Colors follow shadcn/ui's token names. */\n@import \"tailwindcss\";\n@import \"./theme.css\";\n/* The app's own styles (never overwritten). Tailwind's styles are in cascade layers, so these\n   rules win over the kit's without !important, wherever they are imported. */\n@import \"./custom/styles.css\";\n\n@custom-variant dark (@media (prefers-color-scheme: dark));\n\n@theme inline {\n  --font-sans: var(--font-body);\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --color-card: var(--card);\n  --color-card-foreground: var(--card-foreground);\n  --color-primary: var(--primary);\n  --color-primary-foreground: var(--primary-foreground);\n  --color-secondary: var(--secondary);\n  --color-secondary-foreground: var(--secondary-foreground);\n  --color-muted: var(--muted);\n  --color-muted-foreground: var(--muted-foreground);\n  --color-accent: var(--accent);\n  --color-accent-foreground: var(--accent-foreground);\n  --color-destructive: var(--destructive);\n  --color-destructive-foreground: var(--destructive-foreground);\n  --color-border: var(--border);\n  --color-input: var(--input);\n  --color-ring: var(--ring);\n  --color-sidebar: var(--sidebar);\n  --color-sidebar-foreground: var(--sidebar-foreground);\n  --color-success: var(--success);\n  --color-success-foreground: var(--success-foreground);\n  --color-warning: var(--warning);\n  --color-warning-foreground: var(--warning-foreground);\n  --color-chart-1: var(--chart-1);\n  --color-chart-2: var(--chart-2);\n  --color-chart-3: var(--chart-3);\n  --color-chart-4: var(--chart-4);\n  --color-chart-5: var(--chart-5);\n  /* Density: h-control, min-h-row, px-cell and p-card follow the theme's density. */\n  --spacing-control: var(--control-height);\n  --spacing-row: var(--row-height);\n  --spacing-cell: var(--cell-padding);\n  --spacing-card: var(--card-padding);\n  --shadow-card: var(--card-shadow);\n  --radius-sm: calc(var(--radius) - 4px);\n  --radius-md: calc(var(--radius) - 2px);\n  --radius-lg: var(--radius);\n  --radius-xl: calc(var(--radius) + 4px);\n}\n\n@layer base {\n  * {\n    @apply border-border;\n  }\n  body {\n    @apply bg-background text-foreground font-sans antialiased;\n  }\n  /* A preset may set tables' numbers in even columns (corporate does). */\n  [data-kit=\"model-table\"] td {\n    font-variant-numeric: var(--table-numbers, normal);\n  }\n}\n",
  "tsconfig.json": "{\n  \"include\": [\"**/*.ts\", \"**/*.tsx\"],\n  \"exclude\": [\"node_modules\", \"dist\"],\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"jsx\": \"react-jsx\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"paths\": { \"#/*\": [\"./src/*\"] },\n    \"lib\": [\"ES2022\", \"DOM\", \"DOM.Iterable\"],\n    \"types\": [\"vite/client\", \"node\"],\n    \"allowImportingTsExtensions\": true,\n    \"verbatimModuleSyntax\": true,\n    \"noEmit\": true,\n    \"skipLibCheck\": true,\n    \"strict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true\n  }\n}\n",
  "tsr.config.json": "{\n  \"routeTreeFileFooter\": [\n    \"import type { getRouter } from './router.tsx'\\nimport type { createStart } from '@tanstack/react-start'\\ndeclare module '@tanstack/react-start' {\\n  interface Register {\\n    ssr: true\\n    router: Awaited<ReturnType<typeof getRouter>>\\n  }\\n}\"\n  ]\n}\n",
  "vite.config.ts": "import tailwindcss from \"@tailwindcss/vite\";\nimport { tanstackStart } from \"@tanstack/react-start/plugin/vite\";\nimport viteReact from \"@vitejs/plugin-react\";\nimport { defineConfig } from \"vite\";\n\nexport default defineConfig({\n  resolve: { tsconfigPaths: true },\n  plugins: [tailwindcss(), tanstackStart(), viteReact()],\n  // The pages and the kit are compiled as the dev server starts, so the libraries they use are\n  // found then. Otherwise the first visit to a page can find a new one: Vite optimizes it and\n  // reloads, and a page loading at that moment fails (\"Failed to fetch dynamically imported\n  // module\"), which a busy machine makes likely.\n  server: { warmup: { clientFiles: [\"./src/routes/**/*.tsx\", \"./src/kit/**/*.tsx\"] } },\n  optimizeDeps: {\n    include: [\n      \"react\",\n      \"react-dom\",\n      \"react-dom/client\",\n      \"react/jsx-runtime\",\n      \"react/jsx-dev-runtime\",\n      \"@tanstack/react-router\",\n      \"lucide-react\",\n      \"clsx\",\n      \"tailwind-merge\",\n      \"class-variance-authority\",\n      \"zod\",\n    ],\n  },\n});\n",
  "vitest.config.ts": "import { rmSync } from \"node:fs\";\nimport { defineConfig } from \"vitest/config\";\n\n// Tests use their own database, never the development data, and start from an empty one.\nrmSync(\"data/test\", { recursive: true, force: true });\n\nexport default defineConfig({\n  resolve: { tsconfigPaths: true },\n  test: {\n    include: [\"src/**/*.test.ts\"],\n    passWithNoTests: true,\n    env: { DATA_DIR: \"data/test\" },\n    // The test files share one database, so they run one after another.\n    fileParallelism: false,\n  },\n});\n",
};
